function normalizeVersionLabel(raw) {
  return String(raw || '').trim().replace(/^v/i, '');
}

function parseVersionParts(raw) {
  const normalized = normalizeVersionLabel(raw);
  const match = normalized.match(/^(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z.-]+))?$/);
  if (!match) return null;
  return {
    major: Number(match[1]),
    minor: Number(match[2]),
    patch: Number(match[3]),
    prerelease: match[4] ? match[4].split('.') : [],
  };
}

function comparePrereleaseParts(a = [], b = []) {
  if (!a.length && !b.length) return 0;
  if (!a.length) return 1;
  if (!b.length) return -1;
  const len = Math.max(a.length, b.length);
  for (let i = 0; i < len; i += 1) {
    const left = a[i];
    const right = b[i];
    if (left == null) return -1;
    if (right == null) return 1;
    const leftNum = /^\d+$/.test(left) ? Number(left) : null;
    const rightNum = /^\d+$/.test(right) ? Number(right) : null;
    if (leftNum != null && rightNum != null) {
      if (leftNum !== rightNum) return leftNum > rightNum ? 1 : -1;
      continue;
    }
    if (leftNum != null) return -1;
    if (rightNum != null) return 1;
    if (left !== right) return left > right ? 1 : -1;
  }
  return 0;
}

function compareVersionLabels(a, b) {
  const left = parseVersionParts(a);
  const right = parseVersionParts(b);
  if (!left || !right) return 0;
  if (left.major !== right.major) return left.major > right.major ? 1 : -1;
  if (left.minor !== right.minor) return left.minor > right.minor ? 1 : -1;
  if (left.patch !== right.patch) return left.patch > right.patch ? 1 : -1;
  return comparePrereleaseParts(left.prerelease, right.prerelease);
}

function pickReleaseDownloadUrl(release) {
  const assets = Array.isArray(release?.assets) ? release.assets.slice() : [];
  assets.sort((a, b) => {
    const rank = item => {
      const name = String(item?.name || '').toLowerCase();
      if (name.endsWith('-setup.exe')) return 0;
      if (name.endsWith('.msi')) return 1;
      if (name.endsWith('.exe')) return 2;
      return 3;
    };
    return rank(a) - rank(b);
  });
  const url = String(assets[0]?.browser_download_url || '').trim();
  return /\.(exe|msi)(?:$|\?)/i.test(url) ? url : '';
}

// DevTools: Ctrl+Shift+I
document.addEventListener('keydown', e => {
  if (e.ctrlKey && e.shiftKey && e.key === 'I') {
    e.preventDefault();
    try {
      const wv = window.__TAURI__?.webviewWindow;
      const win = wv?.getCurrentWebviewWindow?.() ?? wv?.WebviewWindow?.getCurrent?.();
      const openFn = win?.openDevtools ?? win?.openDevTools;
      if (typeof openFn === 'function') openFn.call(win);
    } catch (_) {}
  }
});

function _shutdownFrontendResources() {
  stopNwsApiPolling();

  if (pollTimer !== null) {
    clearInterval(pollTimer);
    pollTimer = null;
  }
  stopRadarSiteStatusPolling();
  if (panePollTimer != null) {
    clearInterval(panePollTimer);
    panePollTimer = null;
  }
  if (wxwiseChaserPollTimer != null) {
    clearInterval(wxwiseChaserPollTimer);
    wxwiseChaserPollTimer = null;
  }
  if (roChaserPollTimer != null) {
    clearInterval(roChaserPollTimer);
    roChaserPollTimer = null;
  }
  if (mpingPollTimer != null) {
    clearInterval(mpingPollTimer);
    mpingPollTimer = null;
  }
  if (metarPollTimer != null) {
    clearInterval(metarPollTimer);
    metarPollTimer = null;
  }
  if (spotterLocationsPollTimer != null) {
    clearInterval(spotterLocationsPollTimer);
    spotterLocationsPollTimer = null;
  }

  _clearCameraStartupRetry();
  closeCamera();

  if (_wiseWorker) {
    _wiseWorker.terminate();
    _wiseWorker = null;
  }
  _wiseWorkerPending.clear();

  if (_trafficCameraWorker) {
    _trafficCameraWorker.terminate();
    _trafficCameraWorker = null;
  }
  _trafficCameraWorkerPending.clear();
}

window.addEventListener('beforeunload', () => {
  _shutdownFrontendResources();
  try {
    invoke('stop_nwws_bridge').catch(() => {});
  } catch (_) {}
});

