Object.assign(STATIONS, HAWAII_STATIONS, TERMINAL_STATIONS);

const TERMINAL_STATION_IDS = new Set(Object.keys(TERMINAL_STATIONS));
const HAWAII_STATION_IDS = new Set(Object.keys(HAWAII_STATIONS));
const STATION_SOURCE_OVERRIDES = Object.freeze({
  ...Object.fromEntries(Object.keys(HAWAII_STATIONS).map(id => [id, { source: 'tgftp', kind: 'wsr' }])),
  ...Object.fromEntries(Object.keys(TERMINAL_STATIONS).map(id => [id, { source: 'tgftp', kind: 'tdwr' }])),
});

const STATION_ID_ALIASES = Object.freeze({
  KLIX: 'KHDC',
});

const STATION_ID_DISPLAY = Object.freeze({
  // keep hook for future display-only remaps
});

function canonicalStationId(id) {
  const sid = String(id || '').toUpperCase();
  return STATION_ID_ALIASES[sid] || sid;
}

function displayStationId(id) {
  const sid = String(id || '').toUpperCase();
  return STATION_ID_DISPLAY[sid] || sid;
}

function stationSource(id) {
  const sid = canonicalStationId(id);
  return STATION_SOURCE_OVERRIDES[sid]?.source || 's3';
}

function stationKind(id) {
  const sid = canonicalStationId(id);
  return STATION_SOURCE_OVERRIDES[sid]?.kind || 'wsr';
}

function isTerminalStation(id) {
  return stationKind(id) === 'tdwr';
}

function _stationSupportsProcessedWise(id) {
  const sid = canonicalStationId(id);
  if (!sid) return false;
  // Terminal stations (TDWR) now support WeatherWise processed data
  return stationSource(sid) === 's3' || isTerminalStation(sid);
}

const VIEWABLE_STATION_IDS = Object.freeze(
  Object.keys(STATIONS).filter(id => _stationSupportsProcessedWise(id)),
);
const VIEWABLE_STATIONS = Object.freeze(
  Object.fromEntries(VIEWABLE_STATION_IDS.map(id => [id, STATIONS[id]])),
);

const RADAR_SITE_DEFAULT_WSR_COLOR = '#FFFFFF';
const RADAR_SITE_DEFAULT_TERMINAL_COLOR = '#FFFFFF';
const RADAR_SITE_LEGACY_TERMINAL_COLOR = '#6FD2FF';
const radarSiteStatusById = new Map();
let radarSiteStatusTimer = null;
let radarSiteStatusLoading = false;
let radarSiteStatusLastFetchMs = 0;

function _normalizeRadarSiteColor(color, fallback) {
  return _normalizeSpcHex(color) || fallback;
}

function _parseHexColorRgb(color, fallback = '#FFFFFF') {
  const normalized = _normalizeRadarSiteColor(color, fallback) || fallback;
  const raw = normalized.slice(1);
  return {
    r: parseInt(raw.slice(0, 2), 16),
    g: parseInt(raw.slice(2, 4), 16),
    b: parseInt(raw.slice(4, 6), 16),
  };
}

function _mixRgb(a, b, t = 0.5) {
  const ratio = Math.max(0, Math.min(1, Number(t) || 0));
  return {
    r: Math.round(a.r + ((b.r - a.r) * ratio)),
    g: Math.round(a.g + ((b.g - a.g) * ratio)),
    b: Math.round(a.b + ((b.b - a.b) * ratio)),
  };
}

function _rgbCss(rgb, alpha = 1) {
  const r = Math.max(0, Math.min(255, Math.round(Number(rgb?.r) || 0)));
  const g = Math.max(0, Math.min(255, Math.round(Number(rgb?.g) || 0)));
  const b = Math.max(0, Math.min(255, Math.round(Number(rgb?.b) || 0)));
  if (alpha >= 1) return `rgb(${r}, ${g}, ${b})`;
  return `rgba(${r}, ${g}, ${b}, ${Math.max(0, Math.min(1, Number(alpha) || 0))})`;
}

function _radarSiteConfiguredColorForKind(kind) {
  return String(kind || '').trim().toLowerCase() === 'tdwr'
    ? radarSitesTerminalColor
    : radarSitesWsrColor;
}

function stationDotColor(id) {
  return _radarSiteConfiguredColorForKind(stationKind(id));
}

function _radarSiteStatusId(rawId) {
  const raw = String(rawId || '').trim().toUpperCase();
  if (!raw) return '';
  const canonical = canonicalStationId(raw);
  if (VIEWABLE_STATIONS[canonical]) return canonical;
  const withK = raw.length === 3 ? `K${raw}` : raw;
  return VIEWABLE_STATIONS[withK] ? withK : canonical;
}

function _radarSiteStatusText(props) {
  const rdaProps = props?.rda?.properties || {};
  return [
    rdaProps.operabilityStatus,
    rdaProps.status,
    rdaProps.mode,
    rdaProps.alarmSummary,
  ].map(v => String(v || '').trim()).filter(Boolean).join(' | ');
}

function _radarSiteStatusIsOffline(props) {
  const rdaProps = props?.rda?.properties || {};
  const status = String(rdaProps.status || '').trim();
  const mode = String(rdaProps.mode || '').trim();
  const statusText = _radarSiteStatusText(props);
  if (/offline|off-line|down|unavailable|inoperable|failed|not reporting|no data/i.test(statusText)) return true;
  // NWS reports many healthy radars as "Maintenance Action Required/Mandatory".
  // Those are still usable when status/mode are good and latency is current.
  if (status && !/^operate$/i.test(status)) return true;
  if (mode && !/^operational$/i.test(mode)) return true;
  const lastTime = Date.parse(props?.latency?.levelTwoLastReceivedTime || props?.rda?.timestamp || '');
  return Number.isFinite(lastTime)
    && Date.now() >= lastTime
    && (Date.now() - lastTime) > RADAR_SITE_STALE_MS;
}

function _isRadarSiteOffline(id) {
  return radarSiteStatusById.get(canonicalStationId(id))?.offline === true;
}

function _stationDotColorForStatus(id) {
  return _isRadarSiteOffline(id) ? RADAR_SITE_OFFLINE_COLOR : stationDotColor(id);
}

async function refreshRadarSiteStatuses(force = false) {
  const now = Date.now();
  if (radarSiteStatusLoading) return;
  if (!force && radarSiteStatusLastFetchMs && (now - radarSiteStatusLastFetchMs) < RADAR_SITE_STATUS_REFRESH_MS) return;
  radarSiteStatusLoading = true;
  try {
    const data = await _fetchGeoJsonViaTauri(RADAR_SITE_STATUS_URL, {
      timeoutMs: 10000,
      preferDirect: false,
    });
    const next = new Map();
    const features = Array.isArray(data?.features) ? data.features : [];
    for (const feature of features) {
      const props = feature?.properties || {};
      const id = _radarSiteStatusId(props.id || props.stationId || props.siteId);
      if (!id || !VIEWABLE_STATIONS[id]) continue;
      next.set(id, {
        offline: _radarSiteStatusIsOffline(props),
        label: _radarSiteStatusText(props),
        fetchedAt: now,
      });
    }
    radarSiteStatusById.clear();
    next.forEach((value, key) => radarSiteStatusById.set(key, value));
    radarSiteStatusLastFetchMs = now;
    window.__radarSiteStatus = () => Object.fromEntries(radarSiteStatusById.entries());
    _refreshStationSourceData();
  } catch (err) {
    console.warn('[Radar sites] status refresh failed', err?.message || err);
  } finally {
    radarSiteStatusLoading = false;
  }
}

function startRadarSiteStatusPolling() {
  if (radarSiteStatusTimer != null) return;
  void refreshRadarSiteStatuses(true);
  radarSiteStatusTimer = setInterval(() => {
    void refreshRadarSiteStatuses(false);
  }, RADAR_SITE_STATUS_REFRESH_MS);
}

function stopRadarSiteStatusPolling() {
  if (radarSiteStatusTimer != null) clearInterval(radarSiteStatusTimer);
  radarSiteStatusTimer = null;
}

// Derived products computed in JS from base WISE products (no separate server folder).
const DERIVED_RADAR_PRODUCTS = Object.freeze({
  PTDS: { label: 'Probability of Tornado Debris Signature', baseProducts: ['REF', 'CC'], optionalProducts: ['SRV'] },
});

function isDerivedRadarProduct(family) {
  return !!DERIVED_RADAR_PRODUCTS[String(family || '').trim().toUpperCase()];
}

function supportedL3FamiliesForStation(id) {
  if (!_stationSupportsProcessedWise(id)) return [];
  // TDWR stations support a subset of families; derived products not applicable there
  if (isTerminalStation(id)) return [...TDWR_WISE_FAMILIES];
  return [...PROCESSED_WISE_FAMILIES, ...Object.keys(DERIVED_RADAR_PRODUCTS)];
}

const TDWR_FAMILY_TILTS = Object.freeze({
  REF: ['0.5'],
  VEL: ['0.5', '1.5', '2.4'],
  ET: ['0.5'],
});

function _processedWiseSupportedTilts(family) {
  const f = String(family || '').trim().toUpperCase();
  const tilts = PROCESSED_WISE_FAMILY_TILTS[f];
  return Array.isArray(tilts) && tilts.length ? [...tilts] : [];
}

function _tdwrWiseSupportedTilts(family) {
  const f = String(family || '').trim().toUpperCase();
  const tilts = TDWR_WISE_FAMILY_TILTS[f];
  return Array.isArray(tilts) && tilts.length ? [...tilts] : ['0.5'];
}

function _normalizeProcessedWiseTilt(family, tilt) {
  const f = String(family || '').trim().toUpperCase();
  const normalized = normalizeTilt(tilt || '0.5');
  const allowed = _processedWiseSupportedTilts(f);
  return allowed.includes(normalized) ? normalized : (allowed[0] || '0.5');
}

function _normalizeProcessedWiseTiltForStation(stationId, family, tilt) {
  if (isTerminalStation(stationId)) {
    const f = String(family || '').trim().toUpperCase();
    const normalized = normalizeTilt(tilt || '0.5');
    const allowed = _tdwrWiseSupportedTilts(f);
    return allowed.includes(normalized) ? normalized : (allowed[0] || '0.5');
  }
  return _normalizeProcessedWiseTilt(family, tilt);
}

function supportedL3TiltsForStationFamily(id, family) {
  const f = String(family || 'REF').toUpperCase();
  if (!_stationSupportsProcessedWise(id)) return ['0.5'];
  
  // TDWR stations have different tilt options
  if (isTerminalStation(id)) {
    return _tdwrWiseSupportedTilts(f);
  }
  
  if (PROCESSED_WISE_FAMILY_SET.has(f)) {
    return _processedWiseSupportedTilts(f);
  }
  if (isDerivedRadarProduct(f)) {
    return _processedWiseSupportedTilts('REF');
  }
  return ['0.5'];
}

function normalizeTiltForStationFamily(id, family, tilt) {
  const allowed = supportedL3TiltsForStationFamily(id, family);
  const nextTilt = normalizeTilt(tilt);
  return allowed.includes(nextTilt) ? nextTilt : (allowed[0] || '0.5');
}

// S3 helpers
function enc(s) { return encodeURIComponent(s); }

function flatDate(d) {
  return d.toISOString().slice(0, 10).replace(/-/g, '_');
}

function flatDateTime(d) {
  // "2026-03-01T02:23:17" ? "2026_03_01_02_23_17"
  return d.toISOString().slice(0, 19).replace('T', '_').replace(/-/g, '_').replace(/:/g, '_');
}

async function findRecentKeys(stationId, family, tilt, maxFrames = 5) {
  if (_canUseProcessedWise(stationId, family, tilt)) {
    const result = await invoke('list_wise_frames', {
      station: canonicalStationId(stationId),
      family:  String(family || '').trim().toUpperCase(),
      tilt:    normalizeTilt(tilt || '0.5'),
      maxFrames: Math.max(1, Math.round(Number(maxFrames) || 5)),
    });
    return (Array.isArray(result?.frames) ? result.frames : [])
      .map(fileName => _buildProcessedWiseMeta(stationId, family, result.tilt || tilt, fileName))
      .filter(Boolean);
  }
  const res = await resolveL3Selection(stationId, family, tilt, maxFrames);
  return Array.isArray(res?.history) ? res.history : [];
}

function parseKeys(xml) {
  return [...xml.matchAll(/<Key>([^<]+)<\/Key>/g)]
    .map(m => m[1])
    .filter(k => !k.endsWith('/'));
}

function parseNextContinuationToken(xml) {
  const m = xml.match(/<NextContinuationToken>([^<]+)<\/NextContinuationToken>/);
  return m ? m[1] : null;
}

function parseCommonPrefixes(xml) {
  return [...xml.matchAll(/<CommonPrefixes>\s*<Prefix>([^<]+)<\/Prefix>\s*<\/CommonPrefixes>/g)]
    .map(m => m[1]);
}

function parseKeyTimestampMs(key) {
  if (key.startsWith('L2:')) {
    const ts = key.split(':')[3];  // "20260228-062733"
    if (!ts) return NaN;
    const m = ts.match(/^(\d{4})(\d{2})(\d{2})-(\d{2})(\d{2})(\d{2})$/);
    if (!m) return NaN;
    return Date.UTC(+m[1], +m[2] - 1, +m[3], +m[4], +m[5], +m[6]);
  }
  if (key.startsWith('TGFTP:')) {
    const ts = key.split(':')[4];
    if (!ts) return NaN;
    const m = ts.match(/^(\d{4})(\d{2})(\d{2})-(\d{2})(\d{2})(\d{2})$/);
    if (!m) return NaN;
    return Date.UTC(+m[1], +m[2] - 1, +m[3], +m[4], +m[5], +m[6]);
  }
  if (key.startsWith('WISE:')) {
    const fileToken = key.split(':').slice(4).join(':');
    const fileName = decodeURIComponent(fileToken || '');
    const m = fileName.match(/(\d{4})_(\d{2})_(\d{2})_(\d{2})_(\d{2})(?:_(\d{2}))?\.wise$/i);
    if (!m) return NaN;
    return Date.UTC(+m[1], +m[2] - 1, +m[3], +m[4], +m[5], +(m[6] || 0));
  }
  const m = key.match(/_(\d{4})_(\d{2})_(\d{2})_(\d{2})_(\d{2})_(\d{2})$/);
  if (!m) return NaN;
  return Date.UTC(+m[1], +m[2] - 1, +m[3], +m[4], +m[5], +m[6]);
}

function id3(stationId) {
  const canonicalId = canonicalStationId(stationId);
  const sid = canonicalId.startsWith('K') ? canonicalId.slice(1) : canonicalId;
  return sid;
}

async function s3ListPage(prefix, { startAfter = '', continuationToken = '', maxKeys = 1000 } = {}) {
  try {
    const res = await invoke('l3_list_page', {
      prefix,
      startAfter: startAfter || null,
      continuationToken: continuationToken || null,
      maxKeys,
    });
    return {
      keys: Array.isArray(res?.keys) ? res.keys : [],
      next: typeof res?.next === 'string' && res.next ? res.next : null,
    };
  } catch (_) {
    return { keys: [], next: null };
  }
}

async function findNewestKeySince(prefix, startAfter, maxPages = 40) {
  let newest = null;
  let token = '';
  let pages = 0;

  while (pages < maxPages) {
    const { keys, next } = await s3ListPage(prefix, {
      startAfter,
      continuationToken: token,
      maxKeys: 1000,
    });

    if (keys.length) newest = keys[keys.length - 1];
    if (!next) break;

    token = next;
    pages += 1;
  }

  return newest;
}

async function listAvailableProducts(stationId) {
  const sid = id3(stationId);
  const prefix = `${sid}_`;

  const products = new Set();
  let token = '';
  for (let i = 0; i < 12; i += 1) {
    const { keys, next } = await s3ListPage(prefix, { continuationToken: token, maxKeys: 1000 });
    keys.forEach(k => {
      const p = k.split('_')[1];
      if (p) products.add(p);
    });
    if (!next) break;
    token = next;
  }

  return [...products].sort();
}

