function _hasTvsSignal(value) {
  const s = String(value ?? '').trim().toUpperCase();
  return !!s && s !== 'NONE' && s !== '0' && s !== 'FALSE' && s !== 'NO';
}

function _tvsThreatBucket(props) {
  const meso = Number.parseInt(String(props?.meso ?? ''), 10) || 0;
  const maxDbz = Number.parseFloat(String(props?.max_dbz ?? ''));
  const bonus = maxDbz > 60 ? 5 : (maxDbz > 55 ? 3 : (maxDbz > 50 ? 1 : 0));
  const score = meso + bonus;
  if (score >= 18) return 'PINK';
  if (score >= 10) return 'RED';
  if (score >= 5) return 'ORANGE';
  if (score >= 2) return 'YELLOW';
  return 'GREEN';
}

function _buildTvsGeoJson(raw) {
  const out = [];
  const features = Array.isArray(raw?.features) ? raw.features : [];
  for (const feature of features) {
    const geom = feature?.geometry;
    if (!geom || geom.type !== 'Point' || !Array.isArray(geom.coordinates) || geom.coordinates.length < 2) continue;
    const p = feature?.properties || {};
    if (!_hasTvsSignal(p.tvs)) continue;
    const nexrad = String(p.nexrad || '').trim();
    const stormId = String(p.storm_id || '').trim();
    const azimuth = Number(p.azimuth);
    const rangeNm = Number(p.range);
    const meso = String(p.meso ?? '').trim();
    const posh = Number(p.posh);
    const poh = Number(p.poh);
    const maxSize = Number(p.max_size);
    const vil = Number(p.vil);
    const drct = Number(p.drct);
    const sknt = Number(p.sknt);
    const maxDbz = Number(p.max_dbz);
    const maxDbzHeight = Number(p.max_dbz_height);
    const top = Number(p.top);
    const bucket = _tvsThreatBucket(p);
    const motion = Number.isFinite(drct) && Number.isFinite(sknt)
      ? `${drct}° @ ${sknt} kt`
      : '--';
    out.push({
      type: 'Feature',
      geometry: { type: 'Point', coordinates: [geom.coordinates[0], geom.coordinates[1]] },
      properties: {
        _label: 'TVS',
        _nexrad: nexrad,
        _stormId: stormId,
        _tvs: String(p.tvs || '').trim(),
        _valid: String(p.valid || '').trim(),
        _azimuth: azimuth,
        _range: rangeNm,
        _meso: meso || '--',
        _posh: posh,
        _poh: poh,
        _maxSize: maxSize,
        _vil: vil,
        _maxDbz: maxDbz,
        _maxDbzHeight: maxDbzHeight,
        _top: top,
        _drct: drct,
        _sknt: sknt,
        _motion: motion,
        _tvsBucket: bucket,
        _tvsIcon: TVS_ICON_BY_BUCKET[bucket] || TVS_ICON_BY_BUCKET.YELLOW,
      },
    });
  }
  return { type: 'FeatureCollection', features: out };
}

// ── Report / mPING custom icon images ─────────────────────────────────────────

function _mkIconCtx(size) {
  const canvas = document.createElement('canvas');
  canvas.width = size; canvas.height = size;
  const ctx = canvas.getContext('2d');
  if (!ctx) return null;
  return { canvas, ctx, s: size, c: size / 2, R: size * 0.37 };
}

// Draw background circle + border, then set up a scaled/centered transform so
// the caller's shape code fills roughly the inner 58% of the canvas.
function _iconBeginCircleBg(ctx, s, c, bgColor, borderColor = 'rgba(0,0,0,0.72)', borderWidth = 2.5) {
  const bgR = s * 0.44;
  ctx.beginPath(); ctx.arc(c, c, bgR, 0, Math.PI * 2);
  ctx.fillStyle = bgColor; ctx.fill();
  ctx.strokeStyle = borderColor; ctx.lineWidth = borderWidth; ctx.stroke();
  // Scale inner drawing to 58% so shapes don't touch the edge
  ctx.save();
  ctx.translate(c, c);
  ctx.scale(0.58, 0.58);
  ctx.translate(-c, -c);
}

function _lsrIconPaintSetup(ctx, fill, stroke = 'rgba(0,0,0,0.82)', lineWidth = 2.4) {
  ctx.fillStyle = fill;
  ctx.strokeStyle = stroke;
  ctx.lineWidth = lineWidth;
  ctx.lineJoin = 'round';
  ctx.lineCap = 'round';
}

function _lsrIconCirclePath(ctx, c, r) {
  ctx.beginPath();
  ctx.arc(c, c, r, 0, Math.PI * 2);
}

function _lsrIconDiamondPath(ctx, c, r) {
  ctx.beginPath();
  ctx.moveTo(c, c - r);
  ctx.lineTo(c + r, c);
  ctx.lineTo(c, c + r);
  ctx.lineTo(c - r, c);
  ctx.closePath();
}

function _lsrIconSquarePath(ctx, c, r) {
  ctx.beginPath();
  ctx.rect(c - r, c - r, r * 2, r * 2);
}

function _lsrIconTrianglePath(ctx, c, r, inverted = false) {
  const topY = inverted ? c + r : c - r;
  const bottomY = inverted ? c - r : c + r;
  ctx.beginPath();
  ctx.moveTo(c, topY);
  ctx.lineTo(c + r * 0.92, bottomY);
  ctx.lineTo(c - r * 0.92, bottomY);
  ctx.closePath();
}

function _lsrIconPinPath(ctx, c, r) {
  ctx.beginPath();
  ctx.moveTo(c, c - r);
  ctx.bezierCurveTo(c + r * 0.92, c - r, c + r * 0.98, c + r * 0.04, c, c + r * 1.24);
  ctx.bezierCurveTo(c - r * 0.98, c + r * 0.04, c - r * 0.92, c - r, c, c - r);
  ctx.closePath();
}

function _createLsrIconImage(category) {
  const ic = _mkIconCtx(40);
  if (!ic) return null;
  const { ctx, s, c, R } = ic;
  ctx.clearRect(0, 0, s, s);
  ctx.fillStyle = '#ffffff';
  ctx.strokeStyle = '#ffffff';
  ctx.lineWidth = 2.2;
  ctx.lineJoin = 'round';
  ctx.lineCap = 'round';

  switch (category) {
    case 'TORNADO': {
      _lsrIconTrianglePath(ctx, c, R * 1.06, true);
      ctx.fill();
      break;
    }
    case 'HAIL': {
      _lsrIconDiamondPath(ctx, c, R * 1.00);
      ctx.fill();
      break;
    }
    case 'WIND': {
      _lsrIconTrianglePath(ctx, c, R * 1.04, false);
      ctx.fill();
      break;
    }
    case 'WINTER': {
      _lsrIconDiamondPath(ctx, c, R * 1.00);
      ctx.fill();
      break;
    }
    case 'ICE': {
      _lsrIconSquarePath(ctx, c, R * 0.86);
      ctx.fill();
      break;
    }
    case 'FLOOD': {
      _lsrIconCirclePath(ctx, c, R * 0.92);
      ctx.fill();
      break;
    }
    case 'MARINE': {
      _lsrIconDiamondPath(ctx, c, R * 1.00);
      ctx.fill();
      break;
    }
    case 'TSTM': {
      _lsrIconSquarePath(ctx, c, R * 0.86);
      ctx.fill();
      break;
    }
    case 'FIRE': {
      _lsrIconSquarePath(ctx, c, R * 0.86);
      ctx.fill();
      break;
    }
    case 'FOG': {
      _lsrIconSquarePath(ctx, c, R * 0.86);
      ctx.fill();
      break;
    }
    default: {
      _lsrIconPinPath(ctx, c, R * 0.96);
      ctx.fill();
      break;
    }
  }
  return ic.ctx.getImageData(0, 0, s, s);
}

function _createMpingIconImage(category) {
  const colorMap = {
    'Rain/Snow': '#4499ff', 'Hail': '#00e5ff', 'Flood': '#00cc44',
    'Wind Damage': '#ffdd00', 'Storm Damage': '#ff8800',
    'Fog/Mist/Dust': '#aabbcc', 'Blowing Snow / Reduced Visibility': '#ddddff',
    'Freezing Rain/Drizzle': '#88aaff', 'Ice Pellets/Sleet': '#99ccff',
    'Tornado': '#ff3333', 'None': '#555555', 'Test': '#333333',
  };
  const color = colorMap[category] || '#888888';
  const ic = _mkIconCtx(40);
  if (!ic) return null;
  const { ctx, s, c, R } = ic;
  ctx.clearRect(0, 0, s, s);
  _iconBeginCircleBg(ctx, s, c, 'rgba(20,20,20,0.78)');

  switch (category) {
    case 'Tornado': {
      ctx.fillStyle = color; ctx.strokeStyle = 'rgba(0,0,0,0.72)'; ctx.lineWidth = 2.8; ctx.lineJoin = 'round';
      ctx.beginPath(); ctx.ellipse(c, c * 0.54, R * 0.82, R * 0.3, 0, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(c - R * 0.82, c * 0.54); ctx.lineTo(c - R * 0.16, s * 0.87);
      ctx.lineTo(c, s * 0.93); ctx.lineTo(c + R * 0.16, s * 0.87); ctx.lineTo(c + R * 0.82, c * 0.54);
      ctx.closePath(); ctx.fill(); ctx.stroke();
      break;
    }
    case 'Rain/Snow': {
      ctx.fillStyle = color; ctx.strokeStyle = 'rgba(0,0,0,0.62)'; ctx.lineWidth = 2.5;
      ctx.beginPath();
      ctx.moveTo(c, s * 0.1);
      ctx.bezierCurveTo(c + R * 0.92, c * 0.8, c + R * 0.92, s * 0.74, c, s * 0.9);
      ctx.bezierCurveTo(c - R * 0.92, s * 0.74, c - R * 0.92, c * 0.8, c, s * 0.1);
      ctx.fill(); ctx.stroke();
      ctx.fillStyle = 'rgba(255,255,255,0.45)';
      ctx.beginPath(); ctx.ellipse(c - R * 0.2, c * 0.58, R * 0.18, R * 0.12, -0.5, 0, Math.PI * 2); ctx.fill();
      break;
    }
    case 'Hail': {
      ctx.fillStyle = color; ctx.strokeStyle = 'rgba(0,0,0,0.65)'; ctx.lineWidth = 2.8;
      ctx.beginPath(); ctx.arc(c, c, R, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
      ctx.fillStyle = 'rgba(255,255,255,0.5)';
      ctx.beginPath(); ctx.ellipse(c - R * 0.25, c - R * 0.25, R * 0.28, R * 0.18, -0.6, 0, Math.PI * 2); ctx.fill();
      ctx.strokeStyle = 'rgba(0,0,0,0.3)'; ctx.lineWidth = 1.5;
      ctx.beginPath(); ctx.arc(c, c, R * 0.55, 0, Math.PI * 2); ctx.stroke();
      break;
    }
    case 'Flood': {
      ctx.fillStyle = color; ctx.strokeStyle = 'rgba(0,0,0,0.65)'; ctx.lineWidth = 2.4;
      ctx.beginPath();
      ctx.moveTo(0, c);
      ctx.quadraticCurveTo(s * 0.25, c - R * 0.66, c, c);
      ctx.quadraticCurveTo(s * 0.75, c + R * 0.66, s, c);
      ctx.lineTo(s, s); ctx.lineTo(0, s); ctx.closePath();
      ctx.fill(); ctx.stroke();
      break;
    }
    case 'Wind Damage': {
      ctx.fillStyle = color; ctx.strokeStyle = 'rgba(0,0,0,0.65)'; ctx.lineWidth = 2.2; ctx.lineJoin = 'round';
      ctx.beginPath();
      ctx.moveTo(s * 0.88, c);
      ctx.lineTo(s * 0.56, c - R * 0.52);
      ctx.lineTo(s * 0.56, c - R * 0.2);
      ctx.lineTo(s * 0.10, c - R * 0.2);
      ctx.lineTo(s * 0.10, c + R * 0.2);
      ctx.lineTo(s * 0.56, c + R * 0.2);
      ctx.lineTo(s * 0.56, c + R * 0.52);
      ctx.closePath(); ctx.fill(); ctx.stroke();
      break;
    }
    case 'Storm Damage': {
      ctx.fillStyle = color; ctx.strokeStyle = 'rgba(0,0,0,0.65)'; ctx.lineWidth = 2.5; ctx.lineJoin = 'round';
      ctx.beginPath();
      ctx.moveTo(s * 0.60, s * 0.08); ctx.lineTo(s * 0.34, s * 0.48);
      ctx.lineTo(s * 0.52, s * 0.48); ctx.lineTo(s * 0.38, s * 0.92);
      ctx.lineTo(s * 0.70, s * 0.40); ctx.lineTo(s * 0.52, s * 0.40);
      ctx.closePath(); ctx.fill(); ctx.stroke();
      break;
    }
    case 'Fog/Mist/Dust': {
      ctx.lineCap = 'round'; ctx.lineWidth = 4.2;
      [-R * 0.47, 0, R * 0.47].forEach((dy, i) => {
        const xs = i === 1 ? R * 0.2 : 0;
        ctx.strokeStyle = color;
        ctx.beginPath(); ctx.moveTo(s * 0.1 + xs, c + dy); ctx.lineTo(s * 0.9 - xs, c + dy); ctx.stroke();
      });
      break;
    }
    case 'Blowing Snow / Reduced Visibility': {
      ctx.lineCap = 'round';
      for (let i = 0; i < 4; i++) {
        const a = (i / 4) * Math.PI * 2;
        ctx.strokeStyle = color; ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.moveTo(c - R * 0.88 * Math.cos(a), c - R * 0.88 * Math.sin(a));
        ctx.lineTo(c + R * 0.88 * Math.cos(a), c + R * 0.88 * Math.sin(a));
        ctx.stroke();
        const bx = c + R * 0.55 * Math.cos(a), by = c + R * 0.55 * Math.sin(a), ba = a + Math.PI / 2, bl = R * 0.22;
        ctx.lineWidth = 1.8;
        ctx.beginPath();
        ctx.moveTo(bx + bl * Math.cos(ba), by + bl * Math.sin(ba));
        ctx.lineTo(bx - bl * Math.cos(ba), by - bl * Math.sin(ba));
        ctx.stroke();
      }
      ctx.fillStyle = color; ctx.beginPath(); ctx.arc(c, c, R * 0.17, 0, Math.PI * 2); ctx.fill();
      break;
    }
    case 'Freezing Rain/Drizzle': {
      ctx.fillStyle = color; ctx.strokeStyle = 'rgba(0,0,0,0.62)'; ctx.lineWidth = 2.2;
      ctx.beginPath();
      ctx.moveTo(c, s * 0.1);
      ctx.bezierCurveTo(c + R * 0.88, c * 0.8, c + R * 0.88, s * 0.74, c, s * 0.9);
      ctx.bezierCurveTo(c - R * 0.88, s * 0.74, c - R * 0.88, c * 0.8, c, s * 0.1);
      ctx.fill(); ctx.stroke();
      ctx.strokeStyle = 'rgba(255,255,255,0.75)'; ctx.lineWidth = 1.5; ctx.lineCap = 'round';
      ctx.beginPath(); ctx.moveTo(c - R * 0.2, s * 0.24); ctx.lineTo(c + R * 0.2, s * 0.34); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(c, s * 0.19); ctx.lineTo(c, s * 0.39); ctx.stroke();
      break;
    }
    case 'Ice Pellets/Sleet': {
      ctx.fillStyle = color; ctx.strokeStyle = 'rgba(0,0,0,0.6)'; ctx.lineWidth = 2.2;
      [[c - R * 0.46, c - R * 0.36], [c + R * 0.46, c - R * 0.36], [c, c + R * 0.46]].forEach(([x, y]) => {
        ctx.beginPath(); ctx.arc(x, y, R * 0.38, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
      });
      break;
    }
    case 'None': {
      ctx.fillStyle = color; ctx.strokeStyle = 'rgba(0,0,0,0.5)'; ctx.lineWidth = 2.5;
      ctx.beginPath(); ctx.arc(c, c, R, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
      ctx.strokeStyle = 'rgba(255,255,255,0.55)'; ctx.lineWidth = 3; ctx.lineCap = 'round';
      ctx.beginPath(); ctx.moveTo(c - R * 0.54, c); ctx.lineTo(c + R * 0.54, c); ctx.stroke();
      break;
    }
    case 'Test': {
      ctx.fillStyle = color; ctx.strokeStyle = 'rgba(0,0,0,0.5)'; ctx.lineWidth = 2.5; ctx.lineJoin = 'round';
      const sq = R * 0.84;
      ctx.beginPath(); ctx.rect(c - sq, c - sq, sq * 2, sq * 2); ctx.fill(); ctx.stroke();
      break;
    }
    default: {
      ctx.fillStyle = color; ctx.strokeStyle = 'rgba(0,0,0,0.55)'; ctx.lineWidth = 2.8;
      ctx.beginPath(); ctx.arc(c, c, R, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
      break;
    }
  }
  ctx.restore();
  return ic.ctx.getImageData(0, 0, s, s);
}

const LSR_ICON_IMAGE_IDS = {
  TORNADO: 'rdr-lsr-tornado', HAIL: 'rdr-lsr-hail', WIND: 'rdr-lsr-wind',
  WINTER: 'rdr-lsr-winter', ICE: 'rdr-lsr-ice', FLOOD: 'rdr-lsr-flood',
  TSTM: 'rdr-lsr-tstorm', MARINE: 'rdr-lsr-marine', FIRE: 'rdr-lsr-fire',
  FOG: 'rdr-lsr-fog', OTHER: 'rdr-lsr-other',
};
const LSR_ICON_IMAGE_EXPR = ['match', ['get', '_category'],
  ...Object.entries(LSR_ICON_IMAGE_IDS).flatMap(([k, v]) => [k, v]),
  LSR_ICON_IMAGE_IDS.OTHER,
];
const MPING_STORM_ICON_EXPR = ['match', ['get', '_markerCategory'],
  ...Object.entries(LSR_ICON_IMAGE_IDS).flatMap(([k, v]) => [k, v]),
  LSR_ICON_IMAGE_IDS.OTHER,
];
const STORM_REPORT_ICON_SIZE_EXPR = ['interpolate', ['linear'], ['zoom'], 3, 0.78, 6, 0.90, 10, 1.06, 13, 1.18];
const STORM_REPORT_TEXT_SIZE_EXPR = ['interpolate', ['linear'], ['zoom'], 3, 0, 4, 0, 5, 8, 8, 9, 11, 10.5, 13, 11.5];

const MPING_ICON_IMAGE_IDS = {
  'Rain/Snow': 'rdr-mping-rain', 'Hail': 'rdr-mping-hail', 'Flood': 'rdr-mping-flood',
  'Wind Damage': 'rdr-mping-wind', 'Storm Damage': 'rdr-mping-storm',
  'Fog/Mist/Dust': 'rdr-mping-fog', 'Blowing Snow / Reduced Visibility': 'rdr-mping-snow',
  'Freezing Rain/Drizzle': 'rdr-mping-fzra', 'Ice Pellets/Sleet': 'rdr-mping-sleet',
  'Tornado': 'rdr-mping-tornado', 'None': 'rdr-mping-none', 'Test': 'rdr-mping-test',
};
const MPING_ICON_IMAGE_EXPR = ['match', ['get', 'category'],
  ...Object.entries(MPING_ICON_IMAGE_IDS).flatMap(([k, v]) => [k, v]),
  'rdr-mping-none',
];

function _ensureLsrIconImages(m) {
  for (const [cat, id] of Object.entries(LSR_ICON_IMAGE_IDS)) {
    if (!m.hasImage(id)) { const img = _createLsrIconImage(cat); if (img) m.addImage(id, img, { pixelRatio: 2, sdf: true }); }
  }
}

function _ensureMpingIconImages(m) {
  for (const [cat, id] of Object.entries(MPING_ICON_IMAGE_IDS)) {
    if (!m.hasImage(id)) { const img = _createMpingIconImage(cat); if (img) m.addImage(id, img, { pixelRatio: 2 }); }
  }
}

function _createTvsTriangleIconImage(strokeColor) {
  const size = 40;
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');
  if (!ctx) return null;

  ctx.clearRect(0, 0, size, size);
  ctx.beginPath();
  ctx.moveTo(size * 0.5, size * 0.78);
  ctx.lineTo(size * 0.2, size * 0.28);
  ctx.lineTo(size * 0.8, size * 0.28);
  ctx.closePath();
  ctx.lineWidth = 5.0;
  ctx.lineJoin = 'round';
  ctx.strokeStyle = '#000000';
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(size * 0.5, size * 0.78);
  ctx.lineTo(size * 0.2, size * 0.28);
  ctx.lineTo(size * 0.8, size * 0.28);
  ctx.closePath();
  ctx.lineWidth = 2.7;
  ctx.lineJoin = 'round';
  ctx.strokeStyle = strokeColor;
  ctx.stroke();

  return ctx.getImageData(0, 0, size, size);
}

function _createLightningBoltIconImage() {
  const size = 34;
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');
  if (!ctx) return null;

  ctx.clearRect(0, 0, size, size);

  const drawBolt = () => {
    ctx.beginPath();
    ctx.moveTo(size * 0.58, size * 0.10);
    ctx.lineTo(size * 0.37, size * 0.45);
    ctx.lineTo(size * 0.52, size * 0.45);
    ctx.lineTo(size * 0.40, size * 0.84);
    ctx.lineTo(size * 0.68, size * 0.39);
    ctx.lineTo(size * 0.54, size * 0.39);
    ctx.closePath();
  };

  drawBolt();
  ctx.lineWidth = 3.5;
  ctx.lineJoin = 'round';
  ctx.strokeStyle = 'rgba(0, 0, 0, 0.42)';
  ctx.stroke();

  drawBolt();
  ctx.fillStyle = 'rgba(232, 237, 240, 0.78)';
  ctx.fill();

  drawBolt();
  ctx.lineWidth = 1.4;
  ctx.lineJoin = 'round';
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.35)';
  ctx.stroke();

  return ctx.getImageData(0, 0, size, size);
}

async function refreshTvsOverlay(force = false, opts = {}) {
  if (!tvsMapReady) return;
  if (!tvsVisible) {
    _setTvsLayersVisible(false);
    return;
  }
  if (!force && tvsRenderedKey) {
    _setTvsLayersVisible(true);
    return;
  }

  const seq = ++tvsLoadSeq;
  const forceNetwork = !!opts.forceNetwork;
  let data = TVS_EMPTY_GEOJSON;
  try {
    const cached = tvsCache;
    const fresh = cached && (Date.now() - cached.fetchedAt) < STORM_REPORT_CACHE_MS;
    if (fresh && !forceNetwork) data = cached.data;
    else {
      const raw = await _fetchGeoJsonViaTauri(NEXRAD_ATTR_TVS_URL);
      data = _buildTvsGeoJson(raw);
      tvsCache = { fetchedAt: Date.now(), data };
    }
  } catch (err) {
    console.warn('[TVS] failed to load:', err?.message || String(err));
    data = TVS_EMPTY_GEOJSON;
  }

  if (seq !== tvsLoadSeq) return;
  if (!tvsVisible) return;
  _overlayMaps().forEach(m => m.getSource('tvs-icons-src')?.setData(data));
  tvsRenderedKey = `ready:${data.features.length}`;
  _setTvsLayersVisible(true);
}

function initTvsOverlayLayers() {
  if (tvsMapReady) return;

  Object.keys(TVS_ICON_BY_BUCKET).forEach(bucket => {
    const imageId = TVS_ICON_BY_BUCKET[bucket];
    if (map.hasImage(imageId)) return;
    const icon = _createTvsTriangleIconImage(TVS_ICON_COLORS[bucket] || '#ffd400');
    if (icon) map.addImage(imageId, icon, { pixelRatio: 2 });
  });

  map.addSource('tvs-icons-src', {
    type: 'geojson',
    data: TVS_EMPTY_GEOJSON,
  });
  map.addLayer({
    id: 'tvs-icons-symbol',
    type: 'symbol',
    source: 'tvs-icons-src',
    layout: {
      visibility: 'none',
      'icon-image': ['coalesce', ['get', '_tvsIcon'], TVS_ICON_BY_BUCKET.YELLOW],
      'icon-size': 0.7,
      'icon-allow-overlap': true,
      'icon-ignore-placement': true,
    },
  }, 'stations-dot');

  const clickTvs = e => {
    if (!Array.isArray(e?.features) || !e.features.length) return;
    const p = e.features[0]?.properties || {};
    const fmtNum = (val, decimals = 0, suffix = '') => {
      const n = Number(val);
      return Number.isFinite(n) ? `${n.toFixed(decimals)}${suffix}` : '--';
    };
    const bucket = String(p._tvsBucket || '').toUpperCase();
    const accent = TVS_ICON_COLORS[bucket] || '#ffd400';
    const title = `${_escapeHtml(p._nexrad || 'NEXRAD')} ${_escapeHtml(p._stormId || '')}`.trim();
    const rows = [
      ['TVS', _escapeHtml(p._tvs || '--')],
      ['Meso', _escapeHtml(String(p._meso ?? '--'))],
      ['Azimuth', fmtNum(p._azimuth, 0, '°')],
      ['Range', fmtNum(p._range, 0, ' nmi')],
      ['POSH', fmtNum(p._posh, 0, '%')],
      ['POH', fmtNum(p._poh, 0, '%')],
      ['Max Size', fmtNum(p._maxSize, 2, ' in')],
      ['VIL', fmtNum(p._vil, 0)],
      ['Max dBZ', fmtNum(p._maxDbz, 0, ' dBZ')],
      ['Max dBZ Hgt', fmtNum(p._maxDbzHeight, 1, ' kft')],
      ['Top', fmtNum(p._top, 1, ' kft')],
      ['Dir', fmtNum(p._drct, 0, '°')],
      ['Speed', fmtNum(p._sknt, 0, ' kt')],
      ['Motion', _escapeHtml(p._motion || '--')],
      ['Valid', _escapeHtml(p._valid || '--')],
    ];
    const rowsHtml = rows.map(([k, v]) => (
      `<div class="storm-popup-k">${k}</div><div class="storm-popup-v">${v}</div>`
    )).join('');
    new mapboxgl.Popup({ closeButton: true, closeOnClick: true, className: 'storm-popup' })
      .setLngLat(e.lngLat)
      .setHTML(
        `<div class="storm-popup-card" style="--storm-accent:${accent}">`
        + `<div class="storm-popup-title">${title}</div>`
        + `<div class="storm-popup-grid">${rowsHtml}</div>`
        + `</div>`,
      )
      .addTo(map);
  };

  map.on('mouseenter', 'tvs-icons-symbol', () => { map.getCanvas().style.cursor = 'pointer'; });
  map.on('mouseleave', 'tvs-icons-symbol', () => { map.getCanvas().style.cursor = ''; });
  map.on('click', 'tvs-icons-symbol', clickTvs);

  tvsMapReady = true;
  if (tvsVisible) refreshTvsOverlay(true, { forceNetwork: true });
}

function _stormWindowConfig(windowId = stormReportsWindow) {
  return STORM_REPORT_LSR_WINDOWS.find(opt => opt.id === windowId)
    || STORM_REPORT_LSR_WINDOWS.find(opt => opt.id === '24')
    || STORM_REPORT_LSR_WINDOWS[0];
}

function _stormWindowAgeMs(windowId = stormReportsWindow) {
  const minutes = Number(_stormWindowConfig(windowId)?.minutes);
  return Number.isFinite(minutes) && minutes > 0 ? minutes * 60_000 : 24 * 60 * 60_000;
}

function _stormWindowLabel(windowId = stormReportsWindow) {
  return _stormWindowConfig(windowId)?.label || '24h';
}

function _stormEventId(props) {
  return String(props?.event_id || props?.EVENT_ID || '').trim().toUpperCase();
}

function _stormEventText(props) {
  return String(
    props?.event
    || props?.descript
    || props?.DESCRIPT
    || props?.report_type
    || props?.TYPE
    || props?.title
    || 'Storm Report',
  ).trim();
}

function _stormMagnitudeValue(props) {
  const direct = Number(props?.magnitude_value ?? props?.MAGNITUDE_VALUE);
  if (Number.isFinite(direct)) return direct;
  const raw = String(props?.magnitude || props?.MAGNITUDE || '').trim();
  if (!raw) return NaN;
  const match = raw.match(/-?\d+(?:\.\d+)?/);
  return match ? Number(match[0]) : NaN;
}

function _stormStateText(props) {
  const state = props?.state;
  if (state && typeof state === 'object') {
    return String(state.code || state.name || '').trim();
  }
  return String(props?.STATE || props?.state || '').trim();
}

function _stormCountyText(props) {
  return String(props?.county || props?.COUNTY || '').trim();
}

function _stormDisplayTime(props) {
  const candidates = [
    Number(props?.event_at_ms),
    Number(props?.issued_at_ms),
    Number(props?.generated_at_ms),
    Number(props?.lsr_validtime ?? props?.LSR_VALIDTIME),
  ];
  const bestMs = candidates.find(value => Number.isFinite(value) && value > 0);
  if (Number.isFinite(bestMs)) {
    return new Date(bestMs).toLocaleString(undefined, {
      month: 'short',
      day: 'numeric',
      hour: 'numeric',
      minute: '2-digit',
    });
  }
  const iso = String(props?.event_at || props?.issued_at || props?.generated_at || props?.valid_time || props?.VALID_TIME || '').trim();
  if (!iso) return '';
  const parsed = Date.parse(iso);
  if (Number.isFinite(parsed)) {
    return new Date(parsed).toLocaleString(undefined, {
      month: 'short',
      day: 'numeric',
      hour: 'numeric',
      minute: '2-digit',
    });
  }
  return iso.replace('T', ' ');
}

function _formatReportDateTime(value) {
  const rawNum = Number(value);
  let ms = Number.isFinite(rawNum) && rawNum > 0 ? rawNum : NaN;
  if (!Number.isFinite(ms)) {
    const rawText = String(value || '').trim();
    const parsed = rawText ? Date.parse(rawText) : NaN;
    if (Number.isFinite(parsed)) ms = parsed;
    else return rawText;
  }
  return new Date(ms).toLocaleString(undefined, {
    month: 'numeric',
    day: 'numeric',
    year: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
  });
}

function _reportAgeText(value) {
  const rawNum = Number(value);
  let ms = Number.isFinite(rawNum) && rawNum > 0 ? rawNum : NaN;
  if (!Number.isFinite(ms)) {
    const parsed = Date.parse(String(value || '').trim());
    if (Number.isFinite(parsed)) ms = parsed;
  }
  if (!Number.isFinite(ms)) return '';
  const deltaMs = Math.max(0, Date.now() - ms);
  const min = Math.floor(deltaMs / 60000);
  if (min < 1) return 'now';
  if (min < 60) return `${min} min ago`;
  const hr = Math.floor(min / 60);
  if (hr < 24) return `${hr} hour${hr === 1 ? '' : 's'} ago`;
  const day = Math.floor(hr / 24);
  return `${day} day${day === 1 ? '' : 's'} ago`;
}

function _reportCoordsText(coords) {
  if (!Array.isArray(coords) || coords.length < 2) return '';
  const lon = Number(coords[0]);
  const lat = Number(coords[1]);
  if (!Number.isFinite(lat) || !Number.isFinite(lon)) return '';
  return `${lat.toFixed(4)}, ${lon.toFixed(4)}`;
}

function _metarFlightCategoryColorValue(category) {
  const code = String(category || '').trim().toUpperCase();
  return METAR_FLIGHT_CATEGORY_COLORS[code] || '#B9C1CD';
}

function _metarFlightCategoryColorExpr() {
  return ['match', ['upcase', ['coalesce', ['get', 'flightCategory'], '']],
    'VFR', METAR_FLIGHT_CATEGORY_COLORS.VFR,
    'MVFR', METAR_FLIGHT_CATEGORY_COLORS.MVFR,
    'IFR', METAR_FLIGHT_CATEGORY_COLORS.IFR,
    'LIFR', METAR_FLIGHT_CATEGORY_COLORS.LIFR,
    '#B9C1CD',
  ];
}

function _metarTempF(valueC) {
  const c = Number(valueC);
  if (!Number.isFinite(c)) return NaN;
  return (c * 9 / 5) + 32;
}

function _metarTempShort(valueC) {
  const f = _metarTempF(valueC);
  return Number.isFinite(f) ? `${Math.round(f)}°` : '--';
}

function _metarTempDetailed(valueC) {
  const c = Number(valueC);
  const f = _metarTempF(c);
  if (!Number.isFinite(c) || !Number.isFinite(f)) return '--';
  return `${Math.round(f)}°F (${Math.round(c)}°C)`;
}

function _metarWindShort(props = {}) {
  const windKt = Number(props.windSpeedKt);
  if (!Number.isFinite(windKt) || windKt <= 0) return 'Calm';
  return `${Math.round(windKt)}kt`;
}

function _metarWindDetailed(props = {}) {
  const dir = Number(props.windDirDeg);
  const kt = Number(props.windSpeedKt);
  const mph = Number.isFinite(kt) ? Math.round(kt * 1.15078) : NaN;
  if (!Number.isFinite(kt) || kt <= 0) return 'Calm';
  if (Number.isFinite(dir)) return `${Math.round(dir)}° at ${Math.round(kt)} kt (${mph} mph)`;
  return `${Math.round(kt)} kt (${mph} mph)`;
}

function _buildMetarStyledGeoJson(raw) {
  const features = Array.isArray(raw?.features) ? raw.features : [];
  const out = [];
  for (const feature of features) {
    const coords = feature?.geometry?.coordinates;
    if (!Array.isArray(coords) || coords.length < 2) continue;
    const lon = Number(coords[0]);
    const lat = Number(coords[1]);
    if (!Number.isFinite(lon) || !Number.isFinite(lat)) continue;
    const props = feature?.properties && typeof feature.properties === 'object' ? feature.properties : {};
    const tempShort = _metarTempShort(props.tempC);
    const dewShort = _metarTempShort(props.dewpointC);
    const windShort = _metarWindShort(props);
    out.push({
      type: 'Feature',
      geometry: { type: 'Point', coordinates: [lon, lat] },
      properties: {
        ...props,
        _title: String(props.id || props.name || 'METAR').trim(),
        _meta: String(props.flightCategory || 'METAR').trim(),
        _label: `${tempShort}/${dewShort}\n${windShort}`,
        _color: _metarFlightCategoryColorValue(props.flightCategory),
        _observedText: _formatReportDateTime(props.observed),
      },
    });
  }
  return { type: 'FeatureCollection', features: out };
}

function _openMetarDetails(props = {}, coords = []) {
  const observed = props?._observedText || _formatReportDateTime(props?.observed);
  const age = _reportAgeText(props?.observed);
  const observedText = observed && age ? `${observed} (${age})` : observed;
  const stationId = String(props?.id || '').trim();
  const name = String(props?.name || '').trim();
  const title = name && stationId ? `${stationId} • ${name}` : (stationId || name || 'METAR');
  openReportDetailsModal({
    title,
    meta: props?.flightCategory ? `METAR • ${String(props.flightCategory).trim().toUpperCase()}` : 'METAR',
    rows: [
      { label: 'Station', value: stationId || props?.name },
      { label: 'Observed', value: observedText },
      { label: 'Wind', value: _metarWindDetailed(props) },
      { label: 'Temp', value: _metarTempDetailed(props?.tempC) },
      { label: 'Dewpoint', value: _metarTempDetailed(props?.dewpointC) },
      { label: 'Visibility', value: props?.visibilityText || props?.visibilityMiles },
      { label: 'Ceiling', value: props?.ceilingText },
      { label: 'Altimeter', value: props?.altimeterText },
      { label: 'Source', value: props?.source || 'NOAA AviationWeather' },
      { label: 'Coordinates', value: _reportCoordsText(coords), linkish: true },
    ],
    remarks: props?.raw,
    remarksTitle: 'Raw METAR',
  });
}

function _stormEventTimeMs(props) {
  const candidates = [
    Number(props?.event_at_ms),
    Number(props?.issued_at_ms),
    Number(props?.generated_at_ms),
    Number(props?.lsr_validtime ?? props?.LSR_VALIDTIME),
  ];
  for (const value of candidates) {
    if (Number.isFinite(value) && value > 0) return value;
  }
  const text = String(props?.event_at || props?.issued_at || props?.generated_at || props?.valid_time || props?.VALID_TIME || '').trim();
  if (!text) return NaN;
  const parsed = Date.parse(text);
  return Number.isFinite(parsed) ? parsed : NaN;
}

function _stormFormatFixed(value, digits = 2) {
  if (!Number.isFinite(value)) return '';
  return value.toFixed(digits).replace(/\.?0+$/, '');
}

function _stormNormalizeMagnitudeLabel(rawText, value, unit) {
  if (Number.isFinite(value)) {
    if (unit === 'in') return `${_stormFormatFixed(value, 2)}"`;
    if (unit === 'mph') return `${Math.round(value)} MPH`;
  }
  const raw = String(rawText || '').trim();
  if (!raw) return '';
  const upper = raw.toUpperCase();
  if (/INCH| IN\b/.test(upper)) {
    const match = upper.match(/-?\d+(?:\.\d+)?/);
    return match ? `${_stormFormatFixed(Number(match[0]), 2)}"` : upper;
  }
  if (/MPH/.test(upper)) {
    const match = upper.match(/-?\d+(?:\.\d+)?/);
    return match ? `${Math.round(Number(match[0]))} MPH` : upper;
  }
  return upper;
}

function _stormBucketColor(value, thresholds, fallback) {
  if (!Number.isFinite(value)) return fallback;
  for (const [threshold, color] of thresholds) {
    if (value >= threshold) return color;
  }
  return fallback;
}

function _stormRainColor(value, eventId) {
  if (String(eventId || '').includes('FLOOD')) return '#72D62B';
  return _stormBucketColor(value, [
    [8, '#A91CE0'],
    [6, '#8A73D8'],
    [5, '#2536FF'],
    [4, '#2B9DF7'],
    [3, '#24D0F4'],
    [2, '#0FBE30'],
    [1, '#20D42B'],
    [0.01, '#49E72E'],
  ], '#72D62B');
}

function _stormSnowColor(value, eventId) {
  if (/BLIZZ/.test(String(eventId || ''))) return '#FF2A1C';
  return _stormBucketColor(value, [
    [60, '#04070D'],
    [48, '#FF2218'],
    [36, '#FF67CE'],
    [30, '#FF36EF'],
    [24, '#C01EFF'],
    [18, '#7A17D4'],
    [12, '#232EFF'],
    [8, '#466FD7'],
    [6, '#5D90DD'],
    [4, '#7EB2E8'],
    [2, '#A6CCE8'],
    [0.01, '#B9B9B9'],
  ], '#7FB0EB');
}

function _stormIceColor(value) {
  return _stormBucketColor(value, [
    [0.5, '#B317B1'],
    [0.25, '#EC74D0'],
    [0.1, '#E8A5D9'],
    [0.01, '#BDBDBD'],
  ], '#DDA0DD');
}

function _stormHailColor(value) {
  return _stormBucketColor(value, [
    [2, '#B317B1'],
    [1, '#E85CC6'],
    [0.01, '#E7B1E6'],
  ], '#EA60C6');
}

function _stormWindColor(value) {
  return _stormBucketColor(value, [
    [75, '#A07A22'],
    [57, '#C6942F'],
    [35, '#F7B51A'],
    [0.01, '#FFF01C'],
  ], '#C7962A');
}

function _stormTstmColor(value) {
  return _stormBucketColor(value, [
    [75, '#FF2020'],
    [50, '#F7B51A'],
    [0.01, '#FFF01C'],
  ], '#E3A727');
}

function _stormColorForFeature(category, props) {
  const value = _stormMagnitudeValue(props);
  const eventId = _stormEventId(props);
  switch (category) {
    case 'FLOOD': return _stormRainColor(value, eventId);
    case 'WINTER': return _stormSnowColor(value, eventId);
    case 'ICE': return _stormIceColor(value);
    case 'HAIL': return _stormHailColor(value);
    case 'WIND': return _stormWindColor(value);
    case 'TSTM': return _stormTstmColor(value);
    case 'MARINE': return Number.isFinite(value) ? _stormWindColor(value) : '#E4B6CB';
    case 'TORNADO': return '#FF3030';
    case 'FIRE': return '#FF9F43';
    case 'FOG': return '#A9ADB7';
    default: return STORM_REPORT_CATEGORY_COLORS[category] || '#8F949E';
  }
}

function _stormShortEventLabel(props, category) {
  const eventId = _stormEventId(props);
  const event = _stormEventText(props);
  const eventMap = {
    TORNADO: 'Tornado',
    FUNNEL_CLOUD: 'Funnel',
    WALL_CLOUD: 'Wall',
    FLASH_FLOOD: 'Flood',
    FLOOD: 'Flood',
    RAIN: 'Rain',
    HAIL: 'Hail',
    SNOW: 'Snow',
    TSTM_WND_GST: 'Wind',
    TSTM_WND_DMG: 'Damage',
    NONTSTM_WND_GST: 'Wind',
    NONTSTM_WND_DMG: 'Damage',
    MARINE_TSTM_WIND: 'Marine',
    SEVERE_WEATHER: 'Severe',
    DAMAGE: 'Damage',
  };
  if (eventMap[eventId]) return eventMap[eventId];
  if (event && event.length <= 12) return event;
  return STORM_REPORT_CATEGORY_OPTIONS.find(opt => opt.id === category)?.label || 'Report';
}

function _stormCategoryFromText(text) {
  const s = String(text || '').toUpperCase();
  if (!s.trim()) return 'OTHER';
  if (s.includes('WATERSPOUT') || s.includes('MARINE')) return 'MARINE';
  if (s.includes('TORNADO') || s.includes('FUNNEL') || s.includes('WALL CLOUD')) return 'TORNADO';
  if (s.includes('HAIL')) return 'HAIL';
  if (s.includes('TSTM') || s.includes('THUNDER') || s.includes('LIGHTNING')) return 'TSTM';
  if (s.includes('NONTSTM') || s.includes('WND') || s.includes('WIND') || s.includes('DOWNBURST') || s.includes('MICROBURST')) return 'WIND';
  if (s.includes('FREEZ') || s.includes('SLEET') || s.includes('ICE')) return 'ICE';
  if (s.includes('SNOW') || s.includes('BLIZZ')) return 'WINTER';
  if (s.includes('FLOOD') || s.includes('RAIN')) return 'FLOOD';
  if (s.includes('FIRE') || s.includes('SMOKE')) return 'FIRE';
  if (s.includes('FOG') || s.includes('MIST')) return 'FOG';
  return 'OTHER';
}

function _stormCategoryFromProps(props) {
  const eventId = _stormEventId(props);
  const combined = [
    eventId,
    _stormEventText(props),
    props?.remarks,
    props?.REMARKS,
    props?.narrative,
    props?.report_text,
    props?.TEXT,
  ].filter(Boolean).join(' ');

  if (/MARINE_HAIL/.test(eventId)) return 'HAIL';
  if (/MARINE_TSTM_WIND|WATERSPOUT/.test(eventId)) return 'MARINE';
  if (/TORNADO|FUNNEL_CLOUD|WALL_CLOUD/.test(eventId)) return 'TORNADO';
  if (/HAIL/.test(eventId)) return 'HAIL';
  if (/TSTM_WND_GST|TSTM_WND_DMG|SEVERE_WEATHER|LIGHTNING/.test(eventId)) return 'TSTM';
  if (/NONTSTM_WND_GST|NONTSTM_WND_DMG|WIND|DAMAGE|BLOWING_DUST/.test(eventId)) return 'WIND';
  if (/FREEZ|SLEET|ICE/.test(eventId)) return 'ICE';
  if (/SNOW|BLIZZ/.test(eventId)) return 'WINTER';
  if (/FLOOD|RAIN|COASTAL_FLOOD|LANDSLIDE/.test(eventId)) return 'FLOOD';
  if (/WILDFIRE|FIRE|SMOKE/.test(eventId)) return 'FIRE';
  if (/FOG/.test(eventId)) return 'FOG';
  return _stormCategoryFromText(combined);
}

function _stormMagnitudeLabel(props, category, compact = false) {
  const raw = String(props?.magnitude || props?.MAGNITUDE || '').trim();
  const value = _stormMagnitudeValue(props);
  switch (category) {
    case 'FLOOD':
    case 'WINTER':
    case 'ICE':
    case 'HAIL':
      return _stormNormalizeMagnitudeLabel(raw, value, 'in');
    case 'WIND':
    case 'TSTM':
    case 'MARINE':
      return _stormNormalizeMagnitudeLabel(raw, value, 'mph');
    default:
      return compact ? '' : _stormNormalizeMagnitudeLabel(raw, value, '');
  }
}

function _stormLocationText(props) {
  const city = String(props?.city || props?.loc_desc || props?.LOC_DESC || props?.location || props?.LOCATION || '').trim();
  const state = _stormStateText(props);
  const county = _stormCountyText(props);
  if (city && state && !city.toUpperCase().endsWith(`, ${state.toUpperCase()}`)) return `${city}, ${state}`;
  if (city) return city;
  if (county && state) return `${county} County, ${state}`;
  return county || state;
}

function _stormFeatureInWindow(props, windowId = stormReportsWindow) {
  const eventMs = _stormEventTimeMs(props);
  if (!Number.isFinite(eventMs)) return true;
  return eventMs >= (Date.now() - _stormWindowAgeMs(windowId));
}

function _buildStormFeature(geom, props, sourceTag) {
  if (!geom || geom.type !== 'Point' || !Array.isArray(geom.coordinates) || geom.coordinates.length < 2) return null;
  const desc = _stormEventText(props);
  const remarks = String(props?.remarks || props?.REMARKS || props?.narrative || props?.report_text || props?.TEXT || '').trim();
  const category = _stormCategoryFromProps(props);
  const location = _stormLocationText(props);
  const magLabel = _stormMagnitudeLabel(props, category, false);
  const label = STORM_REPORT_CATEGORY_OPTIONS.find(opt => opt.id === category)?.label || category;
  const when = _stormDisplayTime(props);
  const categoryColor = _stormColorForFeature(category, props);
  const markerLabel = _stormMagnitudeLabel(props, category, true) || _stormShortEventLabel(props, category);
  const reporter = String(props?.source || '').trim();
  const eventMs = _stormEventTimeMs(props);
  const issued = _formatReportDateTime(props?.issued_at_ms || props?.issued_at || props?.generated_at_ms || props?.generated_at);
  const office = String(props?.office || props?.OFFICE || '').trim();

  return {
    type: 'Feature',
    geometry: { type: 'Point', coordinates: [geom.coordinates[0], geom.coordinates[1]] },
    properties: {
      _category: category,
      _categoryLabel: label,
      _color: categoryColor,
      _title: desc || label,
      _when: when,
      _location: location,
      _magnitude: magLabel,
      _remarks: remarks,
      _source: reporter ? `${sourceTag} · ${reporter}` : sourceTag,
      _reporter: reporter,
      _database: sourceTag,
      _issued: issued,
      _office: office,
      _markerLabel: markerLabel,
      _eventAtMs: Number.isFinite(eventMs) ? eventMs : '',
    },
  };
}

function _extractQuotedText(line) {
  const m = String(line || '').match(/"([^"]+)"/);
  return m ? m[1].trim() : '';
}

function _parseSpotterIconLine(line) {
  const raw = String(line || '').trim();
  if (!/^Icon:/i.test(raw)) return null;
  const body = raw.replace(/^Icon:\s*/i, '');
  const fields = [];
  let cursor = 0;
  for (let i = 0; i < 5; i += 1) {
    const comma = body.indexOf(',', cursor);
    if (comma < 0) return null;
    fields.push(body.slice(cursor, comma).trim());
    cursor = comma + 1;
  }
  let payload = body.slice(cursor).trim();
  if (payload.startsWith('"')) payload = payload.slice(1);
  if (payload.endsWith('"')) payload = payload.slice(0, -1);
  payload = payload
    .replace(/\\"/g, '"')
    .replace(/\\r/g, '')
    .replace(/\\n/g, '\n')
    .trim();

  const lat = Number.parseFloat(fields[0]);
  const lon = Number.parseFloat(fields[1]);
  if (!Number.isFinite(lat) || !Number.isFinite(lon)) return null;
  return { lat, lon, payload };
}

function _parseSpotterIconPayload(payload) {
  const lines = String(payload || '')
    .split(/\n+/)
    .map(line => String(line || '').trim())
    .filter(Boolean);

  let reporter = '';
  let typeText = '';
  let validTime = '';
  let magnitude = '';
  let location = '';
  const remarks = [];

  for (const line of lines) {
    if (/^Reported By:/i.test(line)) {
      reporter = line.replace(/^Reported By:\s*/i, '').trim();
      continue;
    }
    if (/^Time:/i.test(line)) {
      validTime = line.replace(/^Time:\s*/i, '').trim();
      continue;
    }
    if (/^Location:/i.test(line)) {
      location = line.replace(/^Location:\s*/i, '').trim();
      continue;
    }
    if (/^Size:/i.test(line)) {
      magnitude = line.replace(/^Size:\s*/i, '').replace(/^Notes:\s*/i, '').trim();
      continue;
    }
    if (!typeText) {
      typeText = line;
      continue;
    }
    if (!magnitude && /^\d/.test(line) && /(mph|kt|kts|inch|in\b|ft\b|cm\b|mm\b|mi\b|dbz|\[)/i.test(line)) {
      magnitude = line.trim();
      continue;
    }
    if (/^Notes?:/i.test(line)) {
      const note = line.replace(/^Notes?:\s*/i, '').trim();
      if (note && !/^none$/i.test(note)) remarks.push(note);
      continue;
    }
    remarks.push(line);
  }

  if (!typeText) typeText = 'Spotter Report';

  const reportText = [
    reporter ? `Reported by: ${reporter}` : '',
    ...remarks,
  ].filter(Boolean).join(' | ');

  return {
    reporter,
    typeText,
    validTime,
    magnitude,
    location,
    reportText,
  };
}

function _currentLightningRadarId() {
  const stationId = canonicalStationId(activeStation);
  return (stationId && VIEWABLE_STATIONS[stationId]) ? stationId : '';
}

function _shouldShowLightningOverlay() {
  return lightningVisible && !!_currentLightningRadarId();
}

function _weatherWiseLightningUrl(radarId = _currentLightningRadarId()) {
  const normalized = String(radarId || '').trim().toUpperCase();
  if (!normalized) return '';
  return `https://data2.weatherwise.app/satellite/radar/${encodeURIComponent(normalized)}/active.json`;
}

function _normalizeLightningTimestampMs(unixTime) {
  const raw = Number(unixTime);
  if (!Number.isFinite(raw) || raw <= 0) return NaN;
  return raw < 1e12 ? raw * 1000 : raw;
}

function _formatLightningTime(unixTime) {
  const ms = _normalizeLightningTimestampMs(unixTime);
  if (!Number.isFinite(ms)) return '';
  return _formatReportDateTime(ms);
}

function _buildWeatherWiseLightningGeoJson(payload, radarId = _currentLightningRadarId(), nowMs = Date.now()) {
  const strikes = Array.isArray(payload?.strikes) ? payload.strikes : [];
  const features = [];
  const cutoffMs = Number(nowMs) - LIGHTNING_WINDOW_MS;
  for (const strike of strikes) {
    if (!Array.isArray(strike) || strike.length < 3) continue;
    const lon = Number(strike[0]);
    const lat = Number(strike[1]);
    const unixTime = Number(strike[2]);
    if (!Number.isFinite(lon) || !Number.isFinite(lat)) continue;
    const timestampMs = _normalizeLightningTimestampMs(unixTime);
    if (!Number.isFinite(timestampMs) || timestampMs < cutoffMs) continue;
    const formattedTime = _formatLightningTime(unixTime);
    features.push({
      type: 'Feature',
      geometry: { type: 'Point', coordinates: [lon, lat] },
      properties: {
        title: 'Lightning',
        source: 'WeatherWise',
        timestamp: Number.isFinite(timestampMs) ? timestampMs : null,
        unixTime: Number.isFinite(unixTime) ? unixTime : null,
        formattedTime,
        radarId,
        _title: 'Lightning',
        _source: 'WeatherWise',
        _when: formattedTime,
        _details: radarId ? `Radar ${radarId}` : '',
        _magnitude: '',
      },
    });
  }
  return { type: 'FeatureCollection', features };
}

function _parseSpotterPlacefile(text) {
  const lines = String(text || '').split(/\r?\n/);
  const features = [];
  let obj = null;

  const flush = () => {
    if (!obj) return;
    if (!Number.isFinite(obj.lat) || !Number.isFinite(obj.lon)) {
      obj = null;
      return;
    }
    const props = {
      report_type: obj.typeText || 'Spotter Report',
      report_text: obj.textParts.filter(Boolean).join(' | '),
      descript: obj.typeText || 'Spotter Report',
      remarks: obj.textParts.filter(Boolean).join(' | '),
      valid_time: '',
      location: '',
    };
    features.push({
      type: 'Feature',
      geometry: { type: 'Point', coordinates: [obj.lon, obj.lat] },
      properties: props,
    });
    obj = null;
  };

  for (const rawLine of lines) {
    const line = String(rawLine || '').trim();
    if (!line) continue;

    if (/^Icon:/i.test(line)) {
      const icon = _parseSpotterIconLine(line);
      if (!icon) continue;
      const parsed = _parseSpotterIconPayload(icon.payload);
      features.push({
        type: 'Feature',
        geometry: { type: 'Point', coordinates: [icon.lon, icon.lat] },
        properties: {
          report_type: parsed.typeText,
          report_text: parsed.reportText,
          descript: parsed.typeText,
          remarks: parsed.reportText,
          valid_time: parsed.validTime,
          location: parsed.location,
          magnitude: parsed.magnitude,
        },
      });
      continue;
    }

    const objectMatch = line.match(/^Object:\s*(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)/i);
    if (objectMatch) {
      flush();
      obj = {
        lat: parseFloat(objectMatch[1]),
        lon: parseFloat(objectMatch[2]),
        textParts: [],
        typeText: 'Spotter Report',
      };
      continue;
    }

    if (!obj) continue;
    if (/^End:/i.test(line)) {
      flush();
      continue;
    }
    if (/^Text:/i.test(line)) {
      const textPart = line.replace(/^Text:\s*/i, '').trim();
      if (textPart) obj.textParts.push(textPart.replace(/^"|"$/g, ''));
      continue;
    }
    if (/^Title:/i.test(line)) {
      const title = line.replace(/^Title:\s*/i, '').trim();
      if (title) obj.typeText = title.replace(/^"|"$/g, '');
      continue;
    }
    if (/^Icon:/i.test(line)) {
      const label = _extractQuotedText(line);
      if (label) obj.textParts.push(label);
      continue;
    }
    if (/^Threshold:/i.test(line) || /^Refresh:/i.test(line) || /^Font:/i.test(line) || /^IconFile:/i.test(line)) continue;
  }

  flush();
  return { type: 'FeatureCollection', features };
}

function _stormRawCacheKey(sourceId) {
  return String(sourceId || '').toUpperCase();
}

async function _loadStormRaw(sourceId, forceNetwork = false) {
  const key = _stormRawCacheKey(sourceId);
  const cached = stormRawCache.get(key);
  const fresh = cached && (Date.now() - cached.fetchedAt) < STORM_REPORT_CACHE_MS;
  if (fresh && !forceNetwork) return cached.data;

  let data = STORM_EMPTY_GEOJSON;
  if (sourceId === 'SPOTTER') {
    data = await _fetchGeoJsonViaTauri(SPOTTER_REPORTS_URL);
  } else {
    data = await _fetchGeoJsonViaTauri(STORM_REPORT_LSR_URL);
  }

  stormRawCache.set(key, { fetchedAt: Date.now(), data });
  return data;
}

function _buildStormStyledGeoJson(raw, sourceId) {
  const sourceTag = sourceId === 'SPOTTER'
    ? 'Spotter Network'
    : `NWS Local Storm Reports (${_stormWindowLabel(stormReportsWindow)})`;

  const out = [];
  const features = Array.isArray(raw?.features) ? raw.features : [];
  for (const feature of features) {
    if (!_stormFeatureInWindow(feature?.properties || {}, stormReportsWindow)) continue;
    const built = _buildStormFeature(feature?.geometry, feature?.properties || {}, sourceTag);
    if (built) out.push(built);
  }
  return { type: 'FeatureCollection', features: out };
}

function _mpingMarkerCategory(props = {}) {
  const category = String(props.category || '').trim();
  switch (category) {
    case 'Tornado': return 'TORNADO';
    case 'Hail': return 'HAIL';
    case 'Flood': return 'FLOOD';
    case 'Rain/Snow': return 'WINTER';
    case 'Wind Damage': return 'WIND';
    case 'Storm Damage': return 'TSTM';
    case 'Fog/Mist/Dust': return 'FOG';
    case 'Blowing Snow / Reduced Visibility': return 'WINTER';
    case 'Freezing Rain/Drizzle': return 'ICE';
    case 'Ice Pellets/Sleet': return 'ICE';
    default: return 'OTHER';
  }
}

function _mpingMarkerColor(props = {}) {
  const category = String(props.category || '').trim();
  switch (category) {
    case 'Rain/Snow': return '#4499ff';
    case 'Hail': return '#EA60C6';
    case 'Flood': return '#34D24A';
    case 'Wind Damage': return '#F7B51A';
    case 'Storm Damage': return '#FF7A1A';
    case 'Fog/Mist/Dust': return '#A9ADB7';
    case 'Blowing Snow / Reduced Visibility': return '#7FB0EB';
    case 'Freezing Rain/Drizzle': return '#DDA0DD';
    case 'Ice Pellets/Sleet': return '#EC74D0';
    case 'Tornado': return '#FF3030';
    case 'None': return '#777777';
    case 'Test': return '#999999';
    default: return '#8F949E';
  }
}

function _mpingMarkerLabel(props = {}) {
  const category = String(props.category || '').trim();
  const byCategory = {
    'Rain/Snow': 'Rain',
    'Hail': 'Hail',
    'Flood': 'Flood',
    'Wind Damage': 'Wind',
    'Storm Damage': 'Damage',
    'Fog/Mist/Dust': 'Fog',
    'Blowing Snow / Reduced Visibility': 'Snow',
    'Freezing Rain/Drizzle': 'Ice',
    'Ice Pellets/Sleet': 'Sleet',
    'Tornado': 'Tornado',
    'None': '',
    'Test': 'Test',
  };
  if (Object.prototype.hasOwnProperty.call(byCategory, category)) return byCategory[category];
  const description = String(props.description || '').trim();
  return description.length <= 12 ? description : category;
}

function _buildMpingStyledGeoJson(raw) {
  const features = Array.isArray(raw?.features) ? raw.features : [];
  const out = [];
  for (const feature of features) {
    const coords = feature?.geometry?.coordinates;
    if (!Array.isArray(coords) || coords.length < 2) continue;
    const props = feature?.properties && typeof feature.properties === 'object' ? feature.properties : {};
    out.push({
      type: 'Feature',
      geometry: { type: 'Point', coordinates: [coords[0], coords[1]] },
      properties: {
        ...props,
        _markerCategory: _mpingMarkerCategory(props),
        _markerLabel: _mpingMarkerLabel(props),
        _color: _mpingMarkerColor(props),
      },
    });
  }
  return { type: 'FeatureCollection', features: out };
}

function _setLightningLayersVisible(visible) {
  const vis = visible ? 'visible' : 'none';
  _overlayMaps().forEach(m => {
    LIGHTNING_LAYER_IDS.forEach(id => {
      if (m.getLayer(id)) m.setLayoutProperty(id, 'visibility', vis);
    });
  });
}

async function refreshLightningOverlay(force = false, opts = {}) {
  if (!lightningMapReady) return;
  const radarId = _currentLightningRadarId();
  if (!_shouldShowLightningOverlay() || !radarId) {
    _overlayMaps().forEach(m => m.getSource('lightning-src')?.setData(LIGHTNING_EMPTY_GEOJSON));
    _setLightningLayersVisible(false);
    return;
  }

  const seq = ++lightningLoadSeq;
  let data = LIGHTNING_EMPTY_GEOJSON;
  const url = _weatherWiseLightningUrl(radarId);
  try {
    const text = await _fetchTextViaTauri(url, { cacheMode: 'no-store' });
    const payload = JSON.parse(text);
    const strikes = Array.isArray(payload?.strikes) ? payload.strikes : null;
    if (!strikes) {
      console.warn(`[LIGHTNING] invalid WeatherWise payload for ${radarId}`);
    } else if (!strikes.length) {
      console.warn(`[LIGHTNING] WeatherWise returned no strikes for ${radarId}`);
    } else {
      data = _buildWeatherWiseLightningGeoJson(payload, radarId);
    }
  } catch (err) {
    console.warn(`[LIGHTNING] failed to load WeatherWise lightning for ${radarId}:`, err?.message || String(err || 'Unknown error'));
    data = LIGHTNING_EMPTY_GEOJSON;
  }

  if (seq !== lightningLoadSeq) return;
  if (!_shouldShowLightningOverlay()) return;
  _overlayMaps().forEach(m => m.getSource('lightning-src')?.setData(data));
  _setLightningLayersVisible(true);
}

