function setStormFilterOpen(open) {
  const panel = document.getElementById('settings-section-storm');
  const btn = document.getElementById('storm-filter-btn');
  if (!panel || !btn) return;
  panel.classList.toggle('open', open);
  btn.classList.toggle('open', open);
  btn.setAttribute('aria-expanded', open ? 'true' : 'false');
}

function syncStormFilterUi() {
  const windowWrap = document.getElementById('storm-window-buttons');
  const windowBlock = document.getElementById('storm-window-block');
  if (!windowWrap) return;
  if (!STORM_REPORT_LSR_WINDOWS.some(opt => opt.id === stormReportsWindow)) {
    stormReportsWindow = '24';
  }

  if (windowBlock) windowBlock.style.display = 'grid';
  windowWrap.innerHTML = '';
  STORM_REPORT_LSR_WINDOWS.forEach(opt => {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = `spc-chip${opt.id === stormReportsWindow ? ' active' : ''}`;
    btn.textContent = opt.label;
    btn.addEventListener('click', async () => {
      if (opt.id === stormReportsWindow) return;
      stormReportsWindow = opt.id;
      syncStormFilterUi();
      if (stormReportsVisible) await refreshStormReports(true, { forceNetwork: true });
      saveSettings();
    });
    windowWrap.appendChild(btn);
  });
}

async function refreshStormReports(force = false, opts = {}) {
  if (!stormReportsMapReady) return;
  stormReportsVisible = stormReportsLsrVisible || stormReportsSpotterVisible;
  if (!stormReportsVisible) {
    _overlayMaps().forEach(m => m.getSource('storm-reports-src')?.setData(STORM_EMPTY_GEOJSON));
    _setStormReportLayersVisible(false);
    stormReportsRenderedKey = '';
    return;
  }

  const renderKey = [
    stormReportsLsrVisible ? `LSR:${stormReportsWindow}` : '',
    stormReportsSpotterVisible ? 'SPOTTER' : '',
  ].filter(Boolean).join('|');
  if (!force && renderKey === stormReportsRenderedKey) {
    _setStormReportLayersVisible(true);
    return;
  }

  const seq = ++stormReportsLoadSeq;
  const forceNetwork = !!opts.forceNetwork;
  const requestedSources = [];
  if (stormReportsLsrVisible) requestedSources.push('LSR');
  if (stormReportsSpotterVisible) requestedSources.push('SPOTTER');
  const results = await Promise.allSettled(
    requestedSources.map(sourceId => _loadStormRaw(sourceId, forceNetwork).then(raw => ({ sourceId, raw }))),
  );
  if (seq !== stormReportsLoadSeq) return;
  if (!stormReportsVisible) return;

  const merged = [];
  const counts = [];
  results.forEach(result => {
    if (result.status !== 'fulfilled') {
      console.warn('[REPORTS] failed to load:', result.reason?.message || String(result.reason || 'Unknown error'));
      return;
    }
    const { sourceId, raw } = result.value;
    const styled = _buildStormStyledGeoJson(raw, sourceId);
    if (Array.isArray(styled?.features) && styled.features.length) merged.push(...styled.features);
    counts.push(`${sourceId}:${Array.isArray(styled?.features) ? styled.features.length : 0}`);
  });
  const styled = { type: 'FeatureCollection', features: merged };
  _overlayMaps().forEach(m => m.getSource('storm-reports-src')?.setData(styled));
  console.info('[REPORTS] shown=%d window=%s sources=%s',
    Array.isArray(styled?.features) ? styled.features.length : 0,
    stormReportsWindow,
    counts.join(', ') || 'none',
  );
  stormReportsRenderedKey = renderKey;
  _setStormReportLayersVisible(true);
}

function _stormReportPopupHtml(props) {
  const title = _escapeHtml(props?._title || 'Storm Report');
  const category = _escapeHtml(props?._categoryLabel || '');
  const categoryColor = _escapeHtml(props?._color || '#4EA5FF');
  const source = _escapeHtml(props?._source || '');
  const when = _escapeHtml(props?._when || '');
  const location = _escapeHtml(props?._location || '');
  const magnitude = _escapeHtml(props?._magnitude || '');
  const remarks = _escapeHtml(props?._remarks || '');
  const categoryText = category || 'Report';
  const timeText = when || '--';
  const locationText = location || '--';
  const magnitudeText = magnitude || '--';
  const sourceText = source || '--';

  return `
    <div class="storm-popup-card" style="--storm-accent:${categoryColor}">
      <div class="storm-popup-title">${title}</div>
      <div class="storm-popup-meta">${categoryText}</div>
      <div class="storm-popup-grid">
        <div class="storm-popup-k">Location</div><div class="storm-popup-v">${locationText}</div>
        <div class="storm-popup-k">Amount</div><div class="storm-popup-v">${magnitudeText}</div>
        <div class="storm-popup-k">Time</div><div class="storm-popup-v">${timeText}</div>
        <div class="storm-popup-k">Source</div><div class="storm-popup-v">${sourceText}</div>
      </div>
      ${remarks ? `<div class="storm-popup-remarks">${remarks}</div>` : ''}
    </div>
  `;
}

function _reportDetailsRowsHtml(rows = []) {
  return rows
    .filter(row => row && String(row.value ?? '').trim())
    .map(row => {
      const label = _escapeHtml(row.label || '');
      const value = _escapeHtml(String(row.value ?? '').trim());
      const cls = row.muted ? 'report-details-v muted' : row.linkish ? 'report-details-v report-details-linkish' : 'report-details-v';
      return `<div class="report-details-k">${label}</div><div class="${cls}">${value}</div>`;
    })
    .join('');
}

function openReportDetailsModal(detail = {}) {
  const overlay = document.getElementById('report-details-overlay');
  const titleEl = document.getElementById('report-details-title');
  const metaEl = document.getElementById('report-details-meta');
  const bodyEl = document.getElementById('report-details-body');
  if (!overlay || !titleEl || !metaEl || !bodyEl) return;
  if (stormReportsPopup) { stormReportsPopup.remove(); stormReportsPopup = null; }
  if (mpingPopup) { mpingPopup.remove(); mpingPopup = null; }
  if (spotterLocationsPopup) { spotterLocationsPopup.remove(); spotterLocationsPopup = null; }

  titleEl.textContent = String(detail.title || 'Report Details');
  metaEl.textContent = String(detail.meta || 'Report');
  const rowsHtml = _reportDetailsRowsHtml(detail.rows || []);
  const remarks = String(detail.remarks || '').trim();
  bodyEl.innerHTML = `
    ${rowsHtml ? `<div class="report-details-grid">${rowsHtml}</div>` : ''}
    ${remarks ? `<div class="report-details-block">
      <div class="report-details-block-title">${_escapeHtml(detail.remarksTitle || 'Details')}</div>
      <div class="report-details-block-text">${_escapeHtml(remarks)}</div>
    </div>` : ''}
  `;
  overlay.classList.add('open');
  overlay.setAttribute('aria-hidden', 'false');
}

function closeReportDetailsModal() {
  const overlay = document.getElementById('report-details-overlay');
  overlay?.classList.remove('open');
  overlay?.setAttribute('aria-hidden', 'true');
}

function _openStormReportDetails(props = {}, coords = []) {
  const eventTime = props?._when || _formatReportDateTime(props?._eventAtMs);
  const age = _reportAgeText(props?._eventAtMs);
  openReportDetailsModal({
    title: props?._title || 'Storm Report',
    meta: props?._categoryLabel || 'Storm Report',
    rows: [
      { label: 'Location', value: props?._location },
      { label: 'Magnitude', value: props?._magnitude },
      { label: 'Event Time', value: eventTime && age ? `${eventTime} (${age})` : eventTime },
      { label: 'Issued', value: props?._issued },
      { label: 'Source', value: props?._reporter || props?._source },
      { label: 'Office', value: props?._office, linkish: true },
      { label: 'Coordinates', value: _reportCoordsText(coords), linkish: true },
      { label: 'Database', value: props?._database || props?._source },
    ],
    remarks: props?._remarks,
    remarksTitle: 'Report Text',
  });
}

function _openMpingReportDetails(props = {}, coords = []) {
  const eventValue = props?.obtime || props?.observed_at || props?.time || props?.valid_time || '';
  const eventTime = _formatReportDateTime(eventValue);
  const age = _reportAgeText(eventValue);
  const title = String(props?.description || props?.category || 'mPING Report').trim();
  openReportDetailsModal({
    title,
    meta: 'mPING Report',
    rows: [
      { label: 'Category', value: props?.category },
      { label: 'Event Time', value: eventTime && age ? `${eventTime} (${age})` : eventTime },
      { label: 'Source', value: 'mPING' },
      { label: 'Coordinates', value: _reportCoordsText(coords), linkish: true },
    ],
    remarks: title !== String(props?.category || '').trim() ? '' : String(props?.description || '').trim(),
    remarksTitle: 'Report Text',
  });
}

function _openSpotterLocationDetails(props = {}, coords = []) {
  const updatedValue = props?.obtime_utc || props?.updated_at || props?.updated || props?.time || '';
  const updated = _formatReportDateTime(updatedValue);
  const age = _reportAgeText(updatedValue);
  const name = String(props?.label || props?.name || props?.callsign || 'Spotter').trim();
  openReportDetailsModal({
    title: name,
    meta: 'Spotter Network Position',
    rows: [
      { label: 'Status', value: props?.status },
      { label: 'Updated', value: updated && age ? `${updated} (${age})` : updated },
      { label: 'Callsign', value: props?.callsign || props?.spotter || props?.id },
      { label: 'Coordinates', value: _reportCoordsText(coords), linkish: true },
      { label: 'Source', value: 'Spotter Network' },
    ],
    remarks: props?.remarks || props?.description || props?.detail || '',
    remarksTitle: 'Notes',
  });
}

