function _setTestWarnings(features = []) {
  const nowMs = Date.now();
  const activeIds = new Set();
  let changed = false;

  for (const feature of features) {
    const next = _alertsNormalizeExternalFeature(feature, ALERT_SOURCE_TEST);
    if (!next) continue;
    activeIds.add(next.id);

    const prev = alertsById.get(next.id);
    const prevFlashUntil = Number(prev?.properties?._flashUntilMs);
    if (Number.isFinite(prevFlashUntil) && prevFlashUntil > nowMs) {
      next.properties._flashUntilMs = prevFlashUntil;
    } else if (!prev) {
      next.properties._flashUntilMs = nowMs + 10_000;
    }

    if (!prev || JSON.stringify(prev.properties) !== JSON.stringify(next.properties) || JSON.stringify(prev.geometry) !== JSON.stringify(next.geometry)) {
      alertsById.set(next.id, next);
      changed = true;
    }
  }

  for (const [id, feature] of alertsById.entries()) {
    if (String(feature?.properties?._provider || '') !== ALERT_SOURCE_TEST) continue;
    if (!activeIds.has(id)) {
      alertsById.delete(id);
      changed = true;
    }
  }

  if (changed) _alertsScheduleSourceUpdate();
  else _ensureOverlayFlashTicker();
}

function loadTestWarnings() {
  _setTestWarnings(_buildTestWarningFeatures());
}

function clearTestWarnings() {
  _alertsClearProviderFeatures(ALERT_SOURCE_TEST);
}

function _alertsClearProviderFeatures(provider) {
  if (!provider) return;
  if (provider === ALERT_SOURCE_NWS_BOOTSTRAP) _alertsClearBootstrapPruneTimer();
  let changed = false;
  for (const [id, feature] of alertsById.entries()) {
    if (String(feature?.properties?._provider || '') === provider) {
      alertsById.delete(id);
      changed = true;
    }
  }
  if (changed) _alertsScheduleSourceUpdate();
}

function _alertsFeatureStartMs(feature) {
  const props = feature?.properties || {};
  return _alertsParseTimeMs(props?.effective ?? props?.onset ?? props?.sent ?? props?.issued);
}

function _alertsFeatureEndMs(feature) {
  const props = feature?.properties || {};
  return _alertsParseTimeMs(props?.expires ?? props?.ends ?? props?._keepUntilMs);
}

function _alertsFeatureActiveAt(feature, atMs) {
  const t = Number(atMs);
  if (!Number.isFinite(t)) return false;
  const startMs = _alertsFeatureStartMs(feature);
  const endMs = _alertsFeatureEndMs(feature);
  if (Number.isFinite(startMs) && startMs > t + 60_000) return false;
  if (Number.isFinite(endMs) && endMs < t - 60_000) return false;
  return true;
}

function _alertsPresentationTimeMs() {
  return Number.isFinite(alertsPlaybackTimeMs) ? alertsPlaybackTimeMs : Date.now();
}

function _alertsFeaturesForPresentation() {
  if (!Number.isFinite(alertsPlaybackTimeMs)) return [...alertsById.values()];
  const byId = new Map();
  for (const feature of archivedAlertsById.values()) {
    if (_alertsFeatureActiveAt(feature, alertsPlaybackTimeMs)) byId.set(String(feature?.id || feature?.properties?.id || ''), feature);
  }
  for (const feature of alertsById.values()) {
    if (_alertsFeatureActiveAt(feature, alertsPlaybackTimeMs)) {
      const id = String(feature?.id || feature?.properties?.id || '');
      if (!byId.has(id)) byId.set(id, feature);
    }
  }
  return [...byId.values()].filter(Boolean);
}

function _alertsFeatureForPresentationById(id) {
  const key = String(id || '').trim();
  if (!key) return null;
  if (Number.isFinite(alertsPlaybackTimeMs)) {
    const archived = archivedAlertsById.get(key);
    if (archived && _alertsFeatureActiveAt(archived, alertsPlaybackTimeMs)) return archived;
  }
  return alertsById.get(key) || null;
}

function _alertsArchiveRequestUrl(startMs, endMs) {
  const base = String(NWS_API_ALERTS_URL || 'https://api.weather.gov/alerts/active').replace(/\/active(?:\?.*)?$/i, '');
  const url = new URL(base);
  url.searchParams.set('start', new Date(startMs).toISOString());
  url.searchParams.set('end', new Date(endMs).toISOString());
  url.searchParams.set('status', 'actual');
  return url.toString();
}

function _alertsArchiveRangeForTime(frameMs, history = null) {
  const times = (Array.isArray(history) ? history : [])
    .map(entry => parseKeyTimestampMs(String(entry?.key || entry?.fileName || entry?.filename || '')))
    .filter(Number.isFinite);
  let minMs = Number(frameMs);
  let maxMs = Number(frameMs);
  if (times.length) {
    minMs = Math.min(minMs, ...times);
    maxMs = Math.max(maxMs, ...times);
  }
  let startMs = Math.max(0, minMs - ALERT_ARCHIVE_FETCH_LOOKBACK_MS);
  let endMs = maxMs + ALERT_ARCHIVE_FETCH_LOOKAHEAD_MS;
  const latestAllowedMs = Date.now() + ALERT_ARCHIVE_FETCH_LOOKAHEAD_MS;
  if (endMs > latestAllowedMs) endMs = latestAllowedMs;
  if ((endMs - startMs) > ALERT_ARCHIVE_FETCH_MAX_SPAN_MS) {
    startMs = Math.max(0, Number(frameMs) - ALERT_ARCHIVE_FETCH_LOOKBACK_MS);
    endMs = Math.min(latestAllowedMs, Number(frameMs) + ALERT_ARCHIVE_FETCH_LOOKAHEAD_MS);
  }
  return {
    startMs: Math.floor(startMs / 300000) * 300000,
    endMs: Math.ceil(endMs / 300000) * 300000,
  };
}

function _alertsArchiveRangeCovers(startMs, endMs) {
  return Number.isFinite(archivedAlertsRange.startMs)
    && Number.isFinite(archivedAlertsRange.endMs)
    && archivedAlertsRange.startMs <= startMs + ALERT_ARCHIVE_FETCH_PAD_MS
    && archivedAlertsRange.endMs >= endMs - ALERT_ARCHIVE_FETCH_PAD_MS;
}

async function _ensureArchivedWarningsForTime(frameMs, history = null) {
  if (!alertsVisible || !Number.isFinite(frameMs)) return;
  const { startMs, endMs } = _alertsArchiveRangeForTime(frameMs, history);
  if (!Number.isFinite(startMs) || !Number.isFinite(endMs) || endMs <= startMs) return;
  if (_alertsArchiveRangeCovers(startMs, endMs)) return;
  if (archivedAlertsFetchPromise) return archivedAlertsFetchPromise;

  const seq = ++archivedAlertsFetchSeq;
  const url = _alertsArchiveRequestUrl(startMs, endMs);
  archivedAlertsFetchPromise = (async () => {
    try {
      const raw = await _fetchGeoJsonViaTauri(url, { timeoutMs: 30000, cacheMode: 'no-store' });
      if (seq !== archivedAlertsFetchSeq) return;
      const features = Array.isArray(raw?.features) ? raw.features : [];
      const normalized = _alertsCollapseFeaturesByIdentity(
        features
          .map(feature => _alertsNormalizeNwsApiFeature(feature, ALERT_SOURCE_NWS_ARCHIVE))
          .filter(Boolean),
      );
      archivedAlertsById.clear();
      for (const feature of normalized) archivedAlertsById.set(String(feature.id), feature);
      archivedAlertsRange = { startMs, endMs };
      console.info('[WarningsArchive] loaded', {
        start: new Date(startMs).toISOString(),
        end: new Date(endMs).toISOString(),
        count: normalized.length,
      });
      if (Number.isFinite(alertsPlaybackTimeMs)) _alertsRefreshPresentationNow();
    } catch (err) {
      console.warn('[WarningsArchive] fetch failed:', err?.message || String(err));
    } finally {
      if (seq === archivedAlertsFetchSeq) archivedAlertsFetchPromise = null;
    }
  })();
  return archivedAlertsFetchPromise;
}

function _setAlertsPlaybackTime(frameMs, history = null) {
  const nextMs = Number(frameMs);
  if (!Number.isFinite(nextMs)) {
    if (Number.isFinite(alertsPlaybackTimeMs)) {
      alertsPlaybackTimeMs = NaN;
      _alertsRefreshPresentationNow();
    }
    return;
  }
  const changed = !Number.isFinite(alertsPlaybackTimeMs) || Math.abs(alertsPlaybackTimeMs - nextMs) > 1000;
  alertsPlaybackTimeMs = nextMs;
  if (changed) _alertsRefreshPresentationNow();
  void _ensureArchivedWarningsForTime(nextMs, history).catch(() => {});
}

function _setAlertsPlaybackTimeForKey(key) {
  const ts = parseKeyTimestampMs(key);
  if (!Number.isFinite(ts)) return;
  _setAlertsPlaybackTime(ts, historyMap.get(_timelineComboKey()) || null);
}

function _alertsStyledFeatures() {
  const features = [];
  for (const feature of _alertsFeaturesForPresentation()) {
    const props = feature?.properties || {};
    if (!_warningShowOnMap(props)) continue;
    features.push({
      ...feature,
      properties: {
        ...props,
        _displayColor: _warningDisplayColor(props),
        _fillColor: _warningFillColor(props),
        _fillOpacity: _warningFillOpacity(props),
        _lineWidth: _warningLineWidth(props),
      },
    });
  }
  return features;
}

function _alertsQueueTiming(alertId, timing) {
  if (!alertId || !timing || typeof timing !== 'object') return;
  alertsPendingTimingById.set(String(alertId), { ...timing });
}

function _alertsApplySourceDataNow() {
  const features = _alertsStyledFeatures();
  if (alertsMapReady) {
    _overlayMaps().forEach(m => {
      const src = m.getSource('alerts-src');
      if (src) src.setData({ type: 'FeatureCollection', features });
    });
  }
  _alertsScheduleExpiryCheck();
  _ensureOverlayFlashTicker();
  _emitWarningDashboardSnapshot();
}

function _alertsScheduleSourceUpdate() {
  _alertsScheduleExpiryCheck();
  if (!alertsMapReady || alertsFlushPending) return;
  alertsFlushPending = true;
  requestAnimationFrame(() => {
    alertsFlushPending = false;
    _alertsCleanupExpired();

    const features = _alertsStyledFeatures();
    _overlayMaps().forEach(m => {
      const src = m.getSource('alerts-src');
      if (src) src.setData({ type: 'FeatureCollection', features });
    });
    alertsPendingTimingById.clear();
    _alertsScheduleExpiryCheck();
    _ensureOverlayFlashTicker();
    _emitWarningDashboardSnapshot();
  });
}

function _alertsRefreshPresentationNow() {
  alertsFlushPending = false;
  _alertsApplySourceDataNow();
}

function _alertsUpsertFromPayload(payload) {
  const id = _alertsAlertId(payload);
  if (!id) return;
  const nowMs = Date.now();
  const prev = alertsById.get(id);

  if (_alertsShouldRemove(payload)) {
    const removed = alertsById.delete(id);
    if (removed) {
      _alertsQueueTiming(id, payload?.timing);
      _alertsScheduleSourceUpdate();
      if (warningNotificationsPrimed && prev) {
        const kind = _warningChangeKind(prev, null, { removed: true, payload });
        if (kind) _announceWarningChanges([{ feature: prev, kind }]);
      }
    }
    return;
  }

  const feature = _alertsNormalizeFeature(payload);
  if (!feature) return;

  if (prev) {
    const sameGeometry = JSON.stringify(prev.geometry) === JSON.stringify(feature.geometry);
    const sameProperties = JSON.stringify(prev.properties) === JSON.stringify(feature.properties);
    if (sameGeometry && sameProperties) return;
  }

  const prevFlashUntil = Number(prev?.properties?._flashUntilMs);
  if (Number.isFinite(prevFlashUntil) && prevFlashUntil > nowMs) {
    feature.properties._flashUntilMs = prevFlashUntil;
  } else if (!prev && alertsSeeded) {
    feature.properties._flashUntilMs = nowMs + 10_000;
  }

  if (!alertsSeeded) alertsSeeded = true;
  alertsById.set(id, feature);
  _alertsQueueTiming(id, payload?.timing);
  _alertsScheduleSourceUpdate();
  if (warningNotificationsPrimed) {
    const kind = _warningChangeKind(prev, feature, { payload });
    if (kind) _announceWarningChanges([{ feature, kind }]);
  }
}

function _alertsNwsApiWarningEvent(eventName) {
  const raw = String(eventName || '').trim();
  if (!raw) return null;
  if (/warning/i.test(raw)) return raw;
  if (/special weather statement/i.test(raw)) return raw;
  return null;
}

function _alertsNormalizeNwsApiFeature(feature, provider = ALERT_SOURCE_NWS_API) {
  const geomType = String(feature?.geometry?.type || '');
  const coordinates = feature?.geometry?.coordinates;
  if (!['Polygon', 'MultiPolygon', 'Point'].includes(geomType)) return null;
  if (!Array.isArray(coordinates) || coordinates.length === 0) return null;

  const props = feature?.properties || {};
  const eventRaw = String(props?.event || '').trim();
  const event = _alertsNwsApiWarningEvent(eventRaw);
  if (!event) return null;
  if (/special weather statement/i.test(event) && !_alertsIsStormBasedSpecialWeatherStatement(props)) return null;
  if (/special weather statement/i.test(event) && _alertsGeometryVertexCount(feature?.geometry) > 25) return null;

  const warnClass = _alertsWarnClass(event, props);
  if (!warnClass || !WARNING_PREF_ID_SET.has(warnClass)) return null;

  const id = String(feature?.id || props?.id || props?.tracking || '').trim();
  if (!id) return null;

  const sentMs = _alertsParseTimeMs(props?.sent || props?.effective || props?.onset);
  const expiresMs = _alertsParseTimeMs(props?.expires);
  const keepUntilMs = Number.isFinite(expiresMs)
    ? expiresMs
    : (Number.isFinite(sentMs) ? sentMs + ALERT_DEFAULT_KEEP_MS : Date.now() + ALERT_DEFAULT_KEEP_MS);

  return {
    type: 'Feature',
    id,
    geometry: {
      type: geomType,
      coordinates,
    },
    properties: {
      ...(props || {}),
      id,
      event,
      eventRaw,
      _warnClass: _resolvedWarningClass({
        ...(props || {}),
        event,
        eventRaw,
        _warnClass: warnClass,
      }),
      messageType: String(props?.messageType || 'Alert'),
      sent: Number.isFinite(sentMs) ? new Date(sentMs).toISOString() : null,
      expires: Number.isFinite(expiresMs) ? new Date(expiresMs).toISOString() : null,
      _keepUntilMs: keepUntilMs,
      _provider: provider,
    },
  };
}

function _alertsProviderForFeature(feature) {
  return String(feature?.properties?._provider || '').trim();
}

function _alertsStableVtecKey(props) {
  const vtecRaw = props?.parameters?.VTEC ?? props?.parameters?.vtec;
  const first = Array.isArray(vtecRaw)
    ? (vtecRaw.map(v => String(v || '').trim().toUpperCase()).filter(Boolean)[0] || '')
    : String(vtecRaw || '').trim().toUpperCase();
  if (!first) return '';
  // VTEC: /O.NEW.KTLX.TO.W.0001.dates/ → parts: [O, NEW, KTLX, TO, W, 0001, ...]
  const parts = first.replace(/^\//, '').split('.');
  if (parts.length < 6) return '';
  // Stable key: org.WFO.phenom.sig.eventNum — ignores action (index 1) and time range (index 6+)
  return [parts[0], parts[2], parts[3], parts[4], parts[5]].join('.');
}

function _alertsIdentityKey(feature) {
  const props = feature?.properties || {};
  // Use stable VTEC key (org.WFO.phenom.sig.eventNum) as sole identity for VTEC-bearing alerts.
  // This matches the same warning across upgrades (NEW→CON→UPG) regardless of action or times.
  const stableVtec = _alertsStableVtecKey(props);
  if (stableVtec) return `vtec:${stableVtec}`;

  // Fallback for alerts without VTEC
  const warnClass = _warningClassId(props);
  const event = String(props?.event || props?.eventRaw || '').trim().toUpperCase();
  const headline = String(props?.headline || '').replace(/\s+/g, ' ').trim().toUpperCase();
  const areaDesc = String(props?.areaDesc || props?.area || '').replace(/\s+/g, ' ').trim().toUpperCase();
  const ugcRaw = props?.parameters?.UGC ?? props?.parameters?.ugc;
  const ugc = Array.isArray(ugcRaw)
    ? ugcRaw.map(v => String(v || '').trim().toUpperCase()).filter(Boolean).join(',')
    : String(ugcRaw || '').trim().toUpperCase();
  const issuedMs = _alertsParseTimeMs(props?.sent ?? props?.issued ?? props?.effective ?? props?.onset);
  const expiresMs = _alertsParseTimeMs(props?.expires);
  const issuedBucket = Number.isFinite(issuedMs) ? Math.floor(issuedMs / 60000) : 0;
  const expiresBucket = Number.isFinite(expiresMs) ? Math.floor(expiresMs / 60000) : 0;
  return [warnClass || event, ugc || areaDesc, issuedBucket, expiresBucket, headline].join('|');
}

function _alertsFeatureSourceRank(feature) {
  const source = String(feature?.properties?._source || '').trim().toLowerCase();
  if (source === 'nwws') return 3;
  if (source === 'nws-api') return 2;
  return 1;
}

function _alertsFeatureIssuedRank(feature) {
  const props = feature?.properties || {};
  const issuedMs = _alertsParseTimeMs(props?.sent ?? props?.issued ?? props?.effective ?? props?.onset);
  return Number.isFinite(issuedMs) ? issuedMs : 0;
}

function _alertsPreferredIdentityFeature(current, candidate) {
  if (!candidate) return current || null;
  if (!current) return candidate;

  const sourceDiff = _alertsFeatureSourceRank(candidate) - _alertsFeatureSourceRank(current);
  if (sourceDiff !== 0) return sourceDiff > 0 ? candidate : current;

  const vertexDiff = _alertsGeometryVertexCount(candidate?.geometry) - _alertsGeometryVertexCount(current?.geometry);
  if (vertexDiff !== 0) return vertexDiff > 0 ? candidate : current;

  const issuedDiff = _alertsFeatureIssuedRank(candidate) - _alertsFeatureIssuedRank(current);
  if (issuedDiff !== 0) return issuedDiff > 0 ? candidate : current;

  return candidate;
}

function _alertsCollapseFeaturesByIdentity(features) {
  const collapsed = [];
  const identityIndex = new Map();
  for (const feature of Array.isArray(features) ? features : []) {
    if (!feature) continue;
    const identity = _alertsIdentityKey(feature);
    if (!identity) {
      collapsed.push(feature);
      continue;
    }
    const existingIndex = identityIndex.get(identity);
    if (existingIndex == null) {
      identityIndex.set(identity, collapsed.length);
      collapsed.push(feature);
      continue;
    }
    collapsed[existingIndex] = _alertsPreferredIdentityFeature(collapsed[existingIndex], feature);
  }
  return collapsed;
}

function _alertsFindProviderFeatureByIdentity(provider, identity, excludeId = '') {
  if (!identity) return null;
  const excluded = String(excludeId || '');
  for (const feature of alertsById.values()) {
    if (_alertsProviderForFeature(feature) !== provider) continue;
    const featureId = String(feature?.id || feature?.properties?.id || '');
    if (excluded && featureId === excluded) continue;
    if (_alertsIdentityKey(feature) === identity) return feature;
  }
  return null;
}

function _alertsDeleteProviderIdentityAliases(provider, identity, keepId = '') {
  if (!identity) return 0;
  const kept = String(keepId || '');
  let removed = 0;
  for (const [id, feature] of alertsById.entries()) {
    if (_alertsProviderForFeature(feature) !== provider) continue;
    if (kept && String(id) === kept) continue;
    if (_alertsIdentityKey(feature) !== identity) continue;
    alertsById.delete(id);
    removed += 1;
  }
  return removed;
}

function _alertsClearBootstrapPruneTimer() {
  if (alertsBootstrapPruneTimer == null) return;
  clearTimeout(alertsBootstrapPruneTimer);
  alertsBootstrapPruneTimer = null;
}

function _alertsPruneProviderDuplicates(preferredProvider, duplicateProvider, logContext = '') {
  const preferredIds = new Set();
  const preferredKeys = new Set();
  for (const feature of alertsById.values()) {
    if (_alertsProviderForFeature(feature) !== preferredProvider) continue;
    preferredIds.add(String(feature?.id || ''));
    preferredKeys.add(_alertsIdentityKey(feature));
  }

  let changed = false;
  let removed = 0;
  for (const [id, feature] of alertsById.entries()) {
    if (_alertsProviderForFeature(feature) !== duplicateProvider) continue;
    if (preferredIds.has(String(id)) || preferredKeys.has(_alertsIdentityKey(feature))) {
      alertsById.delete(id);
      changed = true;
      removed += 1;
    }
  }
  void logContext;
  if (changed) _alertsScheduleSourceUpdate();
}

function _alertsPruneBootstrapDuplicates() {
  const liveIds = new Set();
  const liveKeys = new Set();
  for (const feature of alertsById.values()) {
    const provider = _alertsProviderForFeature(feature);
    if (!provider || provider === ALERT_SOURCE_NWS_BOOTSTRAP) continue;
    liveIds.add(String(feature?.id || ''));
    liveKeys.add(_alertsIdentityKey(feature));
  }

  let changed = false;
  for (const [id, feature] of alertsById.entries()) {
    if (_alertsProviderForFeature(feature) !== ALERT_SOURCE_NWS_BOOTSTRAP) continue;
    if (liveIds.has(String(id)) || liveKeys.has(_alertsIdentityKey(feature))) {
      alertsById.delete(id);
      changed = true;
    }
  }
  if (changed) _alertsScheduleSourceUpdate();
}

function _alertsScheduleBootstrapPrune() {
  _alertsClearBootstrapPruneTimer();
  alertsBootstrapPruneTimer = setTimeout(() => {
    alertsBootstrapPruneTimer = null;
    _alertsPruneBootstrapDuplicates();
  }, ALERT_BOOTSTRAP_GRACE_MS);
}

function _isFatalNwwsStatusMessage(message) {
  const text = String(message || '').toLowerCase();
  return (
    text.includes('not-authorized')
    || text.includes('not authorized')
    || text.includes('starttls_failure')
    || text.includes('packet length too long')
    || text.includes('tls_get_more_records')
    || text.includes('client network socket disconnected before secure tls connection was established')
    || text.includes('connection is closing')
    || text.includes('error-reconnecting-too-fast')
    || text.includes('write after end')
    || text.includes('cannot read properties of null')
    || text.includes('maxlistenersexceededwarning')
  );
}

function _stopNwwsBridgeForFatal(message) {
  if (nwwsFatalStopInFlight) return;
  nwwsFatalStopInFlight = true;
  nwwsBridgeStartPromise = null;
  nwwsLastStatusSig = '';
  nwwsLastAlertsGeneratedAt = '';
  nwwsHasPublishedSnapshot = false;
  invoke('stop_nwws_bridge')
    .catch(() => {})
    .finally(() => {
      const text = String(message || 'Fatal NWWS error');
      console.warn('[NWWS] Fatal bridge error — bridge stopped:', text);
      setNwwsCredentialsStatus(`NWWS bridge stopped: ${text}`, true);
      applyAlertSourceMode();
    });
}

function _alertsReplaceNormalizedCollection(features, provider, opts = {}) {
  const normalized = _alertsCollapseFeaturesByIdentity(
    Array.isArray(features) ? features.filter(Boolean) : [],
  );
  const removeMissing = opts.removeMissing !== false;
  const activeIds = new Set();
  let changed = false;
  const nowMs = Date.now();
  const seedMode = !alertsSeeded;
  const warningChanges = [];

  for (const next of normalized) {
    activeIds.add(next.id);

    const identity = _alertsIdentityKey(next);
    let prev = alertsById.get(next.id);
    if (!prev && identity) {
      prev = _alertsFindProviderFeatureByIdentity(provider, identity, next.id);
    }
    if (identity) {
      const removedAliases = _alertsDeleteProviderIdentityAliases(provider, identity, next.id);
      if (removedAliases > 0) changed = true;
    }

    const prevId = String(prev?.id || prev?.properties?.id || '');
    const sameIdentityReplacement = !!prev && !!prevId && prevId !== String(next.id);
    const prevFlashUntil = Number(prev?.properties?._flashUntilMs);
    if (Number.isFinite(prevFlashUntil) && prevFlashUntil > nowMs) {
      next.properties._flashUntilMs = prevFlashUntil;
    } else if (!prev && !seedMode) {
      next.properties._flashUntilMs = nowMs + 10_000;
    }

    if (
      !prev
      || sameIdentityReplacement
      || JSON.stringify(prev.properties) !== JSON.stringify(next.properties)
      || JSON.stringify(prev.geometry) !== JSON.stringify(next.geometry)
    ) {
      alertsById.set(next.id, next);
      changed = true;
      if (warningNotificationsPrimed && !seedMode) {
        const kind = _warningChangeKind(prev, next);
        if (kind) warningChanges.push({ feature: next, kind });
      }
    }
  }

  if (removeMissing) {
    for (const [id, feature] of alertsById.entries()) {
      if (_alertsProviderForFeature(feature) !== provider) continue;
      if (!activeIds.has(id)) {
        if (warningNotificationsPrimed && !seedMode) {
          const kind = _warningChangeKind(feature, null, { removed: true });
          if (kind) warningChanges.push({ feature, kind });
        }
        alertsById.delete(id);
        changed = true;
      }
    }
  }

  if (!alertsSeeded) alertsSeeded = true;
  if (changed) _alertsScheduleSourceUpdate();
  else _ensureOverlayFlashTicker();
  if (warningChanges.length) _logWarningChanges(warningChanges);
  if (warningChanges.length) _announceWarningChanges(warningChanges);
}

function _alertsNormalizeExternalFeature(feature, provider = ALERT_SOURCE_NWWS) {
  const geomType = String(feature?.geometry?.type || '');
  const coordinates = feature?.geometry?.coordinates;
  if (!['Polygon', 'MultiPolygon', 'Point'].includes(geomType)) return null;
  if (!Array.isArray(coordinates) || coordinates.length === 0) return null;

  const props = feature?.properties || {};
  const eventRaw = String(props?.eventRaw || props?.event || '').trim();
  const event = eventRaw || 'Unknown Alert';
  if (/special weather statement/i.test(event) && !_alertsIsStormBasedSpecialWeatherStatement(props)) return null;
  if (/special weather statement/i.test(event) && _alertsGeometryVertexCount(feature?.geometry) > 25) return null;
  const id = String(feature?.id || props?.id || props?.tracking || '').trim();
  if (!id) return null;

  const sentMs = _alertsParseTimeMs(
    props?.sent
    ?? props?.issued
    ?? props?.effective
    ?? props?.onset,
  );
  const expiresMs = _alertsParseTimeMs(props?.expires);
  const keepUntilMs = Number.isFinite(expiresMs)
    ? expiresMs
    : (Number.isFinite(sentMs) ? sentMs + ALERT_DEFAULT_KEEP_MS : Date.now() + ALERT_DEFAULT_KEEP_MS);

  return {
    type: 'Feature',
    id,
    geometry: {
      type: geomType,
      coordinates,
    },
    properties: {
      ...(props || {}),
      id,
      event,
      eventRaw: eventRaw || event,
      _warnClass: _resolvedWarningClass({
        ...(props || {}),
        event,
        eventRaw: eventRaw || event,
      }),
      messageType: String(props?.messageType || props?.action || 'Alert'),
      sent: Number.isFinite(sentMs) ? new Date(sentMs).toISOString() : null,
      expires: Number.isFinite(expiresMs) ? new Date(expiresMs).toISOString() : null,
      _keepUntilMs: keepUntilMs,
      _provider: provider,
    },
  };
}

function _alertsReplaceProviderCollection(collection, provider = ALERT_SOURCE_NWWS) {
  const features = Array.isArray(collection?.features) ? collection.features : [];
  const normalized = features
    .map(feature => _alertsNormalizeExternalFeature(feature, provider))
    .filter(Boolean);
  _alertsReplaceNormalizedCollection(normalized, provider);
}

async function bootstrapNwsApiWarnings() {
  if (!alertsVisible) return;
  if (nwsBootstrapCompleted) return;
  if (nwsBootstrapPromise) return nwsBootstrapPromise;

  nwsBootstrapPromise = (async () => {
    let raw = null;
    try {
      raw = await _fetchGeoJsonViaTauri(NWS_API_ALERTS_URL);
    } catch (err) {
      console.warn('[NWS bootstrap] fetch failed:', err?.message || String(err));
      return;
    }

    const features = Array.isArray(raw?.features) ? raw.features : [];
    const normalized = features
      .map(feature => _alertsNormalizeNwsApiFeature(feature, ALERT_SOURCE_NWS_BOOTSTRAP))
      .filter(feature => feature && _warningEnabledForUi(feature.properties));

    _alertsReplaceNormalizedCollection(normalized, ALERT_SOURCE_NWS_BOOTSTRAP);
    if (nwwsHasPublishedSnapshot) {
      _alertsPruneBootstrapDuplicates();
      _alertsScheduleBootstrapPrune();
    }
    nwsBootstrapCompleted = true;
  })()
    .finally(() => {
      nwsBootstrapPromise = null;
    });

  return nwsBootstrapPromise;
}

async function ensureNwwsBridge() {
  if (!nwwsBridgeListenersReady && typeof listen === 'function') {
    nwwsBridgeListenersReady = true;

    await listen('nwws-status', evt => {
      const payload = evt?.payload || {};
      const phase = String(payload?.phase || '').trim();
      const message = String(payload?.message || '').trim();
      const alertCount = Number(payload?.alertCount);
      const sig = `${phase}|${message}|${Number.isFinite(alertCount) ? alertCount : ''}`;
      if (sig && sig !== nwwsLastStatusSig) {
        nwwsLastStatusSig = sig;
        if (phase === 'error' || phase === 'reconnecting') {
          console.warn('[NWWS]', message || phase);
        }
      }
      if (phase === 'error' && message) {
        setNwwsCredentialsStatus(message, true);
        if (_isFatalNwwsStatusMessage(message) && !nwwsFatalStopInFlight) {
          _stopNwwsBridgeForFatal(message);
        }
      } else if (phase === 'connected') {
        nwwsFatalStopInFlight = false;
        setNwwsCredentialsStatus('Connected');
      }
      if (phase === 'starting' || phase === 'reconnecting' || phase === 'error') {
        _resetWarningNotificationPriming();
      } else if (phase === 'connected') {
        _scheduleWarningNotificationPriming();
      }
    });

    await listen('nwws-alerts', evt => {
      const payload = evt?.payload || {};
      const generatedAt = String(payload?.generatedAt || '').trim();
      if (generatedAt && generatedAt === nwwsLastAlertsGeneratedAt) return;
      if (generatedAt) nwwsLastAlertsGeneratedAt = generatedAt;
      const bridgeFeatures = Array.isArray(payload?.features) ? payload.features : [];
      const liveFeatures = bridgeFeatures.filter(feature => String(feature?.properties?._source || '').trim().toLowerCase() === 'nwws');
      if (liveFeatures.length > 0) {
        nwwsHasPublishedSnapshot = true;
        _scheduleWarningNotificationPriming();
      }
      _alertsReplaceProviderCollection({
        ...payload,
        features: liveFeatures,
      }, ALERT_SOURCE_NWWS);
      if (liveFeatures.length > 0) {
        _alertsPruneProviderDuplicates(ALERT_SOURCE_NWWS, ALERT_SOURCE_NWS_API, 'NWWS update');
        _alertsPruneBootstrapDuplicates();
        _alertsScheduleBootstrapPrune();
      }
    });

    await listen('nwws-log', evt => {
      const payload = evt?.payload;
      if (typeof payload === 'string') {
        const text = String(payload || '').trim();
        if (text) {
          const line = /^\[NWWS(?: DEBUG)?\]/.test(text) ? text : `[NWWS] ${text}`;
          if (/NWWS bridge (stdout|stderr) stream closed/i.test(line)) return;
          console.info(line);
        }
        return;
      }
      const level = String(payload?.level || 'info').toLowerCase();
      const message = String(payload?.message || '').trim();
      if (!message) return;
      const line = /^\[NWWS(?: DEBUG)?\]/.test(message) ? message : `[NWWS] ${message}`;
      if (/NWWS bridge stderr stream closed/i.test(message)) return;
      if (level === 'error') {
        console.warn(line);
        if (_isFatalNwwsStatusMessage(message)) _stopNwwsBridgeForFatal(message);
      }
      else if (level === 'debug') {
        console.info(line);
      }
      else if (level === 'warn') {
        if (message === 'NWWS bridge stdout stream closed' && _shouldUseNwwsBridge() && !nwwsBridgeRestartPending) {
          nwwsBridgeRestartPending = true;
          nwwsBridgeStartPromise = null;
          console.info('[NWWS] Bridge process ended unexpectedly; scheduling restart in 5 s');
          setTimeout(() => {
            nwwsBridgeRestartPending = false;
            if (_shouldUseNwwsBridge()) {
              console.info('[NWWS] Restarting bridge after unexpected exit');
              ensureNwwsBridge().catch(err => console.warn('[NWWS] Restart failed:', err));
            }
          }, 5000);
          return;
        }
        console.warn(line);
      }
      else console.info(line);
    });
  }

  const creds = _getNwwsBridgeCredentials();
  if (!creds.configured) {
    setNwwsCredentialsStatus('Not configured');
    nwwsBridgeStartPromise = null;
    return Promise.resolve();
  }

  if (nwwsBridgeStartPromise) return nwwsBridgeStartPromise;
  nwwsBridgeStartPromise = invoke('start_nwws_bridge', {
    username: creds.username,
    password: creds.password,
  })
    .catch(err => {
      nwwsBridgeStartPromise = null;
      setNwwsCredentialsStatus(err?.message || String(err), true);
      console.error('[NWWS] bridge start failed:', err?.message || String(err));
      throw err;
    });
  return nwwsBridgeStartPromise;
}

async function refreshNwsApiAlerts(opts = {}) {
  const provider = String(opts.provider || ALERT_SOURCE_NWS_API);
  const removeMissing = opts.removeMissing !== false;

  let raw = null;
  try {
    raw = await _fetchGeoJsonViaTauri(NWS_API_ALERTS_URL);
  } catch (err) {
    console.warn('[NWS API] fetch failed:', err?.message || String(err));
    return;
  }

  const features = Array.isArray(raw?.features) ? raw.features : [];
  const normalized = features
    .map(feature => _alertsNormalizeNwsApiFeature(feature, provider))
    .filter(Boolean);
  _alertsReplaceNormalizedCollection(normalized, provider, { removeMissing });
  console.info(`[NWS API] refreshed ${features.length} alert(s) for provider ${provider}`);
}

function startNwsApiPolling() {
  nwsApiPollEnforceMode = false;
  if (!nwsApiPollProvider) nwsApiPollProvider = ALERT_SOURCE_NWS_API;
  console.info(`[NWS API] Starting alert polling (${nwsApiPollProvider}) every ${NWS_API_POLL_MS} ms`);
  if (nwsApiPollTimer == null) {
    nwsApiPollTimer = setInterval(() => {
      refreshNwsApiAlerts({
        enforceMode: nwsApiPollEnforceMode,
        provider: nwsApiPollProvider,
        removeMissing: true,
      });
    }, NWS_API_POLL_MS);
  }
  refreshNwsApiAlerts({
    enforceMode: nwsApiPollEnforceMode,
    provider: nwsApiPollProvider,
    removeMissing: true,
  });
}

function stopNwsApiPolling() {
  if (nwsApiPollTimer == null) return;
  clearInterval(nwsApiPollTimer);
  nwsApiPollTimer = null;
}

function applyAlertSourceMode() {
  const useNwws = _shouldUseNwwsBridge();
  const useNwsApi = _shouldUseNwsApiAlerts();
  alertSourceMode = useNwws ? ALERT_SOURCE_NWWS : ALERT_SOURCE_NWS_API;
  _resetWarningNotificationPriming();
  _scheduleWarningNotificationPriming();
  if (useNwws) {
    stopNwsApiPolling();
    if (alertsVisible) {
      _alertsClearProviderFeatures(ALERT_SOURCE_NWS_API);
      bootstrapNwsApiWarnings().catch(err => {
        console.warn('[NWWS] bootstrap failed:', err?.message || String(err));
      });
    } else {
      _alertsClearProviderFeatures(ALERT_SOURCE_NWS_API);
      _alertsClearProviderFeatures(ALERT_SOURCE_NWS_BOOTSTRAP);
    }
    ensureNwwsBridge().catch(() => {});
  } else {
    stopNwsApiPolling();
    if (nwwsBridgeStartPromise || nwwsHasPublishedSnapshot || nwwsLastAlertsGeneratedAt) {
      invoke('stop_nwws_bridge').catch(() => {});
    }
    nwwsBridgeStartPromise = null;
    nwwsLastStatusSig = '';
    nwwsLastAlertsGeneratedAt = '';
    nwwsHasPublishedSnapshot = false;
    _alertsClearProviderFeatures(ALERT_SOURCE_NWWS);
    _alertsClearProviderFeatures(ALERT_SOURCE_NWS_BOOTSTRAP);
    if (useNwsApi && alertsVisible) {
      nwsApiPollProvider = ALERT_SOURCE_NWS_API;
      startNwsApiPolling();
    } else {
      _alertsClearProviderFeatures(ALERT_SOURCE_NWS_API);
    }
    if (!nwwsEnabled) setNwwsCredentialsStatus('Disabled');
    else if (!_getNwwsBridgeCredentials().configured) setNwwsCredentialsStatus('Missing credentials');
  }
  syncNwwsSettingsUi();
}

function initAlertLayers() {
  if (alertsMapReady) return;

  map.addSource('alerts-src', {
    type: 'geojson',
    data: ALERTS_EMPTY_GEOJSON,
  });

  map.addLayer({
    id: 'alerts-fill',
    type: 'fill',
    source: 'alerts-src',
    filter: ['==', ['geometry-type'], 'Polygon'],
    paint: {
      'fill-color': _alertsFillColorExpr('#FFFFFF'),
      'fill-opacity': ['coalesce', ['get', '_fillOpacity'], 0],
    },
  }, 'stations-dot');

  map.addLayer({
    id: 'alerts-line-under',
    type: 'line',
    source: 'alerts-src',
    filter: ['==', ['geometry-type'], 'Polygon'],
    layout: {
      'line-join': 'round',
      'line-cap': 'round',
    },
    paint: {
      'line-color': '#000000',
      'line-width': _alertsLineWidthExpr(false),
      'line-opacity': 0.98,
    },
  }, 'stations-dot');

  map.addLayer({
    id: 'alerts-fill-hit',
    type: 'fill',
    source: 'alerts-src',
    filter: ['==', ['geometry-type'], 'Polygon'],
    paint: {
      'fill-color': '#000000',
      'fill-opacity': 0.001,
    },
  }, 'stations-dot');

  map.addLayer({
    id: 'alerts-line',
    type: 'line',
    source: 'alerts-src',
    filter: ['==', ['geometry-type'], 'Polygon'],
    layout: {
      'line-join': 'round',
      'line-cap': 'round',
    },
    paint: {
      'line-color': _alertsColorExpr('#FFFFFF'),
      'line-color-transition': { duration: 260, delay: 0 },
      'line-width': _alertsLineWidthExpr(true),
      'line-opacity': 0.98,
    },
  }, 'stations-dot');

  map.addLayer({
    id: 'alerts-point',
    type: 'circle',
    source: 'alerts-src',
    filter: ['==', ['geometry-type'], 'Point'],
    paint: {
      'circle-color': _alertsColorExpr('#FFFFFF'),
      'circle-color-transition': { duration: 260, delay: 0 },
      'circle-radius': ['interpolate', ['linear'], ['zoom'], 4, 3.5, 8, 5, 12, 7],
      'circle-stroke-color': '#000000',
      'circle-stroke-width': 1.2,
      'circle-opacity': 0.95,
    },
  }, 'stations-dot');

  const openAlertPopup = e => _openAlertPopupOnMap(map, e);
  map.on('mouseenter', 'alerts-fill-hit', () => { map.getCanvas().style.cursor = 'pointer'; });
  map.on('mouseleave', 'alerts-fill-hit', () => { map.getCanvas().style.cursor = ''; });
  map.on('click', 'alerts-fill-hit', openAlertPopup);
  map.on('mouseenter', 'alerts-line', () => { map.getCanvas().style.cursor = 'pointer'; });
  map.on('mouseleave', 'alerts-line', () => { map.getCanvas().style.cursor = ''; });
  map.on('click', 'alerts-line', openAlertPopup);
  map.on('mouseenter', 'alerts-point', () => { map.getCanvas().style.cursor = 'pointer'; });
  map.on('mouseleave', 'alerts-point', () => { map.getCanvas().style.cursor = ''; });
  map.on('click', 'alerts-point', openAlertPopup);

  alertsMapReady = true;
  _alertsApplySourceDataNow();
  _applyOverlayFlashPaints();
  _setAlertLayersVisible(alertsVisible);
}

function selectionLabel(family, tilt) {
  return `${family} ${normalizeTilt(tilt)}°`;
}

function buildProductCandidates(family, tilt, opts = {}) {
  const crossTilt = !!opts.crossTilt;
  const map = FAMILY_PRODUCTS[family] || FAMILY_PRODUCTS.REF;
  const selectedTilt = normalizeTilt(tilt);
  const orderedTilts = crossTilt
    ? [selectedTilt, ...TILT_VALUES.filter(t => t !== selectedTilt)]
    : [selectedTilt];
  const out = [];

  orderedTilts.forEach(t => {
    (map[t] || []).forEach(code => {
      if (!out.includes(code)) out.push(code);
    });
  });

  return out;
}

const latestKeyCache = new Map();
const MAX_FRESH_AGE_DAYS = 2;

async function resolveL3Selection(stationId, family, tilt, maxFrames = 1, currentOnly = false) {
  try {
    const res = await invoke('l3_resolve_selection', {
      stationId,
      family,
      tilt: normalizeTilt(tilt),
      maxFrames,
      maxFreshAgeDays: MAX_FRESH_AGE_DAYS,
      currentOnly,
      source: stationSource(stationId),
      stationKind: stationKind(stationId),
    });
    return res || {};
  } catch (_) {
    return { latest: null, history: [], availableProducts: [] };
  }
}

function keyAgeDays(key) {
  const ts = parseKeyTimestampMs(key);
  if (!Number.isFinite(ts)) return null;
  return (Date.now() - ts) / 86400000;
}

function isFreshKey(key, maxAgeDays = MAX_FRESH_AGE_DAYS) {
  const age = keyAgeDays(key);
  return age != null && age <= maxAgeDays;
}

async function findLatestKeyForProduct(stationId, product, allowHistorical = false) {
  if (stationSource(stationId) === 'tgftp') {
    const familyTilt = PRODUCT_TO_FAMILY_TILT[String(product || '').toUpperCase()];
    if (!familyTilt) return null;
    const res = await resolveL3Selection(
      stationId,
      familyTilt.family,
      familyTilt.tilt,
      1,
      false,
    );
    return res?.latest?.key || null;
  }

  const sid = id3(stationId);
  const prefix = `${sid}_${product}_`;
  const cacheId = `${sid}:${product}`;

  const cached = latestKeyCache.get(cacheId);
  if (cached) {
    const newer = await findNewestKeySince(prefix, cached, 8);
    if (newer) {
      if (!allowHistorical && !isFreshKey(newer)) return null;
      latestKeyCache.set(cacheId, newer);
      return newer;
    }
    if (!allowHistorical && !isFreshKey(cached)) return null;
    return cached;
  }

  const lookbackDays = allowHistorical
    ? [7, 14, 30, 120, 365, 730]
    : [0.5, 1, MAX_FRESH_AGE_DAYS];

  for (const days of lookbackDays) {
    const startAfter = `${prefix}${flatDate(new Date(Date.now() - days * 86400000))}`;
    const newest = await findNewestKeySince(prefix, startAfter, 30);
    if (newest) {
      if (!allowHistorical && !isFreshKey(newest)) continue;
      latestKeyCache.set(cacheId, newest);
      return newest;
    }
  }

  if (!allowHistorical) return null;

  let newest = null;
  let token = '';
  for (let i = 0; i < 900; i += 1) {
    const { keys, next } = await s3ListPage(prefix, { continuationToken: token, maxKeys: 1000 });
    if (keys.length) newest = keys[keys.length - 1];
    if (!next) break;
    token = next;
  }

  if (newest) latestKeyCache.set(cacheId, newest);
  return newest;
}

async function findLatestKey(stationId, selection) {
  const requestedFamily = selection?.family || 'REF';
  const requestedTilt = normalizeTilt(selection?.tilt || '0.5');
  const requestedLabel = selectionLabel(requestedFamily, requestedTilt);
  if (_canUseProcessedWise(stationId, requestedFamily, requestedTilt)) {
    const result = await invoke('list_wise_frames', {
      station: canonicalStationId(stationId),
      family:  String(requestedFamily).trim().toUpperCase(),
      tilt:    requestedTilt,
      maxFrames: 1,
    });
    const frames = Array.isArray(result?.frames) ? result.frames : [];
    if (frames.length) {
      const meta = _buildProcessedWiseMeta(stationId, requestedFamily, result.tilt || requestedTilt, frames[frames.length - 1]);
      if (meta?.key) return meta;
    }
    throw new Error(`${stationId} ${requestedLabel} not found in processed feed`);
  }
  // Fast path: current-only probe returns quickly and avoids long "Connecting..." stalls.
  const fast = await resolveL3Selection(stationId, requestedFamily, requestedTilt, 1, true);
  if (fast?.latest?.key) return fast.latest;

  const res = await resolveL3Selection(stationId, requestedFamily, requestedTilt, 1, false);
  if (res?.latest?.key) return res.latest;

  const available = Array.isArray(res?.availableProducts) ? res.availableProducts : [];
  if (available.length) {
    throw new Error(`No data for ${stationId} ${requestedLabel}. Available products: ${available.join(', ')}`);
  }

  throw new Error(`${stationId} ${requestedLabel} not found in active feed`);
}

async function findLatestKeyCurrentOnly(stationId, selection) {
  const requestedFamily = selection?.family || 'REF';
  const requestedTilt = normalizeTilt(selection?.tilt || '0.5');
  if (_canUseProcessedWise(stationId, requestedFamily, requestedTilt)) {
    try {
      const result = await invoke('list_wise_frames', {
        station: canonicalStationId(stationId),
        family:  String(requestedFamily).trim().toUpperCase(),
        tilt:    requestedTilt,
        maxFrames: 1,
      });
      const frames = Array.isArray(result?.frames) ? result.frames : [];
      if (frames.length) {
        const meta = _buildProcessedWiseMeta(stationId, requestedFamily, result.tilt || requestedTilt, frames[frames.length - 1]);
        if (meta?.key) return meta;
      }
    } catch (_) {}
    return null;
  }
  const res = await resolveL3Selection(stationId, requestedFamily, requestedTilt, 1, true);
  return res?.latest?.key ? res.latest : null;
}

// Parse the 64-byte RDAR binary blob returned by the backend into a frame object
// with typed array views (zero-copy — all arrays point into the original ArrayBuffer).
function parseRadarBinaryBlob(buffer) {
  const dv = new DataView(buffer);
  const magic = String.fromCharCode(dv.getUint8(0), dv.getUint8(1), dv.getUint8(2), dv.getUint8(3));

  // ── WDAR format (Python WISE decode) ──────────────────────────────────────
  if (magic === 'WDAR') {
    let o = 4;
    const vertex_count      = dv.getUint32(o, true); o += 4;
    const gate_count        = dv.getUint32(o, true); o += 4;
    const source_gate_count = dv.getUint32(o, true); o += 4;
    const elevation         = dv.getFloat32(o, true); o += 4;
    const station_lat       = dv.getFloat32(o, true); o += 4;
    const station_lon       = dv.getFloat32(o, true); o += 4;
    const scan_time_ms      = dv.getFloat64(o, true); o += 8;
    o += 4;                                                    // unused slot
    const decimated         = dv.getUint8(o) !== 0;  o += 1;
    const has_types         = dv.getUint8(o) !== 0;  o += 1;
    o += 4;                                                    // padding (h + H)
    // field_name: 16 bytes null-padded at offset 46
    const fieldRaw = new Uint8Array(buffer, 46, 16);
    const nullIdx  = fieldRaw.indexOf(0);
    const field    = new TextDecoder().decode(fieldRaw.slice(0, nullIdx < 0 ? 16 : nullIdx));
    o = 64;

    let _bufXy = null, _bufColor = null, _bufVals = null, _bufTypes = null;
    if (vertex_count > 0) {
      _bufXy    = new Float32Array(buffer, o, vertex_count * 2); o += vertex_count * 2 * 4;
      _bufColor = new Uint8Array(buffer, o, vertex_count * 4);   o += vertex_count * 4;
      _bufVals  = new Float32Array(buffer, o, vertex_count);     o += vertex_count * 4;
      if (has_types) {
        _bufTypes = new Uint8Array(buffer, o, vertex_count);
      }
    }
    const scan_time = scan_time_ms > 0 ? new Date(scan_time_ms).toISOString() : null;
    return {
      vertex_count, gate_count, source_gate_count,
      elevation, station_lat, station_lon, scan_time,
      product_code: 0, decimated, field,
      l2_product_mask: 0, l2_available_products: [],
      l2_tilt_idx: undefined, l2_tilts: undefined,
      _bufXy, _bufColor, _bufVals, _bufTypes,
    };
  }

  // ── RDAR format (L3 / L2 Python backend) ──────────────────────────────────
  if (magic !== 'RDAR') throw new Error(`Bad binary magic from backend: ${magic}`);

  let o = 4;
  const vertex_count      = dv.getUint32(o, true); o += 4;
  const gate_count        = dv.getUint32(o, true); o += 4;
  const source_gate_count = dv.getUint32(o, true); o += 4;
  const elevation         = dv.getFloat32(o, true); o += 4;
  const station_lat       = dv.getFloat32(o, true); o += 4;
  const station_lon       = dv.getFloat32(o, true); o += 4;
  const scan_time_ms      = dv.getFloat64(o, true); o += 8;
  const product_code      = dv.getUint32(o, true); o += 4;
  const decimated         = dv.getUint8(o) !== 0;  o += 1;
  const field_name_len    = dv.getUint8(o);         o += 1;
  const l2_tilt_idx       = dv.getInt16(o, true);   o += 2;
  const l2_tilts_count    = dv.getUint16(o, true);  o += 2;
  // field_name: 16 bytes null-padded, then 2 bytes L2 product mask (total header = 64)
  const field = new TextDecoder().decode(new Uint8Array(buffer, o, field_name_len));
  o += 16;
  const l2_product_mask = dv.getUint16(o, true); o += 2;

  // Typed array views (zero-copy)
  let _bufXy = null, _bufColor = null, _bufVals = null;
  if (vertex_count > 0) {
    _bufXy    = new Float32Array(buffer, o, vertex_count * 2); o += vertex_count * 2 * 4;
    _bufColor = new Uint8Array(buffer, o, vertex_count * 4);   o += vertex_count * 4;
    _bufVals  = new Float32Array(buffer, o, vertex_count);     o += vertex_count * 4;
  }

  const l2_tilts = [];
  for (let i = 0; i < l2_tilts_count; i++) {
    l2_tilts.push(dv.getFloat32(o, true)); o += 4;
  }

  const scan_time = scan_time_ms > 0 ? new Date(scan_time_ms).toISOString() : null;

  return {
    vertex_count, gate_count, source_gate_count,
    elevation, station_lat, station_lon, scan_time,
    product_code, decimated, field,
    l2_product_mask,
    l2_available_products: _productsFromL2Mask(l2_product_mask),
    l2_tilt_idx: l2_tilt_idx >= 0 ? l2_tilt_idx : undefined,
    l2_tilts:    l2_tilts_count > 0 ? l2_tilts : undefined,
    _bufXy, _bufColor, _bufVals,
  };
}

function _prepareInlinePalette(palData) {
  if (!palData) return null;
  const scale = Number.isFinite(Number(palData.scale)) ? Number(palData.scale) : 1.0;
  if (Array.isArray(palData.colors) && palData.colors.length) {
    const colors = [];
    for (const color of palData.colors) {
      if (!Array.isArray(color) || color.length < 3) continue;
      colors.push([
        Math.max(0, Math.min(255, Number(color[0]) || 0)),
        Math.max(0, Math.min(255, Number(color[1]) || 0)),
        Math.max(0, Math.min(255, Number(color[2]) || 0)),
        Math.max(0, Math.min(255, Number.isFinite(Number(color[3])) ? Number(color[3]) : 255)),
      ]);
    }
    if (colors.length) {
      return {
        scale,
        min: Number.isFinite(Number(palData.min)) ? Number(palData.min) : 0,
        max: Number.isFinite(Number(palData.max)) ? Number(palData.max) : colors.length - 1,
        lookupStep: Number.isFinite(Number(palData.lookupStep)) ? Number(palData.lookupStep) : 1,
        colors,
      };
    }
  }
  const discrete = String(palData.mode || '').trim().toLowerCase() === 'discrete';
  if (!Array.isArray(palData.stops) || palData.stops.length < 2) return null;
  const rows = [];
  const seen = new Map();
  for (const stop of palData.stops) {
    if (!Array.isArray(stop) || stop.length < 4) continue;
    const value = Number(stop[0]);
    if (!Number.isFinite(value)) continue;
    const row = [
      value,
      Math.max(0, Math.min(255, Number(stop[1]) || 0)),
      Math.max(0, Math.min(255, Number(stop[2]) || 0)),
      Math.max(0, Math.min(255, Number(stop[3]) || 0)),
      Math.max(0, Math.min(255, Number.isFinite(Number(stop[4])) ? Number(stop[4]) : 255)),
    ];
    if (discrete) rows.push(row);
    else seen.set(value, row);
  }
  if (!discrete) rows.push(...seen.values());
  rows.sort((a, b) => a[0] - b[0]);
  if (rows.length < 2) return null;

  const xp = new Float32Array(rows.length);
  const fp = new Float32Array(rows.length * 4);
  for (let i = 0; i < rows.length; i += 1) {
    xp[i] = rows[i][0];
    fp[(i * 4) + 0] = rows[i][1];
    fp[(i * 4) + 1] = rows[i][2];
    fp[(i * 4) + 2] = rows[i][3];
    fp[(i * 4) + 3] = rows[i][4];
  }
  return {
    scale,
    mode: discrete ? 'discrete' : (palData.mode || ''),
    xp,
    fp,
  };
}

function _writePreparedPaletteColor(palette, rawValue, target, offset) {
  if (!palette || !target) {
    target[offset + 0] = 255;
    target[offset + 1] = 255;
    target[offset + 2] = 255;
    target[offset + 3] = 255;
    return;
  }

  const scaled = Number(rawValue) * (Number.isFinite(Number(palette.scale)) ? Number(palette.scale) : 1.0);
  const colors = palette.colors;
  if (Array.isArray(colors) && colors.length) {
    const min = Number.isFinite(Number(palette.min)) ? Number(palette.min) : 0;
    const max = Number.isFinite(Number(palette.max)) ? Number(palette.max) : min + colors.length - 1;
    const clamped = Math.max(min, Math.min(max, scaled));
    const lookupStep = Number.isFinite(Number(palette.lookupStep)) && Number(palette.lookupStep) > 0 ? Number(palette.lookupStep) : null;
    const denom = Math.max(max - min, 1e-10);
    const rawIndex = lookupStep
      ? Math.round((clamped - min) / lookupStep)
      : Math.floor(((clamped - min) / denom) * (colors.length - 1));
    const index = Math.max(0, Math.min(colors.length - 1, rawIndex));
    const color = colors[index] || colors[colors.length - 1];
    target[offset + 0] = color[0];
    target[offset + 1] = color[1];
    target[offset + 2] = color[2];
    target[offset + 3] = color[3];
    return;
  }

  const xp = palette.xp;
  const fp = palette.fp;
  if (!xp || !fp || xp.length < 1) {
    target[offset + 0] = 255;
    target[offset + 1] = 255;
    target[offset + 2] = 255;
    target[offset + 3] = 255;
    return;
  }
  let idx = 0;
  const last = xp.length - 1;

  if (palette.mode === 'discrete') {
    while (idx < last && scaled >= xp[idx + 1]) idx += 1;
    const base = idx * 4;
    target[offset + 0] = fp[base + 0];
    target[offset + 1] = fp[base + 1];
    target[offset + 2] = fp[base + 2];
    target[offset + 3] = fp[base + 3];
    return;
  }

  if (scaled <= xp[0]) {
    idx = 0;
  } else if (scaled >= xp[last]) {
    idx = last;
  } else {
    while (idx < last - 1 && scaled > xp[idx + 1]) idx += 1;
    const x0 = xp[idx];
    const x1 = xp[idx + 1];
    const t = Math.max(0, Math.min(1, (scaled - x0) / Math.max(x1 - x0, 1e-10)));
    const base = idx * 4;
    const next = (idx + 1) * 4;
    target[offset + 0] = Math.round(fp[base + 0] + t * (fp[next + 0] - fp[base + 0]));
    target[offset + 1] = Math.round(fp[base + 1] + t * (fp[next + 1] - fp[base + 1]));
    target[offset + 2] = Math.round(fp[base + 2] + t * (fp[next + 2] - fp[base + 2]));
    target[offset + 3] = Math.round(fp[base + 3] + t * (fp[next + 3] - fp[base + 3]));
    return;
  }

  const base = idx * 4;
  target[offset + 0] = fp[base + 0];
  target[offset + 1] = fp[base + 1];
  target[offset + 2] = fp[base + 2];
  target[offset + 3] = fp[base + 3];
}

const WISE_PRT_PALETTE_SECTIONS = Object.freeze({
  RAIN: Object.freeze([
    [-30.0,  53,   8,  72, 255],
    [-12.0,  53,   8,  72, 255],
    [-10.0,  59,  33,  64, 255],
    [ -5.0,  64,  63,  66, 255],
    [  0.0, 118, 117, 118, 255],
    [  5.0, 188, 187, 187, 255],
    [ 10.0,  63,  94, 161, 255],
    [ 15.0,  92, 171, 216, 255],
    [ 20.0,  35, 187,  83, 255],
    [ 25.0,   2, 154,  11, 255],
    [ 30.0,   0, 115,   5, 255],
    [ 35.0,   0,  77,   0, 255],
    [ 40.0, 255, 214,   0, 255],
    [ 45.0, 255, 173,   0, 255],
    [ 50.0, 255,  23,   0, 255],
    [ 55.0, 213,  18,   3, 255],
    [ 60.0,  96,   8,   0, 255],
    [ 65.0, 255, 191, 253, 255],
    [ 70.0, 200, 117, 199, 255],
    [ 75.0, 255, 252, 255, 255],
    [ 80.0, 255, 252, 255, 255],
    [ 90.0, 255, 252, 255, 255],
  ]),
  SNOW: Object.freeze([
    [-30.0,  36, 115, 132, 255],
    [-10.0,  36, 115, 132, 255],
    [  0.0,   2, 117, 255, 255],
    [ 50.0,   0,   0,  50, 255],
    [ 70.0,   0,   0,  36, 255],
    [ 80.0,   0,   0,  26, 255],
    [ 90.0,   0,   0,  26, 255],
  ]),
  SLEET: Object.freeze([
    [-30.0, 128,  64, 192, 255],
    [-10.0, 128,  64, 192, 255],
    [  0.0, 160,  96, 224, 255],
    [ 50.0, 192, 128, 240, 255],
    [ 70.0, 120,  60, 178, 255],
    [ 80.0,  96,  40, 150, 255],
    [ 90.0,  96,  40, 150, 255],
  ]),
  FRZR: Object.freeze([
    [-30.0, 121,  93,  89, 255],
    [-10.0, 121,  93,  89, 255],
    [  0.0, 224,  80,  68, 255],
    [ 50.0,  34,  17,  20, 255],
    [ 70.0,  58,  26,  34, 255],
    [ 80.0,  42,  20,  24, 255],
    [ 90.0,  42,  20,  24, 255],
  ]),
});

let _wisePrtPreparedPalette = null;

function _prepareWisePrtPalette() {
  if (_wisePrtPreparedPalette) return _wisePrtPreparedPalette;
  const combinedStops = [];
  WISE_PRT_SECTION_ORDER.forEach((section, index) => {
    const stops = WISE_PRT_PALETTE_SECTIONS[section] || [];
    const offset = WISE_MULTI_TYPE_RANGE_SPAN * index;
    stops.forEach(stop => {
      combinedStops.push([
        Number(stop[0]) + offset,
        stop[1],
        stop[2],
        stop[3],
        stop[4],
      ]);
    });
  });
  _wisePrtPreparedPalette = _prepareInlinePalette({ scale: 1, stops: combinedStops });
  return _wisePrtPreparedPalette;
}

function _wiseFieldNameForFamily(family) {
  const f = String(family || '').trim().toUpperCase();
  if (f === 'CC') return 'cross_correlation_ratio';
  if (f === 'ZDR') return 'differential_reflectivity';
  if (f === 'ET' || f === 'EET') return 'echo_top';
  if (f === 'SRV') return 'storm_relative_velocity';
  if (f === 'VEL') return 'velocity';
  if (f === 'SW') return 'spectrum_width';
  if (f === 'PRT') return 'precipitation_type';
  if (f === 'DTA') return 'storm_total_precipitation';
  return 'reflectivity';
}

const _wiseHostIsLittleEndian = (() => {
  const buf = new ArrayBuffer(2);
  new DataView(buf).setUint16(0, 0x00ff, true);
  return new Uint16Array(buf)[0] === 0x00ff;
})();

function _wiseStationFallbackCoords(stationId) {
  const sid = canonicalStationId(stationId);
  const station = STATIONS[sid] || HAWAII_STATIONS[sid] || TERMINAL_STATIONS[sid] || [];
  return {
    lat: Number(station[0]) || 0,
    lon: Number(station[1]) || 0,
  };
}

function _parseWiseScanTimeIso(datetimeText, fileName = '') {
  const raw = String(datetimeText || '').trim();
  if (raw) {
    const normalized = raw.replace(' ', 'T');
    const withZone = /(?:Z|[+-]\d{2}:\d{2})$/i.test(normalized) ? normalized : `${normalized}Z`;
    const dt = new Date(withZone);
    if (Number.isFinite(dt.getTime())) return dt.toISOString();
  }
  const ts = parseKeyTimestampMs(`WISE:X:X:X:${encodeURIComponent(fileName || '')}`);
  return Number.isFinite(ts) ? new Date(ts).toISOString() : null;
}

function _wisePayloadToCodeStream(payloadBytes, precision) {
  if (precision <= 8) {
    return new Uint8Array(payloadBytes.buffer, payloadBytes.byteOffset, payloadBytes.byteLength);
  }
  if (precision <= 16) {
    const count = Math.floor(payloadBytes.byteLength / 2);
    if (_wiseHostIsLittleEndian && (payloadBytes.byteOffset % 2) === 0) {
      return new Uint16Array(payloadBytes.buffer, payloadBytes.byteOffset, count);
    }
    const out = new Uint16Array(count);
    const dv = new DataView(payloadBytes.buffer, payloadBytes.byteOffset, payloadBytes.byteLength);
    for (let i = 0, o = 0; i < count; i += 1, o += 2) {
      out[i] = dv.getUint16(o, true);
    }
    return out;
  }
  throw new Error(`Unsupported WISE precision: ${precision}`);
}

function parseWiseContainer(bytes, stationId, family, fileName) {
  if (!(bytes instanceof Uint8Array) || bytes.byteLength < WISE_FIXED_HEADER_SIZE) {
    throw new Error('WISE payload too small');
  }
  const dv = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const magic = String.fromCharCode(
    dv.getUint8(0),
    dv.getUint8(1),
    dv.getUint8(2),
    dv.getUint8(3),
  );
  if (magic !== WISE_MAGIC) throw new Error(`Bad WISE magic: ${magic}`);

  const jsonLen = dv.getUint32(8, false);
  const payloadLen = dv.getUint32(12, false);
  const precision = dv.getUint8(16);
  const headerMin = dv.getFloat32(18, false);
  const headerMax = dv.getFloat32(22, false);
  const dimX = dv.getUint32(26, false);
  const dimY = dv.getUint32(30, false);
  const dimZ = dv.getUint32(34, false);

  const jsonStart = WISE_FIXED_HEADER_SIZE;
  const jsonEnd = jsonStart + jsonLen;
  if (jsonEnd > bytes.byteLength) throw new Error('WISE JSON block truncated');

  const meta = JSON.parse(new TextDecoder('utf-8').decode(bytes.subarray(jsonStart, jsonEnd)));
  const payloadStart = jsonEnd;
  const payloadEnd = payloadStart + payloadLen;
  if (payloadEnd > bytes.byteLength) throw new Error('WISE payload block truncated');

  const payloadBytes = bytes.subarray(payloadStart, payloadEnd);
  const location = Array.isArray(meta?.location) ? meta.location : [];
  const stationFallback = _wiseStationFallbackCoords(stationId);
  const stationLon = Number.isFinite(Number(location[0])) ? Number(location[0]) : stationFallback.lon;
  const stationLat = Number.isFinite(Number(location[1])) ? Number(location[1]) : stationFallback.lat;
  const minValue = Number.isFinite(headerMin) ? headerMin : Number(meta?.stats?.min);
  const maxValue = Number.isFinite(headerMax) ? headerMax : Number(meta?.stats?.max);

  return {
    stationId: canonicalStationId(stationId),
    family: String(family || '').trim().toUpperCase(),
    productCode: String(meta?.product || _processedWiseProductCodeForFamily(family) || '').toUpperCase(),
    fileName: String(fileName || ''),
    precision: Math.max(1, Number(precision) || 0),
    minValue,
    maxValue,
    dims: [dimX, dimY, dimZ],
    azimuthCount: Math.max(1, Number(dimX) || 0),
    gateCount: Math.max(1, Number(dimY) || 0),
    azimuthStart: Number(meta?.azimuth_start) || 0,
    gateSpacingM: Math.max(1, Number(meta?.meters_between_gates) || 250),
    firstGateCenterM: Math.max(0, Number(meta?.meters_to_center_of_first_gate) || (Number(meta?.meters_between_gates) || 250) * 0.5),
    stationLat,
    stationLon,
    elevation: Number(meta?.elevation) || 0,
    scanTime: _parseWiseScanTimeIso(meta?.datetime, fileName),
    field: _wiseFieldNameForFamily(family),
    multiTypeCount: Math.max(0, Number(meta?.multi_type?.count) || 0),
    payloadData: _wisePayloadToCodeStream(payloadBytes, precision),
  };
}

function decodeWiseRadar(meta, data) {
  const precision = Math.max(1, Number(meta?.precision) || 0);
  const threshold = (1 << (precision - 1)) - 1;
  const azimuthCount = Math.max(1, Number(meta?.azimuthCount) || 0);
  const gateCount = Math.max(1, Number(meta?.gateCount) || 0);
  const total = azimuthCount * gateCount;
  const out = new Uint16Array(total);

  if (!total || !data?.length) {
    return { grid: out, azimuthCount, gateCount };
  }

  let startIdx = gateCount * Math.round((azimuthCount / 360) * (Number(meta?.azimuthStart) || 0));
  startIdx = ((startIdx % total) + total) % total;

  let h = startIdx;
  let i = 0;
  while (i < data.length && h < total) {
    const code = data[i++];
    if (code > threshold) {
      h += code - threshold;
      continue;
    }
    if (code > 0) out[h] = code;
    h += 1;
  }

  h %= total;
  while (i < data.length) {
    const code = data[i++];
    if (code > threshold) {
      h += code - threshold;
      continue;
    }
    if (code > 0) out[h] = code;
    h += 1;
    if (h >= total) h %= total;
  }

  return { grid: out, azimuthCount, gateCount };
}

function decodeWiseRadarMultitype(meta, data) {
  const precision = Math.max(1, Number(meta?.precision) || 0);
  const threshold = (1 << (precision - 1)) - 1;
  const typeCount = Math.max(0, Number(meta?.multiTypeCount) || 0);
  const azimuthCount = Math.max(1, Number(meta?.azimuthCount) || 0);
  const gateCount = Math.max(1, Number(meta?.gateCount) || 0);
  const total = azimuthCount * gateCount;
  const out = new Uint16Array(total);
  const typeGrid = new Uint8Array(total);

  if (!total || !data?.length) {
    return { grid: out, typeGrid, azimuthCount, gateCount };
  }

  let startIdx = gateCount * Math.round((azimuthCount / 360) * (Number(meta?.azimuthStart) || 0));
  startIdx = ((startIdx % total) + total) % total;

  let currentType = 1;
  let h = startIdx;
  let i = 0;
  while (i < data.length && h < total) {
    const code = data[i++];
    if (code > (threshold + typeCount)) {
      h += code - threshold - typeCount;
      continue;
    }
    if (code > threshold) {
      currentType = Math.max(1, code - threshold);
      continue;
    }
    if (code > 0) {
      out[h] = (code << 1) - 1;
      typeGrid[h] = currentType;
    }
    h += 1;
  }

  h %= total;
  while (i < data.length) {
    const code = data[i++];
    if (code > (threshold + typeCount)) {
      h += code - threshold - typeCount;
      continue;
    }
    if (code > threshold) {
      currentType = Math.max(1, code - threshold);
      continue;
    }
    if (code > 0) {
      out[h] = (code << 1) - 1;
      typeGrid[h] = currentType;
    }
    h += 1;
    if (h >= total) h %= total;
  }

  return { grid: out, typeGrid, azimuthCount, gateCount };
}

function _toMercatorPoint(latDeg, lonDeg) {
  const latClip = Math.max(-MAX_MERCATOR_LAT, Math.min(MAX_MERCATOR_LAT, latDeg));
  const latRad = latClip * Math.PI / 180.0;
  return {
    x: (lonDeg + 180.0) / 360.0,
    y: (1.0 - (Math.log(Math.tan((Math.PI * 0.25) + (latRad * 0.5))) / Math.PI)) * 0.5,
  };
}

function _wiseGeometryCacheKey(container) {
  return [
    canonicalStationId(container.stationId),
    Number(container.stationLat).toFixed(4),
    Number(container.stationLon).toFixed(4),
    Number(container.azimuthCount) || 0,
    Number(container.gateCount) || 0,
    Number(container.gateSpacingM || 0).toFixed(2),
    Number(container.firstGateCenterM || 0).toFixed(2),
  ].join('|');
}

function _getWiseGeometry(container) {
  const cacheKey = _wiseGeometryCacheKey(container);
  const cached = _wiseGeometryCache.get(cacheKey);
  if (cached) {
    _wiseGeometryCache.delete(cacheKey);
    _wiseGeometryCache.set(cacheKey, cached);
    return cached;
  }

  const azimuthCount = Math.max(1, Number(container.azimuthCount) || 0);
  const gateCount = Math.max(1, Number(container.gateCount) || 0);
  const lat1 = Number(container.stationLat);
  const lon1 = Number(container.stationLon);
  const lat1Rad = lat1 * Math.PI / 180.0;
  const lon1Rad = lon1 * Math.PI / 180.0;
  const sinLat1 = Math.sin(lat1Rad);
  const cosLat1 = Math.cos(lat1Rad);

  const gateSpacingM = Math.max(1, Number(container.gateSpacingM) || 250);
  const firstCenterM = Math.max(0, Number(container.firstGateCenterM) || (gateSpacingM * 0.5));
  const firstEdgeM = Math.max(0, firstCenterM - (gateSpacingM * 0.5));
  const rangeEdgeCount = gateCount + 1;
  const sinD = new Float64Array(rangeEdgeCount);
  const cosD = new Float64Array(rangeEdgeCount);
  for (let r = 0; r < rangeEdgeCount; r += 1) {
    const dist = firstEdgeM + (r * gateSpacingM);
    const d = dist / EARTH_RADIUS_M;
    sinD[r] = Math.sin(d);
    cosD[r] = Math.cos(d);
  }

  const edgeAzCount = azimuthCount + 1;
  const azimuthStepDeg = 360.0 / azimuthCount;
  const halfStepDeg = azimuthStepDeg * 0.5;
  const edgeXs = new Float32Array(edgeAzCount * rangeEdgeCount);
  const edgeYs = new Float32Array(edgeAzCount * rangeEdgeCount);
  for (let a = 0; a < edgeAzCount; a += 1) {
    const azDeg = (a * azimuthStepDeg) - halfStepDeg;
    const bearingRad = azDeg * Math.PI / 180.0;
    const sinBearing = Math.sin(bearingRad);
    const cosBearing = Math.cos(bearingRad);
    const rowBase = a * rangeEdgeCount;
    for (let r = 0; r < rangeEdgeCount; r += 1) {
      const lat2 = Math.asin((sinLat1 * cosD[r]) + (cosLat1 * sinD[r] * cosBearing));
      const lon2 = lon1Rad + Math.atan2(
        sinBearing * sinD[r] * cosLat1,
        cosD[r] - (sinLat1 * Math.sin(lat2)),
      );
      const latDeg = lat2 * 180.0 / Math.PI;
      const lonDeg = (((lon2 * 180.0 / Math.PI) + 180.0) % 360.0) - 180.0;
      const merc = _toMercatorPoint(latDeg, lonDeg);
      edgeXs[rowBase + r] = merc.x;
      edgeYs[rowBase + r] = merc.y;
    }
  }

  const geometry = {
    rangeEdgeCount,
    edgeXs,
    edgeYs,
  };
  _wiseGeometryCache.set(cacheKey, geometry);
  while (_wiseGeometryCache.size > WISE_GEOMETRY_CACHE_MAX) {
    const oldest = _wiseGeometryCache.keys().next().value;
    if (oldest == null) break;
    _wiseGeometryCache.delete(oldest);
  }
  return geometry;
}

// ---------------------------------------------------------------------------
// Off-main-thread frame builder via Web Worker.
// All CPU-intensive work (trig geometry, RLE decode, vertex loop) runs in
// radar-worker.js so the main thread stays responsive during data load.
// ---------------------------------------------------------------------------
let _wiseWorker = null;
const _wiseWorkerPending = new Map(); // id → {resolve, reject}
let _wiseWorkerIdSeq = 0;

function _ensureWiseWorker() {
  if (_wiseWorker) return _wiseWorker;
  _wiseWorker = new Worker('./radar-worker.js');
  _wiseWorker.onmessage = (ev) => {
    const { id, frame, error } = ev.data;
    const cb = _wiseWorkerPending.get(id);
    if (!cb) return;
    _wiseWorkerPending.delete(id);
    if (error) cb.reject(new Error(error));
    else cb.resolve(frame);
  };
  _wiseWorker.onerror = (ev) => {
    const msg = ev?.message || 'radar worker error';
    for (const cb of _wiseWorkerPending.values()) cb.reject(new Error(msg));
    _wiseWorkerPending.clear();
    _wiseWorker = null; // will be recreated on next call
  };
  return _wiseWorker;
}

function _buildWiseFrame(container) {
  const isPrtMultiType = String(container?.family || '').trim().toUpperCase() === 'PRT'
    && Number(container?.multiTypeCount) > 0;
  const palette = isPrtMultiType
    ? _prepareWisePrtPalette()
    : _prepareInlinePalette(ctGetEffectivePalette(container.family));

  // Copy payloadData so the prefetch-cache buffer is not neutered on transfer.
  const src = container.payloadData;
  const payloadCopy = src instanceof Uint16Array
    ? new Uint16Array(src)
    : new Uint8Array(src);
  const containerMsg = {
    ...container,
    payloadData: null,
    maxRenderGates: getAdaptiveMaxRenderGates(),
    dataSmoothingStrength: radarDataSmoothing === true
      ? Math.max(0, Math.min(1, Number(radarDataSmoothingStrength) || 0))
      : 0,
  };

  const id = ++_wiseWorkerIdSeq;
  return new Promise((resolve, reject) => {
    _wiseWorkerPending.set(id, { resolve, reject });
    _ensureWiseWorker().postMessage(
      { id, container: containerMsg, payloadData: payloadCopy, palette },
      [payloadCopy.buffer],  // transfer the copy — zero-copy into worker
    );
  });
}

function getAdaptiveMaxRenderGates() {
  const baseCap = Math.max(100000, Number(WISE_MAX_RENDER_GATES) || 750000);
  let zoom = NaN;
  try { zoom = Number(map?.getZoom?.()); } catch (_) {}
  if (!Number.isFinite(zoom)) return baseCap;
  if (zoom < 5.5) return Math.min(baseCap, 450000);
  if (zoom < 7.5) return Math.min(baseCap, 650000);
  return baseCap;
}

async function _decodeWiseKey(key, opts = {}) {
  const decodeStart = performance.now();
  const parts = String(key || '').split(':');
  const stationId = canonicalStationId(parts[1] || '');
  const family = String(parts[2] || '').trim().toUpperCase();
  const tilt = normalizeTilt(parts[3] || '0.5');
  const fileName = decodeURIComponent(parts.slice(4).join(':') || '');
  if (!stationId || !family || !fileName) {
    throw new Error(`Invalid WISE key: ${key}`);
  }

  const url = _processedWiseFileUrl(stationId, family, tilt, fileName);
  if (_isWiseNotFoundCoolingDown(key) || _isWiseNotFoundCoolingDown(url)) {
    const err = new Error('HTTP 404');
    err.status = 404;
    err.url = url;
    err.isNotFound = true;
    throw err;
  }
  let fetchMs = 0;
  let parseMs = 0;
  let workerMs = 0;
  let cacheHit = false;
  let bytes = _processedWisePrefetchBytes.get(key);
  if (bytes) {
    cacheHit = true;
    _processedWisePrefetchBytes.delete(key);
  } else if (_processedWiseRawBytesCache.has(key)) {
    cacheHit = true;
    bytes = new Uint8Array(_processedWiseRawBytesCache.get(key));
  } else {
    const preferDirect = opts?.allowDirect === true;
    let fetchP = _pendingWiseFetches.get(url);
    if (!fetchP) {
      fetchP = _fetchBytesViaTauri(url, {
        timeoutMs: 15000,
        preferDirect,
      }).finally(() => _pendingWiseFetches.delete(url));
      _pendingWiseFetches.set(url, fetchP);
    }
    try {
      const fetchStart = performance.now();
      bytes = await fetchP;
      fetchMs = performance.now() - fetchStart;
    } catch (err) {
      if (err?.status === 404 || err?.isNotFound) {
        _markWiseNotFound(key);
        _markWiseNotFound(url);
      }
      throw err;
    }
  }
  _clearWiseNotFound(key);
  _clearWiseNotFound(url);
  if (bytes) {
    _storeProcessedWiseRawBytes(key, bytes);
  }
  const parseStart = performance.now();
  const container = parseWiseContainer(bytes, stationId, family, fileName);
  parseMs = performance.now() - parseStart;
  const workerStart = performance.now();
  const frame = await _buildWiseFrame(container);
  workerMs = performance.now() - workerStart;
  if (RADAR_PERF_DEBUG) {
    console.log('[RadarPerf]', {
      station: stationId,
      product: family,
      tilt,
      key,
      gates: frame?.source_gate_count || frame?.gate_count || null,
      vertices: frame?.vertex_count || 0,
      smoothing: {
        enabled: radarDataSmoothing === true,
        strength: radarDataSmoothing === true ? Math.max(0, Math.min(1, Number(radarDataSmoothingStrength) || 0)) : 0,
      },
      cacheHit,
      fetchMs: Math.round(fetchMs),
      parseMs: Math.round(parseMs),
      decodeMs: Math.round(performance.now() - decodeStart),
      buildMs: Math.round(workerMs),
      uploadMs: null,
      frameBytes: estimateDecodedFrameBytes(frame),
    });
  }
  _schedulePredictiveWisePrefetch(stationId, family, tilt, fileName);
  if (!opts?.priority) {
    await new Promise(resolve => requestAnimationFrame(resolve));
  }
  return frame;
}

async function backendDecode(key, opts = {}) {
  if (String(key || '').startsWith('WISE:')) {
    return _decodeWiseKey(key, opts);
  }
  throw new Error('Legacy Py-ART decode was removed. This build supports processed WeatherWise radar only.');
}

// -- PTDS derived product ---------------------------------------------------

function _colorForPtdsValue(value, stops, buf, offset) {
  if (!stops?.length) { buf[offset] = buf[offset+1] = buf[offset+2] = buf[offset+3] = 0; return; }
  if (value <= stops[0][0]) {
    buf[offset] = stops[0][1]; buf[offset+1] = stops[0][2]; buf[offset+2] = stops[0][3]; buf[offset+3] = stops[0][4];
    return;
  }
  const last = stops[stops.length - 1];
  if (value >= last[0]) {
    buf[offset] = last[1]; buf[offset+1] = last[2]; buf[offset+2] = last[3]; buf[offset+3] = last[4];
    return;
  }
  for (let i = 1; i < stops.length; i++) {
    if (value <= stops[i][0]) {
      const t = (value - stops[i-1][0]) / (stops[i][0] - stops[i-1][0]);
      const a = stops[i-1], b = stops[i];
      buf[offset]   = Math.round(a[1] + t * (b[1] - a[1]));
      buf[offset+1] = Math.round(a[2] + t * (b[2] - a[2]));
      buf[offset+2] = Math.round(a[3] + t * (b[3] - a[3]));
      buf[offset+3] = Math.round(a[4] + t * (b[4] - a[4]));
      return;
    }
  }
}

function _computePtdsFrame(refFrame, ccFrame, srvFrame) {
  const vc = Number(refFrame?.vertex_count || 0);
  if (!vc || !refFrame._bufXy || !refFrame._bufVals) return null;
  const refVals = refFrame._bufVals;
  const ccVals  = ccFrame?._bufVals;
  const srvVals = srvFrame?._bufVals;
  const palette = ctGetEffectivePalette('PTDS');
  const stops   = palette?.stops || [];
  const ptdsVals   = new Float32Array(vc);
  const ptdsColors = new Uint8Array(vc * 4);
  for (let i = 0; i < vc; i++) {
    const ref = refVals[i];
    const cc  = (ccVals && i < ccVals.length)  ? ccVals[i]  : 9999;
    const srv = (srvVals && i < srvVals.length) ? srvVals[i] : 0;
    let score = 0;
    if (ref >= 35 && cc <= 0.9 && cc > -9990) {
      score += Math.min(50, Math.max(0, (0.9 - cc) * 100 * 2));
      score += Math.min(30, Math.max(0, ref - 35));
      if (Math.abs(srv) >= 35) score += 20;
    }
    score = Math.max(0, Math.min(100, score));
    ptdsVals[i] = score;
    _colorForPtdsValue(score, stops, ptdsColors, i * 4);
  }
  return {
    vertex_count: vc,
    _bufXy:    refFrame._bufXy,
    _bufColor: ptdsColors,
    _bufVals:  ptdsVals,
    product: 'PTDS', product_code: 'PTDS', units: '%',
    station_id: refFrame.station_id,
    elevation:  refFrame.elevation,
    scan_time:  refFrame.scan_time,
    min_val: 0, max_val: 100,
  };
}

async function _loadPtdsFrame(stationId, tilt, seq) {
  try {
    const [refMeta, ccMeta] = await Promise.all([
      findLatestKey(stationId, { family: 'REF', tilt }),
      findLatestKey(stationId, { family: 'CC',  tilt }),
    ]);
    if (seq !== _l3LoadSeq || stationId !== activeStation || activeFamily !== 'PTDS') return;
    if (!refMeta?.key || !ccMeta?.key) {
      setFrameLabel('PTDS unavailable — REF or CC missing', 'error');
      return;
    }
    let refFrame = frameCache.get(refMeta.key);
    if (!refFrame) { refFrame = await backendDecode(refMeta.key, { priority: true }); if (refFrame) frameCache.set(refMeta.key, refFrame); }
    let ccFrame  = frameCache.get(ccMeta.key);
    if (!ccFrame)  { ccFrame  = await backendDecode(ccMeta.key,  { priority: true }); if (ccFrame)  frameCache.set(ccMeta.key,  ccFrame);  }
    if (seq !== _l3LoadSeq || stationId !== activeStation || activeFamily !== 'PTDS') return;
    if (!refFrame || !ccFrame) { setFrameLabel('PTDS unavailable — decode failed', 'error'); return; }

    let srvFrame = null;
    try {
      const srvMeta = await findLatestKey(stationId, { family: 'SRV', tilt });
      if (srvMeta?.key) {
        srvFrame = frameCache.get(srvMeta.key);
        if (!srvFrame) { srvFrame = await backendDecode(srvMeta.key, { priority: true }); if (srvFrame) frameCache.set(srvMeta.key, srvFrame); }
      }
    } catch (_) {}
    if (seq !== _l3LoadSeq || stationId !== activeStation || activeFamily !== 'PTDS') return;

    const ptdsFrame = _computePtdsFrame(refFrame, ccFrame, srvFrame);
    if (!ptdsFrame) { setFrameLabel('PTDS unavailable — no gate data', 'error'); return; }

    const syntheticKey = `PTDS:${stationId}:${tilt}`;
    frameCache.set(syntheticKey, ptdsFrame);
    applyRadarFrame(ptdsFrame, syntheticKey, () => {
      document.getElementById('info-code').textContent = 'PTDS';
      const t = refFrame.scan_time ? _fmtLocalTime(_parseFrameScanTimeMs(refFrame.scan_time, refMeta.key)) : '--:--:-- --';
      setFrameLabel(`${t}  LIVE`, 'ok');
    }, { immediateUpload: true });
    applyFilter();
  } catch (err) {
    if (seq === _l3LoadSeq && stationId === activeStation && activeFamily === 'PTDS') {
      setFrameLabel('PTDS unavailable', 'error');
      console.warn('[PTDS] load failed:', err);
    }
  }
}

function buildShader(gl, type, source) {
  const shader = gl.createShader(type);
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    const err = gl.getShaderInfoLog(shader) || 'shader compile error';
    gl.deleteShader(shader);
    throw new Error(err);
  }
  return shader;
}

function buildProgram(gl, vertexSource, fragmentSource) {
  const vs = buildShader(gl, gl.VERTEX_SHADER, vertexSource);
  const fs = buildShader(gl, gl.FRAGMENT_SHADER, fragmentSource);
  const program = gl.createProgram();
  gl.attachShader(program, vs);
  gl.attachShader(program, fs);
  gl.linkProgram(program);
  gl.deleteShader(vs);
  gl.deleteShader(fs);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    const err = gl.getProgramInfoLog(program) || 'program link error';
    gl.deleteProgram(program);
    throw new Error(err);
  }
  return program;
}

// Shared WebGL program for all RadarGateLayer instances.
// Compiling the identical GLSL shaders once and reusing the program object
// across every pool layer avoids per-instance GPU driver shader-compilation
// stalls (which can take 500 ms–2 s on Windows ANGLE/D3D11).
let _rgProg = null;
let _rgProgGl = null;   // WebGL context the program was compiled for
let _rgProgAttribs = null;

// Registry of live RadarGateLayer instances keyed by layer id.
export const _radarGateLayerInstances = new Map();

// Maximum vertices to upload per render frame for the chunked GPU upload path.
// Keeps each bufferSubData call well within the 16 ms frame budget even on
// slow integrated graphics (~320 KB per chunk across all three buffers).
const _UPLOAD_CHUNK_VERTS = 90_000;
const LARGE_FRAME_IMMEDIATE_VERTEX_LIMIT = 250_000;

class RadarGateLayer {
  // u_sweep_mode: 0=normal, 1=reveal new scan (discard az>sweep_deg), 2=erase old scan (discard az<=sweep_deg)
  constructor(id) {
    this.id = id;
    this.type = 'custom';
    this.renderingMode = '2d';
    this._sweepMode = 0;

    this.map = null;
    this.gl = null;
    this.program = null;
    this.vertexCount = 0;
    this.posBuffer = null;
    this.colorBuffer = null;
    this.valBuffer = null;
    this._posByteLen = 0;
    this._colorByteLen = 0;
    this._valByteLen = 0;
    this._minValue = -9999.0;
    this._sweepDeg = 0;      // current sweep angle (0–360)
    this._stationX = 0;      // station Mercator x
    this._stationY = 0;      // station Mercator y
    this._visible = false;   // controlled by setVisible(); hidden pool layers still upload to GPU
    this._loadedData = null; // reference to the frame object currently in GPU buffers
    this._onSwap = null;     // fired once when the next back→front swap completes

    // Back buffers: new frame data uploads here while front buffers keep drawing
    // the current frame uninterrupted.  Swapped atomically when upload completes.
    this._posBufferBack   = null;
    this._colorBufferBack = null;
    this._valBufferBack   = null;
    this._posByteLenBack   = 0;
    this._colorByteLenBack = 0;
    this._valByteLenBack   = 0;
  }

  onAdd(map, gl) {
    this.map = map;
    this.gl = gl;
    _radarGateLayerInstances.set(this.id, this);

    // Compile the shader program only once and share it across all pool layer
    // instances.  Recompiling identical GLSL on every RadarGateLayer creation
    // triggers a full ANGLE GLSL?HLSL?D3DCompile round-trip each time, which
    // can stall the render thread for 500 ms–2 s on Windows.
    if (!_rgProg || _rgProgGl !== gl) {
      const vertex = `
        precision highp float;
        uniform mat4 u_matrix;
        attribute highp vec2 a_pos;
        attribute vec4 a_rgba;
        attribute float a_value;
        varying vec4 v_rgba;
        varying float v_value;
        varying highp vec2 v_pos;
        void main() {
          gl_Position = u_matrix * vec4(a_pos, 0.0, 1.0);
          v_rgba = a_rgba;
          v_value = a_value;
          v_pos = a_pos;
        }
      `;
      // Unified fragment shader. u_sweep_mode:
      //   0 = normal render (no mask)
      //   1 = reveal new scan — discard pixels where az > u_sweep_deg (swept area shows)
      //   2 = erase old scan  — discard pixels where az <= u_sweep_deg (swept area hidden)
      // Uses highp for azimuth math to avoid precision loss near the station.
      const fragment = `
        precision highp float;
        uniform float u_min_value;
        uniform float u_sweep_mode;
        uniform highp float u_sweep_deg;
        uniform highp vec2  u_station;
        varying vec4  v_rgba;
        varying float v_value;
        varying highp vec2  v_pos;
        void main() {
          if (u_min_value > -9990.0 && v_value < u_min_value) discard;
          if (u_sweep_mode > 0.5) {
            highp float dx = v_pos.x - u_station.x;
            if (dx > 0.5) dx -= 1.0;
            if (dx < -0.5) dx += 1.0;
            highp float dy = u_station.y - v_pos.y;
            highp float az = degrees(atan(dx, dy));
            if (az < 0.0) az += 360.0;
            if (u_sweep_mode < 1.5) {
              if (az > u_sweep_deg) discard;
            } else {
              if (az <= u_sweep_deg) discard;
            }
          }
          gl_FragColor = v_rgba;
        }
      `;
      _rgProg = buildProgram(gl, vertex, fragment);
      _rgProgGl = gl;
      _rgProgAttribs = {
        aPos:       gl.getAttribLocation(_rgProg, 'a_pos'),
        aRgba:      gl.getAttribLocation(_rgProg, 'a_rgba'),
        aValue:     gl.getAttribLocation(_rgProg, 'a_value'),
        uMatrix:    gl.getUniformLocation(_rgProg, 'u_matrix'),
        uMinValue:  gl.getUniformLocation(_rgProg, 'u_min_value'),
        uSweepMode: gl.getUniformLocation(_rgProg, 'u_sweep_mode'),
        uSweepDeg:  gl.getUniformLocation(_rgProg, 'u_sweep_deg'),
        uStation:   gl.getUniformLocation(_rgProg, 'u_station'),
      };
    }

    this.program    = _rgProg;
    this.aPos       = _rgProgAttribs.aPos;
    this.aRgba      = _rgProgAttribs.aRgba;
    this.aValue     = _rgProgAttribs.aValue;
    this.uMatrix    = _rgProgAttribs.uMatrix;
    this.uMinValue  = _rgProgAttribs.uMinValue;
    this.uSweepMode = _rgProgAttribs.uSweepMode;
    this.uSweepDeg  = _rgProgAttribs.uSweepDeg;
    this.uStation   = _rgProgAttribs.uStation;

    this.posBuffer   = gl.createBuffer();
    this.colorBuffer = gl.createBuffer();
    this.valBuffer   = gl.createBuffer();
    this._posBufferBack   = gl.createBuffer();
    this._colorBufferBack = gl.createBuffer();
    this._valBufferBack   = gl.createBuffer();
  }

  onRemove(_map, gl) {
    _radarGateLayerInstances.delete(this.id);
    if (this.posBuffer)        gl.deleteBuffer(this.posBuffer);
    if (this.colorBuffer)      gl.deleteBuffer(this.colorBuffer);
    if (this.valBuffer)        gl.deleteBuffer(this.valBuffer);
    if (this._posBufferBack)   gl.deleteBuffer(this._posBufferBack);
    if (this._colorBufferBack) gl.deleteBuffer(this._colorBufferBack);
    if (this._valBufferBack)   gl.deleteBuffer(this._valBufferBack);
    // Do NOT delete this.program — it is the shared module-level _rgProg
    // and must outlive this individual layer instance.
    this.vertexCount = 0;
  }

  setFrame(frame, onReady = null, opts = {}) {
    // If this exact frame object is already in GPU, fire callback immediately.
    if (frame && this._loadedData === frame) {
      if (this._visible) this.map?.triggerRepaint();
      if (onReady) onReady();
      return;
    }
    this._loadedData = frame || null;
    this._onSwap = null; // cancel any pending swap callback for the previous upload

    const vertexCount = Number(frame?.vertex_count || 0);
    if (!vertexCount) {
      this._pending = null;
      this.vertexCount = 0;
      this.map?.triggerRepaint();
      if (onReady) onReady();
      return;
    }

    const xy     = frame._bufXy;
    const colors = frame._bufColor;
    const v      = frame._bufVals;
    const valData = (v && v.length === vertexCount) ? v : new Float32Array(vertexCount).fill(9999.0);

    if (xy.length !== vertexCount * 2) throw new Error('Backend triangle position payload mismatch');
    if (colors.length !== vertexCount * 4) throw new Error('Backend triangle color payload mismatch');

    // When no frame is currently visible, upload immediately in a single render
    // pass so the scan appears without a multi-frame build-up delay.
    // When replacing a visible frame, use the chunked path so the old scan
    // stays smooth until the new one is fully ready.
    const explicitImmediate = opts?.immediateUpload === true;
    const wantsImmediate = explicitImmediate || this.vertexCount === 0;
    const _immediate = explicitImmediate || (wantsImmediate && vertexCount <= LARGE_FRAME_IMMEDIATE_VERTEX_LIMIT);
    this._pending = { vertexCount, xy, colors, valData, _offset: 0, _immediate, _uploadStartMs: 0 };
    this._onSwap = onReady || null;
    this.map?.triggerRepaint();
  }

  clearFrame() {
    this._pending = null;
    this._loadedData = null;
    this._onSwap = null;
    this.vertexCount = 0;
    this.map?.triggerRepaint();
  }

  // Show or hide this layer. Hidden layers still upload pending GPU data so
  // they're instantly ready when made visible again.
  setVisible(v) {
    if (this._visible === v) return;
    this._visible = v;
    this.map?.triggerRepaint();
  }

  setSweepAngle(deg) {
    this._sweepDeg = deg;
    // no triggerRepaint here — the RAF loop already calls it
  }

  setStationPos(x, y) {
    this._stationX = x;
    this._stationY = y;
  }

  setSweepMode(mode) {
    if (this._sweepMode === mode) return;
    this._sweepMode = mode;
    this.map?.triggerRepaint();
  }

  setMinValue(v) {
    const next = (v == null) ? -9999.0 : v;
    if (this._minValue === next) return;
    this._minValue = next;
    this.map?.triggerRepaint();
  }

  isFrameReady(frame) {
    if (!frame) return false;
    return (this._loadedData === frame) && !this._pending;
  }

  // Atomically promote back buffers to front.  Called once per frame when the
  // last upload chunk completes — the old scan is visible right up to this point.
  _swapBuffers(vertexCount) {
    [this.posBuffer,   this._posBufferBack]   = [this._posBufferBack,   this.posBuffer];
    [this.colorBuffer, this._colorBufferBack] = [this._colorBufferBack, this.colorBuffer];
    [this.valBuffer,   this._valBufferBack]   = [this._valBufferBack,   this.valBuffer];
    [this._posByteLen,   this._posByteLenBack]   = [this._posByteLenBack,   this._posByteLen];
    [this._colorByteLen, this._colorByteLenBack] = [this._colorByteLenBack, this._colorByteLen];
    [this._valByteLen,   this._valByteLenBack]   = [this._valByteLenBack,   this._valByteLen];
    this.vertexCount = vertexCount;
    const cb = this._onSwap;
    this._onSwap = null;
    this.map?.triggerRepaint();
    if (cb) cb();
  }

  render(gl, matrix) {
    // Upload pending frame data to GPU in fixed-size chunks spread across
    // multiple render frames.  This prevents the monolithic gl.bufferData()
    // call from stalling the render thread for 2–3 s when a large frame
    // (~40 MB across three buffers) arrives for a new product combo.
    //
    // New data is uploaded to the BACK buffers while the FRONT buffers keep
    // serving the previous frame uninterrupted — vertexCount is never zeroed
    // during an upload.  When the last chunk lands, _swapBuffers() promotes
    // back → front atomically so the new scan appears in one render tick.
    if (this._pending) {
      const { vertexCount, xy, colors, valData, _immediate } = this._pending;
      if (!this._pending._uploadStartMs) this._pending._uploadStartMs = performance.now();
      const offset = this._pending._offset;
      const end    = Math.min(offset + _UPLOAD_CHUNK_VERTS, vertexCount);

      if (_immediate) {
        // Full immediate upload to back buffer, then swap.
        gl.bindBuffer(gl.ARRAY_BUFFER, this._posBufferBack);
        gl.bufferData(gl.ARRAY_BUFFER, xy, gl.DYNAMIC_DRAW);
        this._posByteLenBack = xy.byteLength;
        gl.bindBuffer(gl.ARRAY_BUFFER, this._colorBufferBack);
        gl.bufferData(gl.ARRAY_BUFFER, colors, gl.DYNAMIC_DRAW);
        this._colorByteLenBack = colors.byteLength;
        gl.bindBuffer(gl.ARRAY_BUFFER, this._valBufferBack);
        gl.bufferData(gl.ARRAY_BUFFER, valData, gl.DYNAMIC_DRAW);
        this._valByteLenBack = valData.byteLength;
        const uploadMs = performance.now() - this._pending._uploadStartMs;
        this._pending = null;
        this._swapBuffers(vertexCount);
        if (RADAR_PERF_DEBUG) {
          console.log('[RadarPerf]', {
            layer: this.id,
            vertices: vertexCount,
            uploadMs: Math.round(uploadMs),
            uploadMode: 'immediate',
            frameBytes: xy.byteLength + colors.byteLength + valData.byteLength,
          });
        }
      } else {
        if (offset === 0) {
          // First chunk: size the back buffers.  Front buffers are untouched
          // so the current scan keeps drawing without interruption.
          if (this._posByteLenBack !== xy.byteLength) {
            gl.bindBuffer(gl.ARRAY_BUFFER, this._posBufferBack);
            gl.bufferData(gl.ARRAY_BUFFER, xy.byteLength, gl.DYNAMIC_DRAW);
            this._posByteLenBack = xy.byteLength;
          }
          if (this._colorByteLenBack !== colors.byteLength) {
            gl.bindBuffer(gl.ARRAY_BUFFER, this._colorBufferBack);
            gl.bufferData(gl.ARRAY_BUFFER, colors.byteLength, gl.DYNAMIC_DRAW);
            this._colorByteLenBack = colors.byteLength;
          }
          if (this._valByteLenBack !== valData.byteLength) {
            gl.bindBuffer(gl.ARRAY_BUFFER, this._valBufferBack);
            gl.bufferData(gl.ARRAY_BUFFER, valData.byteLength, gl.DYNAMIC_DRAW);
            this._valByteLenBack = valData.byteLength;
          }
        }

        // Transfer this chunk to back buffers.  Byte offsets:
        //   posBuffer   — 2 float32 per vertex → 8 bytes/vertex
        //   colorBuffer — 4 uint8  per vertex → 4 bytes/vertex
        //   valBuffer   — 1 float32 per vertex → 4 bytes/vertex
        gl.bindBuffer(gl.ARRAY_BUFFER, this._posBufferBack);
        gl.bufferSubData(gl.ARRAY_BUFFER, offset * 8, xy.subarray(offset * 2, end * 2));
        gl.bindBuffer(gl.ARRAY_BUFFER, this._colorBufferBack);
        gl.bufferSubData(gl.ARRAY_BUFFER, offset * 4, colors.subarray(offset * 4, end * 4));
        gl.bindBuffer(gl.ARRAY_BUFFER, this._valBufferBack);
        gl.bufferSubData(gl.ARRAY_BUFFER, offset * 4, valData.subarray(offset, end));

        if (end < vertexCount) {
          this._pending._offset = end;
          this.map?.triggerRepaint(); // schedule next chunk
        } else {
          // Upload complete — swap back → front.  Old scan displayed right up to this tick.
          const uploadMs = performance.now() - this._pending._uploadStartMs;
          this._pending = null;
          this._swapBuffers(vertexCount);
          if (RADAR_PERF_DEBUG) {
            console.log('[RadarPerf]', {
              layer: this.id,
              vertices: vertexCount,
              uploadMs: Math.round(uploadMs),
              uploadMode: 'chunked',
              frameBytes: xy.byteLength + colors.byteLength + valData.byteLength,
            });
          }
        }
      }
    }

    // Skip draw if this combo layer is currently hidden
    if (!this._visible) return;
    if (!this.program || this.vertexCount <= 0) return;

    gl.useProgram(this.program);
    gl.uniformMatrix4fv(this.uMatrix, false, matrix);
    gl.uniform1f(this.uMinValue, this._minValue);
    gl.uniform1f(this.uSweepMode, this._sweepMode);
    gl.uniform1f(this.uSweepDeg, this._sweepDeg);
    gl.uniform2f(this.uStation, this._stationX, this._stationY);

    gl.bindBuffer(gl.ARRAY_BUFFER, this.posBuffer);
    gl.enableVertexAttribArray(this.aPos);
    gl.vertexAttribPointer(this.aPos, 2, gl.FLOAT, false, 0, 0);

    gl.bindBuffer(gl.ARRAY_BUFFER, this.colorBuffer);
    gl.enableVertexAttribArray(this.aRgba);
    gl.vertexAttribPointer(this.aRgba, 4, gl.UNSIGNED_BYTE, true, 0, 0);

    gl.bindBuffer(gl.ARRAY_BUFFER, this.valBuffer);
    gl.enableVertexAttribArray(this.aValue);
    gl.vertexAttribPointer(this.aValue, 1, gl.FLOAT, false, 0, 0);

    gl.enable(gl.BLEND);
    gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);
    gl.disable(gl.DEPTH_TEST);
    gl.drawArrays(gl.TRIANGLES, 0, this.vertexCount);
  }
}

// -- Sweep Line Layer (white rotating indicator) -------------------------------
// Reads shared sweep state — angle is driven by the sweepTick() RAF loop.
class SweepLayer {
  constructor(id, options = {}) {
    this.id = id;
    this.type = 'custom';
    this.renderingMode = '2d';
    this._getSweepState = typeof options.getSweepState === 'function'
      ? options.getSweepState
      : () => ({ active: false, waiting: false, angleDeg: 0 });
    this.map = null;
    this.gl = null;
    this.program = null;
    this.posBuffer = null;
    this.alphaBuffer = null;
    this.stationX = 0;
    this.stationY = 0;
    this.meterUnit = 1;
    this._hasStation = false;
    this._trailDeg = 28;
    this._trailSegs = 20;
    this._rangeMeters = 260000;
    this._lineSegs = 3;
    this._posData = new Float32Array((this._lineSegs + 2) * 2);
    this._alphaData = new Float32Array(this._lineSegs + 2);
  }

  onAdd(map, gl) {
    this.map = map;
    this.gl = gl;
    const vert = `
      precision mediump float;
      uniform mat4 u_matrix;
      attribute vec2 a_pos;
      attribute float a_alpha;
      varying float v_alpha;
      void main() {
        gl_Position = u_matrix * vec4(a_pos, 0.0, 1.0);
        v_alpha = a_alpha;
      }
    `;
    const frag = `
      precision mediump float;
      varying float v_alpha;
      void main() {
        gl_FragColor = vec4(1.0, 1.0, 1.0, v_alpha);
      }
    `;
    this.program  = buildProgram(gl, vert, frag);
    this.aPos     = gl.getAttribLocation(this.program, 'a_pos');
    this.aAlpha   = gl.getAttribLocation(this.program, 'a_alpha');
    this.uMatrix  = gl.getUniformLocation(this.program, 'u_matrix');
    this.posBuffer   = gl.createBuffer();
    this.alphaBuffer = gl.createBuffer();
  }

  onRemove(_map, gl) {
    if (this.posBuffer)   gl.deleteBuffer(this.posBuffer);
    if (this.alphaBuffer) gl.deleteBuffer(this.alphaBuffer);
    if (this.program)     gl.deleteProgram(this.program);
  }

  setStation(lat, lon) {
    const merc = mapboxgl.MercatorCoordinate.fromLngLat([lon, lat]);
    this.stationX  = merc.x;
    this.stationY  = merc.y;
    this.meterUnit = merc.meterInMercatorCoordinateUnits();
    this._hasStation = true;
  }

  render(gl, matrix) {
    const _state = this._getSweepState() || {};
    if (!_state.active || _state.waiting || !this._hasStation || !this.program) return;

    const cx    = this.stationX;
    const cy    = this.stationY;
    const r     = this._rangeMeters * this.meterUnit;
    const angle = Number.isFinite(Number(_state.angleDeg)) ? Number(_state.angleDeg) : 0;

    // Just the bright sweep line — a very tight 1.5° fan so it's visible as a line
    const segs = this._lineSegs;
    const posData = this._posData;
    const alphaData = this._alphaData;
    posData[0] = cx; posData[1] = cy; alphaData[0] = 0.0;
    for (let i = 0; i <= segs; i++) {
      const t   = i / segs;
      const rad = ((angle - 1.5 + t * 1.5) * Math.PI) / 180;
      const idx = i + 1;
      posData[idx * 2]     = cx + Math.sin(rad) * r;
      posData[idx * 2 + 1] = cy - Math.cos(rad) * r;
      alphaData[idx] = 0.9 + t * 0.1;
    }

    gl.useProgram(this.program);
    gl.uniformMatrix4fv(this.uMatrix, false, matrix);

    gl.bindBuffer(gl.ARRAY_BUFFER, this.posBuffer);
    gl.bufferData(gl.ARRAY_BUFFER, posData, gl.DYNAMIC_DRAW);
    gl.enableVertexAttribArray(this.aPos);
    gl.vertexAttribPointer(this.aPos, 2, gl.FLOAT, false, 0, 0);

    gl.bindBuffer(gl.ARRAY_BUFFER, this.alphaBuffer);
    gl.bufferData(gl.ARRAY_BUFFER, alphaData, gl.DYNAMIC_DRAW);
    gl.enableVertexAttribArray(this.aAlpha);
    gl.vertexAttribPointer(this.aAlpha, 1, gl.FLOAT, false, 0, 0);

    gl.enable(gl.BLEND);
    gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);
    gl.disable(gl.DEPTH_TEST);
    gl.drawArrays(gl.TRIANGLE_FAN, 0, segs + 2);
  }
}

function applyRadarFrame(data, frameKey = '', onFrameVisible = null, opts = {}) {
  if (!('vertex_count' in data)) {
    throw new Error('Backend payload mismatch. Rebuild backend and app together.');
  }
  const display = _displayComboFromFrameKey(frameKey, activeCacheKey(), activeFamily);
  const ck = display.comboKey;
  const family = display.family;
  // Ensure the correct pool layer is active for the displayed combo, then set the frame.
  if (!radarLayer || radarLayer.id !== `radar-pool-${ck.replace(/[:.]/g, '-')}`) {
    setActiveComboLayer(ck, family);
  }
  // Enforce the active filter state before uploading/drawing to avoid one-frame flashes.
  const minVal = _paneMinValue(family);
  radarLayer.setMinValue(minVal);
  radarLayerSweep?.setMinValue(minVal);
  layerPoolLastUsed.set(ck, Date.now());
  radarLayer.setFrame(data, () => {
    if (onFrameVisible) onFrameVisible();
    pruneRadarLayerPoolGpuMemory();
  }, opts);
  displayedPrimaryComboKey = ck;
  displayedPrimaryFamily = family;
}

function loadInitialMapStyle() {
  try {
    const raw = localStorage.getItem('radar_settings');
    const settings = raw ? JSON.parse(raw) : {};
    const normalized = _normalizeMapStyleId(settings?.mapStyle);
    if (MAP_STYLE_IDS.has(normalized)) return normalized;
  } catch (_) {}
  return DEFAULT_MAP_STYLE;
}

function _normalizeMapStyleId(styleId) {
  const raw = String(styleId || '').trim();
  if (!raw) return DEFAULT_MAP_STYLE;
  if (raw === MAP_STYLE_BLACK) return DEFAULT_MAP_STYLE;
  if (raw === LEGACY_MAP_STYLE_LIGHT_GRAY) return MAP_STYLE_LIGHT_GRAY;
  return raw;
}

