function _isHybridL2Family(family) {
  const f = String(family || '').trim().toUpperCase();
  return HYBRID_L2_FAMILIES.has(f);
}

function _selectableL2Products() {
  return isLocalRadarMode() ? LOCAL_L2_PRODUCTS : REMOTE_HYBRID_L2_PRODUCTS;
}

function _isL2PathForFamily(family, tilt = activeTilt, stationId = activeStation) {
  return false;
}

function _l2TiltIndexFromL3Tilt(tilt) {
  const t = String(tilt ?? '').trim();
  const idx = L3_TILTS.indexOf(t);
  if (idx >= 0) return idx;
  const parsed = parseInt(t, 10);
  return Number.isFinite(parsed) ? Math.max(0, parsed) : 0;
}

function _capturePreLocalUiState() {
  if (_preLocalUiState) return;
  _preLocalUiState = {
    levelII: Boolean(levelII),
    family: String(activeFamily || 'REF').toUpperCase(),
    tilt: String(activeTilt || '0.5'),
  };
}

function _restoreUiStateAfterLocalExit() {
  const prev = _preLocalUiState;
  _preLocalUiState = null;
  _setActiveL2AvailableProducts(null);

  const wantsL2 = Boolean(prev?.levelII);
  if (wantsL2) {
    const l2Products = _selectableL2Products();
    const fallbackFamily = l2Products.includes('REF') ? 'REF' : l2Products[0];
    levelII = true;
    setDataLevelButtons(2);
    populateFamilySelectL2();
    activeFamily = l2Products.includes(String(prev?.family || ''))
      ? String(prev.family)
      : fallbackFamily;
    activeTilt = String(Math.max(0, parseInt(prev?.tilt, 10) || 0));
    if (tiltSelect) {
      tiltSelect.disabled = false;
      tiltSelect.innerHTML = '<option value="0">0\u00b0</option>';
      tiltSelect.value = activeTilt;
    }
  } else {
    levelII = false;
    setDataLevelButtons(3);
    populateFamilySelectL3(stationId);
    {
      const families = supportedL3FamiliesForStation(stationId);
      activeFamily = families.includes(String(prev?.family || '')) ? String(prev.family) : (families[0] || 'REF');
    }
    activeTilt = restoreTiltSelectL3(stationId, activeFamily, String(prev?.tilt || '0.5')) || '0.5';
  }
  setActiveSelectionUi(activeFamily, activeTilt);
}

function activeRadarPollMs() {
  if (_canUseProcessedWise(activeStation, activeFamily, activeTilt)) return PROCESSED_WISE_POLL_MS;
  return _isL2PathForFamily(activeFamily) ? L2_POLL_MS : POLL_MS;
}

function restartActiveRadarPolling() {
  if (!activeStation || isLocalRadarMode()) return;
  stopPolling();
  _syncProcessedWiseRealtime();
  pollTimer = setInterval(() => loadAll(activeStation, false), activeRadarPollMs());
}

// -- Drawing state -------------------------------------------------------------
let drawMode = false;
let drawPanLocked = false;
let drawMouseDown = false;
let drawLastPx = null;  // [x, y] canvas px of last added point (for distance throttle)
function _normalizeDrawColor(input, fallback = DRAW_DEFAULT_COLOR) {
  const value = String(input || '').trim();
  return /^#[0-9a-f]{6}$/i.test(value) ? value : fallback;
}

function _normalizeDrawThickness(input, fallback = DRAW_DEFAULT_THICKNESS) {
  const parsed = Math.round(Number(input));
  if (!Number.isFinite(parsed)) return fallback;
  return Math.max(1, Math.min(DRAW_MAX_WIDTH, parsed));
}

function _normalizeDrawStyle(input, fallback = DRAW_DEFAULT_STYLE) {
  const value = String(input || '').trim().toLowerCase();
  return ['solid', 'dashed', 'dotted'].includes(value) ? value : fallback;
}

function _normalizeDrawOpacity(input, fallback = DRAW_DEFAULT_OPACITY) {
  const parsed = Number(input);
  if (!Number.isFinite(parsed)) return fallback;
  return Math.max(0.1, Math.min(1, parsed));
}

let drawColor = DRAW_DEFAULT_COLOR;
let drawThickness = DRAW_DEFAULT_THICKNESS;
let drawStyle = DRAW_DEFAULT_STYLE;
let drawOpacity = DRAW_DEFAULT_OPACITY;
let drawPoints = [];    // current in-progress freehand line [[lng, lat], ...]
let drawFeatures = [];  // all completed line features
let measureMode = false;
let measureMouseDown = false;
let measurePoints = []; // current in-progress measure line [[lng, lat], ...]
let measurePreviewLngLat = null;
let measurePreviewPoint = null;
let measureActiveMap = null;

// S3 key string ? decoded frame data (universal cache for all combos + history)
const frameCache = new Map();
const frameCacheBytes = new Map();
let frameCacheTotalBytes = 0;

function estimateDecodedFrameBytes(frame) {
  let bytes = 0;
  if (frame?._bufXy?.byteLength) bytes += frame._bufXy.byteLength;
  if (frame?._bufColor?.byteLength) bytes += frame._bufColor.byteLength;
  if (frame?._bufVals?.byteLength) bytes += frame._bufVals.byteLength;
  if (frame?._bufTypes?.byteLength) bytes += frame._bufTypes.byteLength;
  return bytes;
}

function _frameCacheByteLimit() {
  try {
    return (_tlDragging || isPlaying || historyIdx >= 0)
      ? FRAME_CACHE_BYTES_TIMELINE
      : FRAME_CACHE_BYTES_BASE;
  } catch (_) {
    return FRAME_CACHE_BYTES_BASE;
  }
}

function _collectProtectedFrameCacheKeys() {
  const protectedKeys = new Set();
  const add = key => { if (key) protectedKeys.add(String(key)); };
  try { add(viewedKey()); } catch (_) {}
  try { add(sweepPendingKey); } catch (_) {}
  try { add(sweepNewKey); } catch (_) {}
  try { add(comboLatestKey.get(activeCacheKey())); } catch (_) {}
  try {
    for (const pane of secondaryPaneMaps.values()) {
      if (!pane || pane.id > multiPaneCount) continue;
      add(pane.frameKey);
      add(pane.lastKey);
      const comboKey = _paneComboKey(pane);
      const entries = historyMap.get(comboKey) || [];
      const targetIndex = Math.max(0, Math.min(_targetHistoryIndexForEntries(entries), entries.length - 1));
      for (let offset = -2; offset <= 2; offset += 1) add(entries[targetIndex + offset]?.key);
    }
  } catch (_) {}
  try {
    const entries = historyMap.get(_timelineComboKey()) || [];
    const center = _timelineCurrentIndex(entries);
    const radius = (_tlDragging || isPlaying) ? HISTORY_MANUAL_PREFETCH_RADIUS : 1;
    for (let offset = -radius; offset <= radius; offset += 1) add(entries[center + offset]?.key);
  } catch (_) {}
  return protectedKeys;
}

const _frameCacheNative = {
  get: frameCache.get.bind(frameCache),
  set: frameCache.set.bind(frameCache),
  has: frameCache.has.bind(frameCache),
  delete: frameCache.delete.bind(frameCache),
  clear: frameCache.clear.bind(frameCache),
};

function pruneFrameCacheBytes() {
  const limit = _frameCacheByteLimit();
  if (frameCacheTotalBytes <= limit) return;
  const protectedKeys = _collectProtectedFrameCacheKeys();
  for (const key of frameCache.keys()) {
    if (frameCacheTotalBytes <= limit) break;
    if (protectedKeys.has(String(key))) continue;
    deleteFrameCache(key);
  }
  if (RADAR_PERF_DEBUG && frameCacheTotalBytes > limit) {
    console.log('[RadarPerf]', {
      cache: 'decoded-frame',
      action: 'prune-incomplete',
      frameCacheTotalBytes,
      limit,
      entries: frameCache.size,
    });
  }
}

function setFrameCache(key, frame) {
  if (!key) return frameCache;
  deleteFrameCache(key);
  _frameCacheNative.set(key, frame);
  const bytes = estimateDecodedFrameBytes(frame);
  frameCacheBytes.set(key, bytes);
  frameCacheTotalBytes += bytes;
  pruneFrameCacheBytes();
  return frameCache;
}

function deleteFrameCache(key) {
  if (!_frameCacheNative.has(key)) return false;
  const bytes = frameCacheBytes.get(key) || 0;
  frameCacheBytes.delete(key);
  frameCacheTotalBytes = Math.max(0, frameCacheTotalBytes - bytes);
  return _frameCacheNative.delete(key);
}

function clearFrameCache() {
  frameCacheBytes.clear();
  frameCacheTotalBytes = 0;
  _frameCacheNative.clear();
}

frameCache.set = function(key, frame) {
  setFrameCache(key, frame);
  return this;
};
frameCache.delete = function(key) {
  return deleteFrameCache(key);
};
frameCache.clear = function() {
  clearFrameCache();
};
frameCache.get = function(key) {
  const value = _frameCacheNative.get(key);
  if (_frameCacheNative.has(key)) {
    _frameCacheNative.delete(key);
    _frameCacheNative.set(key, value);
  }
  return value;
};
// `${stationId}:${family}:${tilt}` ? latest S3 key string
const comboLatestKey = new Map();
// `${stationId}:${family}:${tilt}` ? [{key, ...meta}] oldest?newest
const historyMap = new Map();
const comboHistoryTargetFrames = new Map();
let historyIdx = -1; // current slider position; -1 = snap to latest
let _timelineAnchorComboKey = '';

function historyFrameLimitForCombo(comboKey) {
  const raw = Number(comboHistoryTargetFrames.get(comboKey) || DEFAULT_L3_HISTORY_FRAMES);
  return Math.max(1, Math.min(MAX_HISTORY_FRAMES, Math.round(raw) || DEFAULT_L3_HISTORY_FRAMES));
}

function historyFrameLimitForSelection(stationId, family, tilt) {
  const sid = canonicalStationId(stationId);
  const fam = String(family || '').toUpperCase();
  const tlt = normalizeTiltForStationFamily(sid, fam, tilt);
  return historyFrameLimitForCombo(`${sid}:${fam}:${tlt}`);
}

function _timelineComboKey() {
  return String(_timelineAnchorComboKey || activeCacheKey() || '');
}

function _timelineHistory() {
  const ck = _timelineComboKey();
  return ck ? (historyMap.get(ck) || []) : [];
}

function _timelineCurrentIndex(history = _timelineHistory()) {
  if (!Array.isArray(history) || !history.length) return -1;
  return (historyIdx >= 0 && historyIdx < history.length)
    ? historyIdx
    : (history.length - 1);
}

function _timelineOffsetFromLatest(history = _timelineHistory()) {
  if (!Array.isArray(history) || !history.length) return 0;
  const latestIndex = Math.max(0, history.length - 1);
  const currentIndex = _timelineCurrentIndex(history);
  if (currentIndex < 0) return 0;
  return Math.max(0, latestIndex - currentIndex);
}

function _historyIndexFromPlaybackOffset(entries, offsetFromLatest = _timelineOffsetFromLatest()) {
  if (!Array.isArray(entries) || !entries.length) return -1;
  const boundedOffset = Math.max(0, Math.min(entries.length - 1, Math.round(Number(offsetFromLatest) || 0)));
  return Math.max(0, entries.length - 1 - boundedOffset);
}

function _shouldPreserveTimelineOffsetForCombo(comboKey) {
  return !!comboKey
    && comboKey === _timelineComboKey()
    && (isPlaying || _isManualHistoryActive(comboKey) || historyIdx >= 0);
}

function _setL3HistoryEntries(comboKey, entries, preferredKey = null) {
  if (!comboKey) return;
  const prevHistory = historyMap.get(comboKey) || [];
  const prevOffsetFromLatest = _shouldPreserveTimelineOffsetForCombo(comboKey)
    ? _timelineOffsetFromLatest(prevHistory)
    : 0;
  const deduped = [];
  const seen = new Set();
  for (const entry of Array.isArray(entries) ? entries : []) {
    const key = String(entry?.key || '');
    if (!key || seen.has(key)) continue;
    seen.add(key);
    deduped.push(entry.key ? entry : { key });
  }
  if (!deduped.length) return;
  deduped.sort((a, b) => {
    const aTs = parseKeyTimestampMs(a.key);
    const bTs = parseKeyTimestampMs(b.key);
    if (Number.isFinite(aTs) && Number.isFinite(bTs) && aTs !== bTs) return aTs - bTs;
    return String(a.key || '').localeCompare(String(b.key || ''));
  });
  const nextHistory = deduped.slice(-historyFrameLimitForCombo(comboKey));
  historyMap.set(comboKey, nextHistory);
  const keepKey = preferredKey && nextHistory.some(entry => entry.key === preferredKey)
    ? preferredKey
    : nextHistory[nextHistory.length - 1].key;
  comboLatestKey.set(comboKey, keepKey);
  if (comboKey === _timelineComboKey()) {
    if (_shouldPreserveTimelineOffsetForCombo(comboKey)) {
      historyIdx = _historyIndexFromPlaybackOffset(nextHistory, prevOffsetFromLatest);
    } else {
      historyIdx = Math.max(0, nextHistory.findIndex(entry => entry.key === keepKey));
    }
    updateSlider();
    startFrameTracking(nextHistory.map(entry => entry.key));
    _syncTlLoadProgress();
  }
}

function clearAllRuntimeCaches() {
  frameCache.clear();
  comboLatestKey.clear();
  historyMap.clear();
  comboHistoryTargetFrames.clear();
  latestKeyCache.clear();
  _processedWiseLatestCache.clear();
  _processedWisePrefetchBytes.clear();
  _l2RetryCooldowns.clear();
  decodeQueue = [];
  clearL3WarmQueue();
  _l2ScanCache = { station: null, scans: [], fullAt: 0 };
  historyIdx = -1;
  sweepPendingKey = null;
  sweepNewKey = null;
  sweepNewData = null;
  startFrameTracking([]);

  try { radarLayer?.clearFrame(); } catch (_) {}
  try { radarLayerSweep?.clearFrame(); } catch (_) {}

  for (const layer of layerPool.values()) {
    try { layer.clearFrame(); } catch (_) {}
  }

  for (const pane of secondaryPaneMaps.values()) {
    pane.lastKey = null;
    pane.historyIdx = -1;
    pane.lastFrameData = null;
    pane.loadToken += 1;
    pane.inflight = false;
    pane.sweepState = null;
    _setPaneFrameTime(pane.id, '', null);
    try { pane.radarLayer?.clearFrame(); } catch (_) {}
    try { pane.sweepLayer?.clearFrame(); } catch (_) {}
    for (const layer of pane.layerPool.values()) {
      try { layer.clearFrame(); } catch (_) {}
    }
  }
}

// Parallel decode queue for the active radar selection.
const N_DECODE_WORKERS_L3 = 2;
const N_DECODE_WORKERS_L3_BURST = 3;
const N_DECODE_WORKERS_L2 = 2;
const L3_DECODE_BURST_MS = 7000;
const MANUAL_HISTORY_BURST_MS = 18000;
const MANUAL_HISTORY_PLAY_BURST_MS = 12000;
const DECODE_BACKGROUND_YIELD_MS = 4;
const STATION_LOAD_DRAIN_MS = 1200;
const PROCESSED_WISE_SIBLING_WARM_THROTTLE_MS = 6000;
let _l3DecodeBurstUntil = 0;
let _processedWiseWarmSeq = 0;
let _processedWiseLastWarmKey = '';
let _processedWiseLastWarmAt = 0;
let _processedWiseWarmTimer = null;
let _manualHistoryBurstUntil = 0;
let _manualHistoryBurstComboKey = '';

function requestL3DecodeBurst(durationMs = L3_DECODE_BURST_MS) {
  const ms = Math.max(500, Math.round(Number(durationMs) || L3_DECODE_BURST_MS));
  const nextUntil = Date.now() + ms;
  if (nextUntil > _l3DecodeBurstUntil) _l3DecodeBurstUntil = nextUntil;
  startDecodeWorkers();
}

function _isManualHistoryBurstActive(comboKey = _timelineComboKey()) {
  return !!comboKey
    && comboKey === _manualHistoryBurstComboKey
    && comboKey === _manualHistoryComboKey
    && Date.now() < _manualHistoryBurstUntil;
}

function _refreshManualHistoryBurst(comboKey = _timelineComboKey(), durationMs = MANUAL_HISTORY_BURST_MS) {
  if (!comboKey) return;
  _manualHistoryBurstComboKey = comboKey;
  const ms = Math.max(1000, Math.round(Number(durationMs) || MANUAL_HISTORY_BURST_MS));
  const nextUntil = Date.now() + ms;
  if (nextUntil > _manualHistoryBurstUntil) _manualHistoryBurstUntil = nextUntil;
  requestL3DecodeBurst(ms);
}

function _clearManualHistoryBurst(comboKey = '') {
  if (comboKey && comboKey !== _manualHistoryBurstComboKey) return;
  _manualHistoryBurstUntil = 0;
  _manualHistoryBurstComboKey = '';
}

function currentDecodeWorkerLimit() {
  if (_isL2PathForFamily(activeFamily)) return N_DECODE_WORKERS_L2;
  if (_isManualHistoryBurstActive()) return N_DECODE_WORKERS_L3_BURST;
  return Date.now() < _l3DecodeBurstUntil ? N_DECODE_WORKERS_L3_BURST : N_DECODE_WORKERS_L3;
}
let decodeQueue = [];
let decodeWorkerCount = 0;
const decodeWaiters = new Map();
const _l3WarmPending = new Set();
let _l3WarmTimer = null;
let _stationProductPreloadSeq = 0;
let _stationVisiblePanePreloadTimer = null;
let _stationAllProductPreloadTimer = null;

function scheduleL3WarmFlush() {
  if (_l3WarmTimer) return;
  _l3WarmTimer = setTimeout(async () => {
    _l3WarmTimer = null;
    if (!_l3WarmPending.size) return;
    const batch = Array.from(_l3WarmPending).slice(0, 16);
    batch.forEach(k => _l3WarmPending.delete(k));
    try {
      const decodeOpts = getActiveDecodeOptions();
      await invoke('l3_warm_keys', {
        keys: batch,
        palettes: decodeOpts.palettes,
      });
    } catch (_) {}
    if (_l3WarmPending.size) scheduleL3WarmFlush();
  }, 40);
}

function clearL3WarmQueue() {
  _l3WarmPending.clear();
  if (_l3WarmTimer) {
    clearTimeout(_l3WarmTimer);
    _l3WarmTimer = null;
  }
  if (_processedWiseWarmTimer) {
    clearTimeout(_processedWiseWarmTimer);
    _processedWiseWarmTimer = null;
  }
  if (_stationVisiblePanePreloadTimer) {
    clearTimeout(_stationVisiblePanePreloadTimer);
    _stationVisiblePanePreloadTimer = null;
  }
  if (_stationAllProductPreloadTimer) {
    clearTimeout(_stationAllProductPreloadTimer);
    _stationAllProductPreloadTimer = null;
  }
  _stationProductPreloadSeq += 1;
}

function _processedWiseWarmSelectionKey(stationId = activeStation, family = activeFamily, tilt = activeTilt) {
  const sid = canonicalStationId(stationId);
  const fam = String(family || '').toUpperCase();
  if (!_canUseProcessedWise(sid, fam, tilt)) return '';
  return `${sid}:${fam}:${_normalizeProcessedWiseTilt(fam, tilt)}`;
}

function scheduleProcessedWiseSiblingWarm(stationId = activeStation, family = activeFamily, tilt = activeTilt, opts = {}) {
  const selectionKey = _processedWiseWarmSelectionKey(stationId, family, tilt);
  if (!selectionKey) return;
  if (_isManualHistoryActive(selectionKey)) return;
  if (_stationVisiblePanePreloadTimer || _stationAllProductPreloadTimer) return;
  const force = opts?.force === true;
  const now = Date.now();
  if (!force
    && _processedWiseLastWarmKey === selectionKey
    && (now - _processedWiseLastWarmAt) < PROCESSED_WISE_SIBLING_WARM_THROTTLE_MS) {
    return;
  }
  // Delay sibling warming so it doesn't compete with the active frame decode/render.
  clearTimeout(_processedWiseWarmTimer);
  _processedWiseWarmTimer = setTimeout(() => {
    _processedWiseWarmTimer = null;
    _processedWiseLastWarmKey = selectionKey;
    _processedWiseLastWarmAt = Date.now();
    const seq = ++_processedWiseWarmSeq;
    void _warmProcessedWiseSiblingProducts(seq, stationId, family, tilt);
  }, 2500);
}

async function _warmProcessedWiseSiblingProducts(seq, stationId, family, tilt) {
  const sid = canonicalStationId(stationId);
  const primaryFamily = String(family || '').toUpperCase();
  if (!_canUseProcessedWise(sid, primaryFamily, tilt)) return;
  const siblings = supportedL3FamiliesForStation(sid).filter(otherFamily => otherFamily && otherFamily !== primaryFamily);
  if (!siblings.length) return;
  // Don't burst — sibling warming uses normal worker limit so it doesn't compete with active frame.
  await Promise.allSettled(siblings.map(async otherFamily => {
    const otherTilt = normalizeTiltForStationFamily(sid, otherFamily, tilt);
    const latestMeta = await findLatestKeyCurrentOnly(sid, { family: otherFamily, tilt: otherTilt });
    if (!latestMeta?.key) return;
    if (seq !== _processedWiseWarmSeq) return;
    const comboKey = `${sid}:${otherFamily}:${otherTilt}`;
    const prevKey = comboLatestKey.get(comboKey);
    const prevTs = parseKeyTimestampMs(prevKey || '');
    const nextTs = parseKeyTimestampMs(latestMeta.key);
    if (prevKey && Number.isFinite(prevTs) && Number.isFinite(nextTs) && nextTs < prevTs) return;
    comboLatestKey.set(comboKey, latestMeta.key);
    if (RADAR_PRELOAD_MODE === 'off') {
      return;
    }
    if (RADAR_PRELOAD_MODE === 'raw-only') {
      void _prefetchProcessedWiseRawBytes(latestMeta);
      return;
    }
    if (!frameCache.has(latestMeta.key) && !_isDecodeQueued(latestMeta.key)) {
      enqueueDecode(latestMeta.key, latestMeta, false);
    }
  }));
}

function _allProcessedWiseSelectionsForStation(stationId = activeStation, tilt = activeTilt) {
  const sid = canonicalStationId(stationId);
  if (!sid || levelII || isLocalRadarMode()) return [];
  const families = supportedL3FamiliesForStation(sid);
  const seen = new Set();
  return families.reduce((list, family) => {
    const normalizedFamily = String(family || '').trim().toUpperCase();
    if (!normalizedFamily) return list;
    const normalizedTilt = normalizeTiltForStationFamily(sid, normalizedFamily, tilt);
    if (!_canUseProcessedWise(sid, normalizedFamily, normalizedTilt)) return list;
    const comboKey = `${sid}:${normalizedFamily}:${normalizedTilt}`;
    if (seen.has(comboKey)) return list;
    seen.add(comboKey);
    list.push({
      station: sid,
      family: normalizedFamily,
      tilt: normalizedTilt,
      comboKey,
    });
    return list;
  }, []);
}

async function _runWithConcurrency(items, limit, worker) {
  const list = Array.isArray(items) ? items : [];
  if (!list.length || typeof worker !== 'function') return;
  const concurrency = Math.max(1, Math.min(list.length, Math.round(Number(limit) || 1)));
  let index = 0;
  await Promise.allSettled(Array.from({ length: concurrency }, async () => {
    while (true) {
      const current = index;
      index += 1;
      if (current >= list.length) return;
      await worker(list[current], current);
    }
  }));
}

async function _preloadLatestProcessedWiseSelections(seq, selections, { priority = false } = {}) {
  const concurrency = priority ? 3 : 2;
  await _runWithConcurrency(selections, concurrency, async selection => {
    if (seq !== _stationProductPreloadSeq) return;
    if (!activeStation || canonicalStationId(selection?.station) !== canonicalStationId(activeStation)) return;
    const family = String(selection?.family || '').toUpperCase();
    const tilt = String(selection?.tilt || '');
    if (!family || !_canUseProcessedWise(activeStation, family, tilt)) return;
    try {
      let latestMeta = await findLatestKeyCurrentOnly(activeStation, { family, tilt });
      if (!latestMeta?.key) {
        latestMeta = await findLatestKey(activeStation, { family, tilt });
      }
      if (!latestMeta?.key || seq !== _stationProductPreloadSeq) return;
      const comboKey = String(selection?.comboKey || `${canonicalStationId(activeStation)}:${family}:${tilt}`);
      const prevKey = comboLatestKey.get(comboKey);
      const prevTs = parseKeyTimestampMs(prevKey || '');
      const nextTs = parseKeyTimestampMs(latestMeta.key);
      if (prevKey && Number.isFinite(prevTs) && Number.isFinite(nextTs) && nextTs < prevTs) return;
      _storePassiveComboHistoryEntries(
        comboKey,
        [...(historyMap.get(comboKey) || []), latestMeta],
        latestMeta.key,
        Math.max(1, historyFrameLimitForCombo(comboKey)),
      );
      const shouldDecode = RADAR_PRELOAD_MODE === 'decode-all'
        || (RADAR_PRELOAD_MODE === 'decode-visible' && priority);
      if (RADAR_PRELOAD_MODE === 'off') return;
      if (RADAR_PRELOAD_MODE === 'raw-only' || !shouldDecode) {
        void _prefetchProcessedWiseRawBytes(latestMeta);
        return;
      }
      if (!frameCache.has(latestMeta.key) && !_isDecodeQueued(latestMeta.key)) {
        enqueueDecode(latestMeta.key, latestMeta, priority);
      }
    } catch (_) {}
  });
}

function scheduleStationProductPreload(stationId = activeStation, family = activeFamily, tilt = activeTilt) {
  const sid = canonicalStationId(stationId);
  if (!_canUseProcessedWise(sid, family, tilt)) return;
  const seq = ++_stationProductPreloadSeq;
  if (_stationVisiblePanePreloadTimer) clearTimeout(_stationVisiblePanePreloadTimer);
  if (_stationAllProductPreloadTimer) clearTimeout(_stationAllProductPreloadTimer);

  const visibleSelections = _visibleProcessedWiseSelections(sid);
  const visibleSecondarySelections = visibleSelections.filter(selection => !selection.isPrimary);
  const allSelections = _allProcessedWiseSelectionsForStation(sid, tilt);
  const visibleComboKeys = new Set(visibleSelections.map(selection => selection.comboKey));
  const remainingSelections = allSelections.filter(selection => !visibleComboKeys.has(selection.comboKey));

  _stationVisiblePanePreloadTimer = setTimeout(() => {
    if (seq !== _stationProductPreloadSeq || sid !== canonicalStationId(activeStation)) return;
    _stationVisiblePanePreloadTimer = null;
    if (multiPaneCount > 1 && !levelII) {
      void _loadVisibleSecondaryPanes({ force: true });
    }
    void _preloadLatestProcessedWiseSelections(seq, visibleSecondarySelections, { priority: true });
  }, 180);

  _stationAllProductPreloadTimer = setTimeout(() => {
    if (seq !== _stationProductPreloadSeq || sid !== canonicalStationId(activeStation)) return;
    _stationAllProductPreloadTimer = null;
    void _preloadLatestProcessedWiseSelections(seq, remainingSelections, { priority: false });
  }, 1200);
}

function queueL3WarmKey(key) {
  if (!key || frameCache.has(key) || key.startsWith('L2:') || key.startsWith('WISE:')) return;
  _l3WarmPending.add(key);
  scheduleL3WarmFlush();
}

function activeCacheKey() { return `${activeStation}:${activeFamily}:${activeTilt}`; }

function _l2ScanSigFromKey(key) {
  const parts = String(key || '').split(':');
  if (parts.length < 4 || parts[0] !== 'L2') return '';
  return `${parts[1]}:${parts[2]}:${parts[3]}`;
}

function _isRetryableL2ErrorMessage(message) {
  return /Incomplete L2 sweep|L2 chunks still uploading|PyART could not read L2 data|No L2 chunks found|Missing L2 chunks/.test(String(message || ''));
}

function _isL2RetryCoolingDown(key) {
  if (!String(key || '').startsWith('L2:')) return false;
  const until = Number(_l2RetryCooldowns.get(key) || 0);
  if (!until) return false;
  if (Date.now() >= until) {
    _l2RetryCooldowns.delete(key);
    return false;
  }
  return true;
}

function _markL2RetryCooldown(key, delayMs = L2_RETRY_COOLDOWN_MS) {
  if (!String(key || '').startsWith('L2:')) return;
  _l2RetryCooldowns.set(key, Date.now() + Math.max(1000, delayMs));
}

function _isDecodeQueued(key) {
  return decodeQueue.some(job => job.s3key === key);
}

function _pruneL2DecodeQueue(stationId, keepKeys = []) {
  if (!stationId) return;
  const prefix = `L2:${stationId}:`;
  const keep = new Set(keepKeys.filter(Boolean));
  const activeView = viewedKey();
  if (activeView && activeView.startsWith(prefix)) keep.add(activeView);
  if (sweepPendingKey && String(sweepPendingKey).startsWith(prefix)) keep.add(sweepPendingKey);
  decodeQueue = decodeQueue.filter(job => {
    if (!String(job?.s3key || '').startsWith(prefix)) return true;
    return keep.has(job.s3key);
  });
}

function _findL2FallbackEntry(ck, failedKey) {
  const history = historyMap.get(ck) || [];
  for (let i = history.length - 1; i >= 0; i--) {
    const entry = history[i];
    if (!entry?.key || entry.key === failedKey) continue;
    if (frameCache.has(entry.key)) return { entry, index: i };
  }
  return null;
}

function _fallbackActiveL2Frame(failedKey, message) {
  if (!_isL2PathForFamily(activeFamily)) return false;
  const ck = activeCacheKey();
  const history = historyMap.get(ck) || [];
  if (!history.some(entry => entry?.key === failedKey)) return false;
  const fallback = _findL2FallbackEntry(ck, failedKey);
  if (!fallback) {
    for (let i = history.length - 1; i >= 0; i--) {
      const entry = history[i];
      if (!entry?.key || entry.key === failedKey) continue;
      historyIdx = i;
      comboLatestKey.set(ck, entry.key);
      updateSlider();
      const { key, ...meta } = entry;
      enqueueDecode(key, meta, true);
      setFrameLabel(message || 'Waiting for complete L2 scan', 'loading');
      return true;
    }
    return false;
  }
  comboLatestKey.set(ck, fallback.entry.key);
  historyIdx = fallback.index;
  updateSlider();
  if (!sweepActive) showFrame(fallback.entry.key);
  setFrameLabel(message || 'Waiting for complete L2 scan', 'loading');
  return true;
}

function isLocalRadarMode() {
  return !!localRadarSession;
}

function _localFileName(path) {
  return String(path || '').split(/[/\\]/).pop() || 'Local Radar File';
}

function _nearestL3TiltForElevation(elevation) {
  const want = Number(elevation);
  if (!Number.isFinite(want)) return '0.5';
  let best = '0.5';
  let bestDiff = Infinity;
  for (const tilt of L3_TILTS) {
    const diff = Math.abs(Number(tilt) - want);
    if (diff < bestDiff) {
      bestDiff = diff;
      best = tilt;
    }
  }
  return best;
}

function _localFamilyFromField(field) {
  const f = String(field || '').toLowerCase();
  if (!f) return 'REF';
  if (f.includes('specific_differential_phase')) return 'KDP';
  if (f.includes('differential_reflectivity')) return 'ZDR';
  if (f.includes('cross_correlation')) return 'CC';
  if (f.includes('velocity')) return 'VEL';
  if (f.includes('echo_top')) return 'EET';
  return 'REF';
}

function _localComboId(product, tiltIdx) {
  return `${String(product || 'REF').toUpperCase()}:${Math.max(0, parseInt(tiltIdx, 10) || 0)}`;
}

function _localFrameKey(path, product, tiltIdx) {
  return `FILE:${path}:${_localComboId(product, tiltIdx)}`;
}

function _storeLocalDecodedCombo(path, product, tiltIdx, data) {
  const comboProduct = String(product || 'REF').toUpperCase();
  const comboTilt = String(Math.max(0, parseInt(tiltIdx, 10) || 0));
  const frameKey = _localFrameKey(path, comboProduct, comboTilt);
  const ck = `${LOCAL_FILE_STATION_ID}:${comboProduct}:${comboTilt}`;
  frameCache.set(frameKey, data);
  historyMap.set(ck, [{ key: frameKey }]);
  comboLatestKey.set(ck, frameKey);
  return frameKey;
}

function _showCachedLocalActiveCombo() {
  if (!localRadarSession?.path) return false;
  const product = LOCAL_L2_PRODUCTS.includes(String(activeFamily || '').toUpperCase())
    ? String(activeFamily || '').toUpperCase()
    : 'REF';
  const tiltIdx = Math.max(0, parseInt(activeTilt, 10) || 0);
  const frameKey = _localFrameKey(localRadarSession.path, product, tiltIdx);
  const data = frameCache.get(frameKey);
  if (!data) return false;
  const ck = activeCacheKey();
  historyMap.set(ck, [{ key: frameKey }]);
  comboLatestKey.set(ck, frameKey);
  historyIdx = 0;
  updateSlider();
  startFrameTracking([frameKey]);
  setStationInfoLocalFile(localRadarSession.name, data);
  showFrame(frameKey);
  return true;
}

function _clearLocalRadarCaches() {
  for (const key of [...frameCache.keys()]) {
    if (String(key).startsWith('FILE:')) frameCache.delete(key);
  }
  for (const ck of [...historyMap.keys()]) {
    if (String(ck).startsWith(`${LOCAL_FILE_STATION_ID}:`)) historyMap.delete(ck);
  }
  for (const ck of [...comboLatestKey.keys()]) {
    if (String(ck).startsWith(`${LOCAL_FILE_STATION_ID}:`)) comboLatestKey.delete(ck);
  }
  for (const [ck, layer] of layerPool.entries()) {
    if (!String(ck).startsWith(`${LOCAL_FILE_STATION_ID}:`)) continue;
    try { layer.clearFrame(); } catch (_) {}
  }
}

// Drop queued decode jobs that won't be useful after a product/tilt switch.
// Keeps: all frames for the new active combo + the latest-frame job for every
// other combo of the current station (so repeated switches are instant once
// those latests finish decoding, without re-downloading anything).
// Drops: history frames for old combos that the user is leaving behind.
function clearStaleQueueItems() {
  const ck = activeCacheKey();
  const history = historyMap.get(ck) || [];
  const keepKeys = new Set(history.map(h => h.key));
  const latest = comboLatestKey.get(ck);
  if (latest) keepKeys.add(latest);
  if (_isManualHistoryActive(ck)) {
    decodeQueue = decodeQueue.filter(job => keepKeys.has(job.s3key));
    return;
  }
  if (_isL2PathForFamily(activeFamily) && activeStation && !isLocalRadarMode()) {
    const visible = viewedKey();
    if (visible) keepKeys.add(visible);
    decodeQueue = decodeQueue.filter(job => {
      const key = String(job?.s3key || '');
      if (!key.startsWith(`L2:${activeStation}:`)) return true;
      return keepKeys.has(key);
    });
    return;
  }
  // Retain in-queue latest-frame jobs for all other combos of the current station
  // so that decoding them continues even while the user browses different products.
  if (activeStation) {
    for (const [otherCk, otherLatest] of comboLatestKey.entries()) {
      if (otherCk.startsWith(activeStation + ':') && otherLatest) {
        keepKeys.add(otherLatest);
      }
    }
  }
  decodeQueue = decodeQueue.filter(job => keepKeys.has(job.s3key));
}

function enqueueDecode(s3key, meta, priority = false) {
  if (String(s3key || '').startsWith('WISE:') && _isWiseNotFoundCoolingDown(s3key)) {
    return;
  }
  if (frameCache.has(s3key) && !meta?.forceDecode) {
    // Already cached — render it if it's the active frame
    // (but don't override the base layer if a sweep is in progress)
    if (activeStation && s3key === viewedKey() && !sweepActive) showFrame(s3key);
    return;
  }
  if (_isL2RetryCoolingDown(s3key) && !meta?.forceDecode) {
    return;
  }
  decodeQueue = decodeQueue.filter(j => j.s3key !== s3key);
  if (priority) decodeQueue.unshift({ s3key, meta, priority: true });
  else          decodeQueue.push({ s3key, meta, priority: false });
  if (priority && String(s3key).startsWith('L2:') && activeStation) {
    _pruneL2DecodeQueue(activeStation, [s3key, comboLatestKey.get(activeCacheKey())]);
  }
  startDecodeWorkers();
}

function _waitForDecodedFrame(key) {
  if (frameCache.has(key)) return Promise.resolve(frameCache.get(key));
  return new Promise((resolve, reject) => {
    const waiters = decodeWaiters.get(key) || [];
    waiters.push({ resolve, reject });
    decodeWaiters.set(key, waiters);
  });
}

function _settleDecodedFrameWaiters(key, error = null, data = null) {
  const waiters = decodeWaiters.get(key);
  if (!waiters?.length) return;
  decodeWaiters.delete(key);
  for (const waiter of waiters) {
    try {
      if (error) waiter.reject(error);
      else waiter.resolve(data ?? frameCache.get(key));
    } catch (_) {}
  }
}

async function ensureFrameDecoded(s3key, meta = {}, priority = false) {
  if (frameCache.has(s3key) && !meta?.forceDecode) {
    if (activeStation && s3key === viewedKey() && !sweepActive) showFrame(s3key);
    return frameCache.get(s3key);
  }
  const pending = _waitForDecodedFrame(s3key);
  enqueueDecode(s3key, meta, priority);
  return pending;
}

function viewedKey() {
  const ck = _timelineComboKey();
  const history = historyMap.get(ck) || [];
  if (history.length > 0) {
    const idx = (historyIdx >= 0 && historyIdx < history.length) ? historyIdx : history.length - 1;
    return history[idx].key;
  }
  return comboLatestKey.get(ck);
}

function _pruneDecodedFramesForCombo(comboKey, keepKeys = []) {
  if (!comboKey) return;
  const keep = new Set((Array.isArray(keepKeys) ? keepKeys : [keepKeys]).filter(Boolean));
  const residentKeys = _residentComboKeysForCurrentStation();
  if (residentKeys.has(comboKey)) {
    const history = historyMap.get(comboKey) || [];
    const preferredIndex = comboKey === _timelineComboKey()
      ? _timelineCurrentIndex(history)
      : Math.max(0, Math.min(_targetHistoryIndexForEntries(history), history.length - 1));
    const residentKey = history[preferredIndex]?.key || comboLatestKey.get(comboKey);
    if (residentKey) keep.add(residentKey);
  } else {
    const latestKey = comboLatestKey.get(comboKey);
    if (latestKey) keep.add(latestKey);
  }
  for (const key of [...frameCache.keys()]) {
    if (comboKeyFromS3Key(String(key || '')) !== comboKey) continue;
    if (keep.has(key)) continue;
    frameCache.delete(key);
  }
}

// Evict least-recently-inserted non-protected frames when cache grows too large.
// Keeps current history + sweep frame safe; evicts background combo frames.
// Base limit; raised while timeline is active (scrubbing or playing history)
// so the frames we just decoded stay resident across a full scrub pass.
const FRAME_CACHE_BASE = 160;
const FRAME_CACHE_TIMELINE_ACTIVE = 300;
const HISTORY_SCRUB_PREFETCH_RADIUS = 16;
const HISTORY_MANUAL_PREFETCH_RADIUS = 1;
const TIMELINE_SETTLE_DEBOUNCE_MS = 140;

function _frameCacheMax() {
  return (_tlDragging || isPlaying || historyIdx >= 0)
    ? FRAME_CACHE_TIMELINE_ACTIVE
    : FRAME_CACHE_BASE;
}

function _collectVisiblePaneHistoryProtectionKeys() {
  const protectedKeys = new Set();
  const protectMultiPaneHistory = multiPaneCount > 1 && (historyIdx >= 0 || isPlaying || historyHoldDirection !== 0);
  if (!protectMultiPaneHistory || !activeStation) return protectedKeys;
  for (const pane of secondaryPaneMaps.values()) {
    if (!pane || pane.id > multiPaneCount) continue;
    if (!pane.productSelected) continue;
    const comboKey = _paneComboKey(pane);
    const entries = historyMap.get(comboKey) || [];
    for (const entry of entries) {
      const key = String(entry?.key || '');
      if (key) protectedKeys.add(key);
    }
  }
  return protectedKeys;
}

function _historyPrefetchOffsets(radius, direction = 0) {
  const offsets = [0];
  const boundedRadius = Math.max(0, Math.floor(Number(radius) || 0));
  const forwardFirst = direction >= 0;
  for (let step = 1; step <= boundedRadius; step += 1) {
    if (forwardFirst) {
      offsets.push(step, -step);
    } else {
      offsets.push(-step, step);
    }
  }
  return offsets;
}

function _enqueueHistoryNeighborhood(entries, centerIndex, { direction = 0, radius = HISTORY_SCRUB_PREFETCH_RADIUS, priorityCenter = false } = {}) {
  if (!Array.isArray(entries) || !entries.length) return;
  const offsets = _historyPrefetchOffsets(radius, direction);
  for (const offset of offsets) {
    const idx = centerIndex + offset;
    if (idx < 0 || idx >= entries.length) continue;
    const entry = entries[idx];
    const key = String(entry?.key || '');
    if (!key || frameCache.has(key) || _isDecodeQueued(key)) continue;
    const { key: _ignoredKey, ...meta } = entry;
    enqueueDecode(key, meta, priorityCenter && offset === 0);
  }
}

function _prefetchVisiblePaneHistoryNeighborhood(centerIndex, direction = 0) {
  if (!activeStation) return;
  requestL3DecodeBurst();
  const ck = _timelineComboKey();
  const activeHistory = historyMap.get(ck) || [];
  const manualHistoryActive = _isManualHistoryActive(ck);
  if (activeHistory.length) {
    const boundedCenter = Math.max(0, Math.min(centerIndex, activeHistory.length - 1));
    if (manualHistoryActive) {
      _queueManualHistoryBurst(activeHistory, boundedCenter, {
        includeBackfill: false,
        burstMs: MANUAL_HISTORY_BURST_MS,
      });
    } else {
      _enqueueHistoryNeighborhood(activeHistory, boundedCenter, {
        direction,
        radius: HISTORY_SCRUB_PREFETCH_RADIUS,
        priorityCenter: true,
      });
    }
  }
  if (multiPaneCount <= 1) return;
  for (const pane of secondaryPaneMaps.values()) {
    if (!pane || pane.id > multiPaneCount) continue;
    if (!pane.productSelected) continue;
    const comboKey = _paneComboKey(pane);
    const entries = historyMap.get(comboKey) || [];
    if (!entries.length) continue;
    const targetIndex = Math.max(0, Math.min(_targetHistoryIndexForEntries(entries), entries.length - 1));
    _enqueueHistoryNeighborhood(entries, targetIndex, {
      direction,
      radius: HISTORY_SCRUB_PREFETCH_RADIUS,
      priorityCenter: false,
    });
  }
}

// -- Timeline strip (history load progress + drag-to-seek) --------------------
// Tracks decode progress for the active combo. Only the active station+family+tilt
// combo is tracked; sibling products are ignored. Stays visible for navigation.

let _hwComboKey  = '';
let _hwFrameKeys = [];
let _hwTotal     = 0;
let _hwReady     = 0;
let _hwFailed    = 0;
let _hwReadyKeys = new Set();
let _hwFailedKeys = new Set();
let _tlActiveIdx = -1;
let _manualHistoryComboKey = '';
let _tlSettleTimer = null;
let _tlSettleSeq = 0;
let _tlPreviewFrameKey = '';

// DOM refs for the scrubber
const _tlTrackWrap = document.getElementById('tl-track-wrap');
const _tlTrackFill = document.getElementById('tl-track-fill');
const _tlThumb     = document.getElementById('tl-thumb');
const _tlLabels    = document.getElementById('tl-labels');

function _isManualHistoryActive(comboKey = _timelineComboKey()) {
  return !!comboKey && comboKey === _manualHistoryComboKey;
}

function _clearTimelineSettle() {
  if (_tlSettleTimer) {
    clearTimeout(_tlSettleTimer);
    _tlSettleTimer = null;
  }
}

function _pruneQueuedHistoryJobs(comboKey, keepKeys = []) {
  const history = historyMap.get(comboKey) || [];
  if (!history.length) return;
  const historyKeys = new Set(history.map(entry => String(entry?.key || '')).filter(Boolean));
  const keep = new Set(keepKeys.filter(Boolean));
  const currentViewed = viewedKey();
  if (currentViewed) keep.add(currentViewed);
  decodeQueue = decodeQueue.filter(job => {
    const key = String(job?.s3key || '');
    if (!historyKeys.has(key)) return true;
    return keep.has(key);
  });
}

function _historyEntriesNewestToOldest(entries) {
  return Array.isArray(entries) ? entries.slice().reverse() : [];
}

function _queueHistoryNewestToOldest(entries, { priorityCount = RECENT_WISE_PRIORITY_WINDOW } = {}) {
  const ordered = _historyEntriesNewestToOldest(entries);
  if (!ordered.length) return;
  const priorityLimit = Math.max(0, Math.min(ordered.length, Math.round(Number(priorityCount) || 0)));
  for (let i = priorityLimit - 1; i >= 0; i -= 1) {
    const entry = ordered[i];
    const key = String(entry?.key || '');
    if (!key || frameCache.has(key)) continue;
    const { key: _ignoredKey, ...meta } = entry;
    enqueueDecode(key, meta, true);
  }
  for (let i = priorityLimit; i < ordered.length; i += 1) {
    const entry = ordered[i];
    const key = String(entry?.key || '');
    if (!key || frameCache.has(key) || _isDecodeQueued(key)) continue;
    const { key: _ignoredKey, ...meta } = entry;
    enqueueDecode(key, meta, false);
  }
}

function _manualHistoryBurstOrder(entries, targetIndex, includeBackfill = true) {
  if (!Array.isArray(entries) || !entries.length) return [];
  const boundedTarget = Math.max(0, Math.min(targetIndex, entries.length - 1));
  const latestIndex = entries.length - 1;
  const ordered = [];
  const seen = new Set();
  const pushIndex = idx => {
    if (idx < 0 || idx >= entries.length || seen.has(idx)) return;
    const entry = entries[idx];
    const key = String(entry?.key || '');
    if (!key) return;
    seen.add(idx);
    ordered.push(entry);
  };
  pushIndex(latestIndex);
  pushIndex(boundedTarget);
  if (includeBackfill) {
    for (let idx = latestIndex; idx >= 0; idx -= 1) {
      pushIndex(idx);
    }
  } else {
    pushIndex(boundedTarget + 1);
    pushIndex(boundedTarget - 1);
  }
  return ordered;
}

function _queueManualHistoryBurst(entries, targetIndex, { includeBackfill = true, burstMs = MANUAL_HISTORY_BURST_MS } = {}) {
  if (!Array.isArray(entries) || !entries.length) return;
  const ck = _timelineComboKey();
  if (!_isManualHistoryActive(ck)) return;
  const ordered = _manualHistoryBurstOrder(entries, targetIndex, includeBackfill);
  if (!ordered.length) return;
  _refreshManualHistoryBurst(ck, burstMs);
  _pruneQueuedHistoryJobs(ck, ordered.map(entry => entry.key));
  const priorityCount = Math.min(RECENT_WISE_PRIORITY_WINDOW, ordered.length);
  for (let i = priorityCount - 1; i >= 0; i -= 1) {
    const entry = ordered[i];
    const key = String(entry?.key || '');
    if (!key || frameCache.has(key)) continue;
    const { key: _ignoredKey, ...meta } = entry;
    enqueueDecode(key, meta, true);
  }
  for (let i = priorityCount; i < ordered.length; i += 1) {
    const entry = ordered[i];
    const key = String(entry?.key || '');
    if (!key || frameCache.has(key) || _isDecodeQueued(key)) continue;
    const { key: _ignoredKey, ...meta } = entry;
    enqueueDecode(key, meta, false);
  }
}

function _setManualHistoryMode(comboKey, history) {
  const entries = Array.isArray(history) ? history : [];
  if (!comboKey || entries.length < 2) {
    _hideTimeline();
    return;
  }
  if (_processedWiseWarmTimer) {
    clearTimeout(_processedWiseWarmTimer);
    _processedWiseWarmTimer = null;
  }
  _manualHistoryComboKey = comboKey;
  _timelineAnchorComboKey = comboKey;
  _refreshManualHistoryBurst(comboKey);
  _initTimeline(comboKey, entries);
}

function _tlRebuildLabels(history) {
  if (!_tlLabels || !history?.length) return;
  _tlLabels.innerHTML = '';
  const n = history.length;
  for (let i = 0; i < n; i++) {
    const pct = n > 1 ? (i / (n - 1)) * 100 : 50;
    const span = document.createElement('span');
    span.className = 'tl-lbl' + (i === _tlActiveIdx ? ' tl-lbl-active' : '');
    span.dataset.idx = i;
    span.style.left = `${pct}%`;
    _tlLabels.appendChild(span);
  }
  _syncTlTickStates(history);
}

function _initTimeline(comboKey, history) {
  if (!history?.length) return;
  if (_hwComboKey === comboKey && history.length <= _hwTotal) return;
  _hwComboKey  = comboKey;
  _hwFrameKeys = history.map(e => e.key);
  _hwTotal     = _hwFrameKeys.length;
  _hwReady     = 0;
  _hwFailed    = 0;
  _hwReadyKeys = new Set();
  _hwFailedKeys = new Set();
  _tlActiveIdx = -1;
  document.getElementById('control-island')?.classList.add('tl-active');
  _tlRebuildLabels(history);
  _updateTlPosition();
  _syncTlLoadProgress();
}

function _hideTimeline() {
  _clearTimelineSettle();
  _tlSettleSeq += 1;
  document.getElementById('control-island')?.classList.remove('tl-active');
  _hwComboKey  = '';
  _hwFrameKeys = [];
  _hwTotal     = 0;
  _hwReady     = 0;
  _hwFailed    = 0;
  _hwReadyKeys = new Set();
  _hwFailedKeys = new Set();
  _tlActiveIdx = -1;
  _tlPreviewFrameKey = '';
  _clearManualHistoryBurst();
  _manualHistoryComboKey = '';
  _timelineAnchorComboKey = '';
  if (_tlLabels) _tlLabels.innerHTML = '';
}

function _historyIndexForComboSwitch(fromComboKey, toComboKey) {
  const nextHistory = historyMap.get(toComboKey) || [];
  if (!nextHistory.length) return -1;
  const prevHistory = historyMap.get(fromComboKey) || [];
  if (historyIdx < 0 || !prevHistory.length) return nextHistory.length - 1;
  const prevLatestIdx = Math.max(0, prevHistory.length - 1);
  const clampedPrevIdx = Math.max(0, Math.min(historyIdx, prevLatestIdx));
  const offsetFromLatest = prevLatestIdx - clampedPrevIdx;
  return Math.max(0, nextHistory.length - 1 - offsetFromLatest);
}

function _restoreTimelineForCombo(comboKey) {
  const history = historyMap.get(comboKey) || [];
  if (history.length < 2) {
    _hideTimeline();
    historyIdx = -1;
    return false;
  }
  const nextIdx = _historyIndexForComboSwitch(_manualHistoryComboKey || comboKey, comboKey);
  _setManualHistoryMode(comboKey, history);
  historyIdx = Math.max(0, Math.min(nextIdx, history.length - 1));
  updateSlider();
  _updateTlPosition();
  return true;
}

function _updateTlProgress(key, failed = false) {
  if (!_hwFrameKeys.includes(key)) return;
  if (!failed) {
    _hwReadyKeys.add(key);
    _hwFailedKeys.delete(key);
  } else if (!_hwReadyKeys.has(key)) {
    _hwFailedKeys.add(key);
  }
  _syncTlLoadProgress();
}

function _syncTlLoadProgress() {
  if (_hwTotal <= 1 || _stationLoadActive) return;
  const trackedKeys = new Set(_hwFrameKeys);
  _hwReadyKeys = new Set([..._hwReadyKeys].filter(key => trackedKeys.has(key)));
  _hwFailedKeys = new Set([..._hwFailedKeys].filter(key => trackedKeys.has(key) && !_hwReadyKeys.has(key)));
  for (const key of _hwFrameKeys) {
    if (frameCache.has(key)) _hwReadyKeys.add(key);
  }
  _hwFailedKeys = new Set([..._hwFailedKeys].filter(key => !_hwReadyKeys.has(key)));
  _hwReady = _hwReadyKeys.size;
  _hwFailed = _hwFailedKeys.size;
  const done = _hwReady + _hwFailed;
  const pending = Math.max(0, _hwTotal - done);
  const controlIsland = document.getElementById('control-island');
  const barVisible = controlIsland?.classList.contains('bar-loading') === true;
  if (pending <= 0) {
    if (barVisible) {
      _setLoadBar(100);
      _loadBarHideTimer = setTimeout(() => _setLoadBar(null), 600);
    }
    return;
  }
  if (done > 0 || barVisible) {
    _setLoadBar(Math.round((done / _hwTotal) * 100));
  }
  _syncTlTickStates();
}

function _syncTlTickStates(history = null) {
  if (!_tlLabels) return;
  const entries = Array.isArray(history) ? history : (historyMap.get(_timelineComboKey()) || []);
  if (!entries.length) return;
  const activeIdx = _timelineCurrentIndex(entries);
  for (const lbl of _tlLabels.children) {
    const idx = Number(lbl.dataset.idx);
    const key = String(entries[idx]?.key || '');
    const loaded = !!key && frameCache.has(key);
    const failed = !!key && _hwFailedKeys.has(key) && !loaded;
    lbl.className = [
      'tl-lbl',
      loaded ? 'tl-lbl-loaded' : 'tl-lbl-pending',
      failed ? 'tl-lbl-failed' : '',
      idx === activeIdx ? 'tl-lbl-active' : '',
    ].filter(Boolean).join(' ');
  }
}

function _updateTlPosition() {
  const ck = _timelineComboKey();
  const history = historyMap.get(ck);
  if (!history?.length || !_hwFrameKeys.length) return;
  const newIdx = _timelineCurrentIndex(history);
  const n = history.length;
  const pct = n > 1 ? (newIdx / (n - 1)) * 100 : 0;

  if (_tlThumb)     _tlThumb.style.left = `${pct}%`;
  if (_tlTrackFill) _tlTrackFill.style.width = `${pct}%`;

  _syncTlTickStates(history);
  _tlActiveIdx = newIdx;
}

function _setHistoryFrameLabelForKey(key) {
  const ts = parseKeyTimestampMs(key);
  const timeStr = Number.isFinite(ts) ? _fmtLocalTime(ts) : '--:--:-- --';
  setFrameLabel(timeStr, 'history');
  _setAlertsPlaybackTimeForKey(key);
}

function _disposeLayerFromMap(mapObj, layer) {
  if (!layer) return;
  try { layer.clearFrame(); } catch (_) {}
  try {
    if (mapObj?.getLayer?.(layer.id)) mapObj.removeLayer(layer.id);
  } catch (_) {}
}

function _disposePrimaryLayerPoolForCombo(comboKey) {
  const layer = layerPool.get(comboKey);
  if (!layer) return;
  if (radarLayer === layer) radarLayer = null;
  if (radarLayerSweep === layer) radarLayerSweep = null;
  if (sweepLayer === layer) sweepLayer = null;
  _disposeLayerFromMap(map, layer);
  layerPool.delete(comboKey);
  layerPoolLastUsed.delete(comboKey);
}

function _disposePaneLayerPool(pane) {
  if (!pane?.layerPool) return;
  for (const layer of pane.layerPool.values()) {
    if (pane.radarLayer === layer) pane.radarLayer = null;
    if (pane.sweepLayer === layer) pane.sweepLayer = null;
    _disposeLayerFromMap(pane.map, layer);
  }
  pane.layerPool.clear();
}

function _renderHistoryPlaceholderAt(idx, history) {
  if (idx < 0 || idx >= history.length) return false;
  const { key } = history[idx];
  if (frameCache.has(key)) {
    if (_tlPreviewFrameKey !== key || !_isFrameGpuReadyForKey(key)) {
      showFrame(key, { skipPrefetch: true, immediateUpload: true });
      _tlPreviewFrameKey = key;
    }
    return true;
  }
  for (let dist = 1; dist < history.length; dist++) {
    const lo = idx - dist;
    const hi = idx + dist;
    if (lo >= 0 && frameCache.has(history[lo].key)) {
      const fallbackKey = history[lo].key;
      if (_tlPreviewFrameKey !== fallbackKey) {
        showFrame(fallbackKey, { skipPrefetch: true });
        _tlPreviewFrameKey = fallbackKey;
      }
      return true;
    }
    if (hi < history.length && frameCache.has(history[hi].key)) {
      const fallbackKey = history[hi].key;
      if (_tlPreviewFrameKey !== fallbackKey) {
        showFrame(fallbackKey, { skipPrefetch: true });
        _tlPreviewFrameKey = fallbackKey;
      }
      return true;
    }
  }
  return false;
}

function _settleTimelineTarget(idx, history, settleSeq) {
  if (settleSeq !== _tlSettleSeq) return;
  if (!Array.isArray(history) || idx < 0 || idx >= history.length) return;
  const ck = _timelineComboKey();
  if (!_isManualHistoryActive(ck)) return;
  const target = history[idx];
  if (!target?.key) return;
  const neighborKeys = [];
  if (idx > 0) neighborKeys.push(history[idx - 1]?.key);
  if (idx < history.length - 1) neighborKeys.push(history[idx + 1]?.key);
  _pruneQueuedHistoryJobs(ck, [target.key, ...neighborKeys]);
  _queueManualHistoryBurst(history, idx, {
    includeBackfill: true,
    burstMs: MANUAL_HISTORY_BURST_MS,
  });
  if (multiPaneCount > 1) {
    if (!_tryRenderCachedSyncedMultiPaneHistoryFrame(idx, history, { immediateUpload: true })) {
      _queueHistoryRender(idx, history, { priority: true });
    }
  } else {
    _showHistoryFrameAt(idx, history, { fetchExact: true });
  }
  _prefetchVisiblePaneHistoryNeighborhood(idx, 0);
}

function _scheduleTimelineSettle(idx, history, immediate = false) {
  _clearTimelineSettle();
  const settleSeq = ++_tlSettleSeq;
  const run = () => {
    _tlSettleTimer = null;
    _settleTimelineTarget(idx, history, settleSeq);
  };
  if (immediate) run();
  else _tlSettleTimer = setTimeout(run, TIMELINE_SETTLE_DEBOUNCE_MS);
}

function _tlSeekFromPointer(clientX) {
  if (!_tlTrackWrap || !_hwFrameKeys.length) return;
  const rect = _tlTrackWrap.getBoundingClientRect();
  const frac = Math.max(0, Math.min(1, (clientX - rect.left) / rect.width));
  const ck = _timelineComboKey();
  const history = historyMap.get(ck) || [];
  if (!history.length) return;
  const newIdx = Math.round(frac * (history.length - 1));
  if (newIdx === historyIdx) {
    if (!frameCache.has(history[newIdx]?.key)) _scheduleTimelineSettle(newIdx, history, false);
    return;
  }
  cancelSweep();
  paneInteractionUntilMs = Date.now() + 1800;
  historyIdx = newIdx;
  const target = history[historyIdx];
  _setHistoryFrameLabelForKey(target?.key);
  if (multiPaneCount > 1) {
    if (!_tryRenderCachedSyncedMultiPaneHistoryFrame(historyIdx, history, { immediateUpload: true })) {
      _queueHistoryRender(historyIdx, history, { priority: true });
    }
  } else {
    _renderHistoryPlaceholderAt(historyIdx, history);
  }
  _updateTlPosition();
  _scheduleTimelineSettle(historyIdx, history, false);
}

if (_tlTrackWrap) {
  _tlTrackWrap.addEventListener('mousedown', e => {
    e.preventDefault();
    stopPlay();
    _tlDragging = true;
    document.getElementById('tl-strip')?.classList.add('tl-dragging');
    _tlSeekFromPointer(e.clientX);
  });
  _tlTrackWrap.addEventListener('touchstart', e => {
    stopPlay();
    _tlDragging = true;
    document.getElementById('tl-strip')?.classList.add('tl-dragging');
    _tlSeekFromPointer(e.touches[0].clientX);
  }, { passive: true });
}
document.addEventListener('mousemove', e => {
  if (_tlDragging) _tlSeekFromPointer(e.clientX);
});
document.addEventListener('mouseup', () => {
  if (_tlDragging) {
    const ck = _timelineComboKey();
    const history = historyMap.get(ck) || [];
    if (historyIdx >= 0 && historyIdx < history.length) {
      _scheduleTimelineSettle(historyIdx, history, true);
    }
  }
  _tlDragging = false;
  _tlPreviewFrameKey = '';
  document.getElementById('tl-strip')?.classList.remove('tl-dragging');
});
document.addEventListener('touchmove', e => {
  if (_tlDragging) _tlSeekFromPointer(e.touches[0].clientX);
}, { passive: true });
document.addEventListener('touchend', () => {
  if (_tlDragging) {
    const ck = _timelineComboKey();
    const history = historyMap.get(ck) || [];
    if (historyIdx >= 0 && historyIdx < history.length) {
      _scheduleTimelineSettle(historyIdx, history, true);
    }
  }
  _tlDragging = false;
  _tlPreviewFrameKey = '';
  document.getElementById('tl-strip')?.classList.remove('tl-dragging');
});

// Warm the full active-combo history into frameCache so arrow-key steps hit cache.
// Uses spiral order (center-out from historyIdx). Safe to call any time; skips
// already-cached/queued frames. Callers are responsible for burst/timeline setup.
function _preloadActiveComboHistory() {
  if (!activeStation || levelII || isLocalRadarMode()) return;
  const ck = _timelineComboKey();
  const history = historyMap.get(ck);
  if (!history?.length) return;
  const center = (historyIdx >= 0 && historyIdx < history.length)
    ? historyIdx
    : history.length - 1;
  _enqueueHistoryNeighborhood(history, center, {
    direction: 0,
    radius: history.length,
    priorityCenter: true,
  });
}

function pruneFrameCache() {
  pruneFrameCacheBytes();
  const limit = _frameCacheMax();
  if (frameCache.size <= limit) return;
  const protected_ = new Set();
  const ck = _timelineComboKey();
  (historyMap.get(ck) || []).forEach(f => protected_.add(f.key));
  for (const key of _collectVisiblePaneHistoryProtectionKeys()) protected_.add(key);
  if (sweepNewKey) protected_.add(sweepNewKey);
  const toEvict = [];
  for (const key of frameCache.keys()) {
    if (!protected_.has(key)) toEvict.push(key);
    if (toEvict.length >= frameCache.size - limit) break;
  }
  toEvict.forEach(key => frameCache.delete(key));
}

// Start up to currentDecodeWorkerLimit() concurrent decode workers. Each worker
// pulls jobs from the shared decodeQueue independently.
function startDecodeWorkers() {
  const needed = Math.min(currentDecodeWorkerLimit() - decodeWorkerCount, decodeQueue.length);
  for (let i = 0; i < needed; i++) {
    decodeWorkerCount++;
    _runOneDecodeWorker();
  }
}

async function _runOneDecodeWorker() {
  while (decodeQueue.length > 0) {
    const job = decodeQueue.shift();
    if (!job) break;
    const isL2 = job.s3key.startsWith('L2:');
    if (isL2 && job.meta?.l2Preload) {
      const activeLatest = comboLatestKey.get(activeCacheKey());
      const activeSig = _l2ScanSigFromKey(activeLatest);
      const jobSig = _l2ScanSigFromKey(job.s3key);
      if (activeSig && jobSig && activeSig !== jobSig) {
        continue;
      }
      if (decodeQueue.some(q => q.priority && String(q.s3key).startsWith('L2:'))) {
        decodeQueue.push(job);
        await new Promise(r => setTimeout(r, 10));
        continue;
      }
    }
    try {
      _trackDecodeStarted(job.s3key);
      const data = await backendDecode(job.s3key, {
        refresh: !!job.meta?.refreshL2,
        priority: !!job.priority,
        allowDirect: !!job.meta?.confirmed,
      });
      if (isL2) _l2RetryCooldowns.delete(job.s3key);
      if (isL2 && data.l2_tilts) updateL2TiltSelect(data.l2_tilts);
      frameCache.set(job.s3key, data);
      _settleDecodedFrameWaiters(job.s3key, null, data);
      pruneFrameCache();
      _trackFrameDecoded(job.s3key);
      _updateTlProgress(job.s3key);

      if (isL2 && job.meta?.activateL2Latest && job.meta?.comboKey && job.meta?.latestEntry) {
        const comboKey = String(job.meta.comboKey);
        if (comboKey === activeCacheKey()) {
          const entries = Array.isArray(job.meta?.l2Entries) && job.meta.l2Entries.length
            ? job.meta.l2Entries
            : [job.meta.latestEntry];
          _setL2HistoryEntries(comboKey, entries, job.s3key);
        }
      }
      if (!isL2 && job.meta?.activateL3Latest && job.meta?.comboKey) {
        const comboKey = String(job.meta.comboKey);
        if (comboKey === activeCacheKey()) {
          const latestEntry = job.meta?.latestEntry?.key
            ? job.meta.latestEntry
            : { key: job.s3key };
          _setL3HistoryEntries(comboKey, [...(historyMap.get(comboKey) || []), latestEntry], job.s3key);
        }
      }
      if (!isL2 && job.meta?.predictedWarm && job.meta?.comboKey) {
        const comboKey = String(job.meta.comboKey);
        const latestEntry = job.meta?.latestEntry?.key
          ? job.meta.latestEntry
          : { key: job.s3key };
        const existing = historyMap.get(comboKey) || [];
        const withoutDup = existing.filter(item => item?.key !== job.s3key);
        const nextHistory = [...withoutDup, latestEntry].sort((a, b) => {
          const at = _parseProcessedWiseFileTimestampMs(a.fileName || a.filename || a.key) || 0;
          const bt = _parseProcessedWiseFileTimestampMs(b.fileName || b.filename || b.key) || 0;
          return at - bt;
        });
        _setL3HistoryEntries(comboKey, nextHistory, job.s3key);
        comboLatestKey.set(comboKey, job.s3key);
      }

      if (job.s3key === sweepPendingKey) {
        const ck = String(job.meta?.comboKey || activeCacheKey());
        sweepPendingKey = null;
        if (_canLiveSweepNow(ck, job.s3key)) {
          beginSweepReveal(data, job.s3key, ck);
        } else if (_isViewingLiveLatest(ck) && activeStation && job.s3key === viewedKey() && !sweepActive) {
          showFrame(job.s3key);
        }
      } else if (activeStation && job.s3key === viewedKey() && !sweepActive) {
        showFrame(job.s3key);
      }
    } catch (e) {
      const errMsg = e?.message || String(e);
      const expectedL2Retry = isL2 && _isRetryableL2ErrorMessage(errMsg);
      const isNotFound = e?.status === 404 || e?.isNotFound || /HTTP 404/.test(errMsg);
      if (isNotFound && String(job.s3key || '').startsWith('WISE:')) {
        _markWiseNotFound(job.s3key);
      }
      if (expectedL2Retry) _markL2RetryCooldown(job.s3key);
      _settleDecodedFrameWaiters(job.s3key, e);
      _trackFrameDecoded(job.s3key);
      _updateTlProgress(job.s3key, true);
      let usedFallback = false;
      if (isL2 && activeStation && job.s3key === viewedKey()) {
        usedFallback = _fallbackActiveL2Frame(job.s3key, 'Waiting for complete L2 scan');
        if (usedFallback) {
          continue;
        }
      }
      if (!expectedL2Retry && !isNotFound) {
        console.error('[decode] failed:', job.s3key, '—', errMsg);
      }
      if (activeStation && job.s3key === viewedKey()) {
        if (expectedL2Retry) {
          setFrameLabel('Waiting for complete L2 scan', 'loading');
        } else if (isNotFound) {
          setFrameLabel('Waiting for data', 'loading');
        } else {
          setFrameLabel(e.message?.slice(0, 50) || 'Error', 'error');
        }
      }
    }
    // Give the event loop a chance to render the map between frames.
    // Priority frames yield immediately; background frames pause briefly so
    // plotting stays responsive without dragging out recent-frame downloads.
    await new Promise(r => setTimeout(r, job.priority ? 0 : DECODE_BACKGROUND_YIELD_MS));
  }
  decodeWorkerCount--;
  // When the last worker exits, schedule the toast drain check.
  if (decodeWorkerCount === 0 && _stationLoadActive) _scheduleToastDrain();
}

// -- Frame display -------------------------------------------------------------

// After a frame renders, wait 300 ms then quietly prefetch the frames on either
// side so scrubbing feels instant without hammering the backend at load time.
let _prefetchTimer = null;
function scheduleNeighborPrefetch() {
  if (!levelII && historyFrameLimitForCombo(_timelineComboKey()) <= 1) return;
  if (_isL2PathForFamily(activeFamily)) return; // L2 decodes are expensive — skip prefetch
  clearTimeout(_prefetchTimer);
  _prefetchTimer = setTimeout(() => {
    if (_tlDragging) return;
    const ck = _timelineComboKey();
    const history = historyMap.get(ck) || [];
    if (!history.length) return;
    const idx = historyIdx >= 0 ? historyIdx : history.length - 1;
    const offsets = _isManualHistoryActive(ck) ? [-1, 1] : [-1, 1, -2, 2, -3, 3];
    for (const offset of offsets) {
      const i = idx + offset;
      if (i < 0 || i >= history.length) continue;
      const { key, ...meta } = history[i];
      if (!frameCache.has(key)) enqueueDecode(key, meta, false);
    }
  }, 300);
}

function showFrame(s3key, opts = {}) {
  const data = frameCache.get(s3key);
  if (!data) return;
  if (
    String(s3key || '').startsWith('WISE:') &&
    data?.data_smoothing != null &&
    Boolean(data.data_smoothing) !== (radarDataSmoothing === true) &&
    opts?.skipSmoothingStateCheck !== true
  ) {
    _scheduleRadarDataSmoothingRebuild(0);
  }
  if (String(s3key || '').startsWith('L2:')) _setActiveL2AvailableProducts(data?.l2_available_products);
  else _setActiveL2AvailableProducts(null);
  applyRadarFrame(data, s3key, () => showFrameMeta(s3key, data), {
    immediateUpload: opts?.immediateUpload === true,
  });
  applyFilter();
  updateInspectorReadout();
  if (_stationLoadActive) {
    const vk = viewedKey();
    if (s3key === vk) _hideDecodeToast();
  }
  if (opts?.skipPrefetch !== true && !isPlaying) scheduleNeighborPrefetch();
}

// Update UI info (time/elev/code/label) for a given key+data without re-rendering.
// Called both from showFrame() and from completeSweep() after the sweep finishes.
function showFrameMeta(s3key, data) {
  const scanTimeMs = _parseFrameScanTimeMs(data?.scan_time, s3key);
  const timeStr = Number.isFinite(scanTimeMs) ? _fmtLocalTime(scanTimeMs) : '--:--:-- --';
  _setPaneFrameTime(1, s3key, data);
  document.getElementById('info-time').textContent = timeStr;
  document.getElementById('info-elev').textContent =
    data.elevation != null ? `${data.elevation.toFixed(1)}°` : '--';
  document.getElementById('info-code').textContent = data.product_code ?? '--';
  if (isLocalRadarMode()) {
    setFrameLabel(`${timeStr}  LOCAL`, 'ok');
    return;
  }
  const ck = _timelineComboKey();
  const history = historyMap.get(ck) || [];
  if (_tlDragging && _isManualHistoryActive(ck) && historyIdx >= 0 && historyIdx < history.length) {
    _setHistoryFrameLabelForKey(history[historyIdx]?.key);
    return;
  }
  const isLive = historyIdx < 0 || history.length === 0 || historyIdx >= history.length - 1;
  if (isLive) _setAlertsPlaybackTime(NaN);
  else _setAlertsPlaybackTime(Number.isFinite(scanTimeMs) ? scanTimeMs : parseKeyTimestampMs(s3key), history);
  setFrameLabel(isLive ? `${timeStr}  LIVE` : timeStr, isLive ? 'ok' : 'history');
}

function setFrameLabel(text, cls) {
  const el = document.getElementById('frame-label');
  if (el) { el.textContent = text; el.className = cls || ''; }
}

function _flashFrameLabel(text, cls = 'live', durationMs = 1600) {
  const el = document.getElementById('frame-label');
  if (!el) return;
  clearTimeout(boardCopyLabelTimer);
  const previousText = el.textContent;
  const previousClass = el.className;
  setFrameLabel(text, cls);
  boardCopyLabelTimer = setTimeout(() => {
    boardCopyLabelTimer = null;
    if (el.textContent === text && el.className === (cls || '')) {
      setFrameLabel(previousText, previousClass);
    }
  }, Math.max(250, Number(durationMs) || 1600));
}

function showCachedActiveCombo() {
  const ck = activeCacheKey();
  const pooledLayer = layerPool.get(ck);
  let history = historyMap.get(ck) || [];
  const targetFrames = historyFrameLimitForCombo(ck);
  if (!levelII && history.length > targetFrames) {
    history = history.slice(-targetFrames);
    historyMap.set(ck, history);
  }
  if (history.length) {
    const keepHistoryIdx = _isManualHistoryActive(_timelineComboKey()) && ck === _timelineComboKey() && historyIdx >= 0 && historyIdx < history.length;
    historyIdx = keepHistoryIdx ? historyIdx : (history.length - 1);
    updateSlider();
    const { key: curKey, ...curMeta } = history[historyIdx];
    const pooledData = pooledLayer?._loadedData || null;
    if (!frameCache.has(curKey) && pooledData) {
      frameCache.set(curKey, pooledData);
    }
    if (frameCache.has(curKey) && !sweepActive) {
      showFrame(curKey);
    } else {
      _clearVisiblePrimaryForPendingCombo('cached-combo-pending');
      setFrameLabel('Loading…', 'loading');
      enqueueDecode(curKey, curMeta, true);
    }
    if (levelII) {
      history.forEach((entry, idx) => {
        if (idx === historyIdx) return;
        const { key, ...meta } = entry;
        if (!frameCache.has(key)) enqueueDecode(key, meta, false);
      });
    }
    _syncLoadMoreBtn();
    return true;
  }

  const latestKey = comboLatestKey.get(ck);
  if (!latestKey) return false;
  historyIdx = -1;
  updateSlider();
  const pooledData = pooledLayer?._loadedData || null;
  if (!frameCache.has(latestKey) && pooledData) {
    frameCache.set(latestKey, pooledData);
  }
  if (frameCache.has(latestKey) && !sweepActive) {
    showFrame(latestKey);
  } else {
    _clearVisiblePrimaryForPendingCombo('cached-latest-pending');
    setFrameLabel('Loading…', 'loading');
    enqueueDecode(latestKey, {}, true);
  }
  _syncLoadMoreBtn();
  return true;
}

function applyFilter() {
  if (radarLayer) {
    const minVal = _paneMinValue(displayedPrimaryFamily || activeFamily);
    radarLayer.setMinValue(minVal);
    radarLayerSweep?.setMinValue(minVal);
  }
  secondaryPaneMaps.forEach(pane => {
    if (!pane.radarLayer) return;
    pane.radarLayer.setMinValue(_paneMinValue(pane.family));
  });
}

// -- Loading -------------------------------------------------------------------
async function loadHistory(stationId, family, tilt, opts = {}) {
  if (stationId !== activeStation || family !== activeFamily || tilt !== activeTilt) return;
  const ck = `${stationId}:${family}:${tilt}`;
  const preferCache = opts.preferCache !== false;
  const currentOnly = opts.currentOnly === true;
  const targetFrames = historyFrameLimitForSelection(stationId, family, tilt);
  const seq = ++_l3LoadSeq;

  try {
    const cachedEntries = historyMap.get(ck) || [];
    if (preferCache && cachedEntries.length) {
      historyIdx = cachedEntries.length - 1;
      updateSlider();
      const { key: curKey, ...curMeta } = cachedEntries[historyIdx];
      if (frameCache.has(curKey) && !sweepActive) showFrame(curKey);
      else enqueueDecode(curKey, curMeta, true);
      if (cachedEntries.length < targetFrames) void _backfillHistory(stationId, family, tilt, seq);
      _syncLoadMoreBtn();
      return;
    }

    // -- Phase 1: find and show the single latest frame immediately ------------
    _trackResolveStarted();
    let latestMeta = currentOnly
      ? await findLatestKeyCurrentOnly(stationId, { family, tilt })
      : await findLatestKey(stationId, { family, tilt });
    if (!latestMeta?.key && currentOnly) {
      try {
        latestMeta = await findLatestKey(stationId, { family, tilt });
      } catch (_) {
        latestMeta = null;
      }
    }
    if (!latestMeta?.key) {
      if (seq === _l3LoadSeq
        && stationId === activeStation
        && family === activeFamily
        && tilt === activeTilt) {
        _hideDecodeToast();
      }
      return;
    }
    if (seq !== _l3LoadSeq) return;
    if (stationId !== activeStation || family !== activeFamily || tilt !== activeTilt) return;

    _setL3HistoryEntries(ck, [latestMeta], latestMeta.key);
    const history = historyMap.get(ck) || [latestMeta];
    const curKey = history[historyIdx].key;
    if (frameCache.has(curKey) && !sweepActive) showFrame(curKey);
    else enqueueDecode(curKey, latestMeta, true);
    if (targetFrames > 1) void _backfillHistory(stationId, family, tilt, seq);
    _syncLoadMoreBtn();
    scheduleStationProductPreload(stationId, family, tilt);

  } catch (_) {
    if (seq === _l3LoadSeq
      && stationId === activeStation
      && family === activeFamily
      && tilt === activeTilt) {
      _hideDecodeToast();
    }
  }
}

async function pollActiveL3Latest(stationId) {
  if (stationId !== activeStation || _isL2PathForFamily(activeFamily)) return;
  if (_processedWiseDirListPollRunning) return;

  const family = activeFamily;
  const tilt = activeTilt;
  const ck = `${stationId}:${family}:${tilt}`;
  if (_isManualHistoryActive(ck)) return;

  _processedWiseDirListPollRunning = true;
  try {
    const latestMeta = await findLatestKeyCurrentOnly(stationId, { family, tilt, forceRefresh: true });
    if (!latestMeta?.key) return;

    // User switched while this was running
    if (stationId !== activeStation || family !== activeFamily || tilt !== activeTilt) return;
    scheduleStationProductPreload(stationId, family, tilt);
    const prevKey = comboLatestKey.get(ck);
    const prevTs = parseKeyTimestampMs(prevKey || '');
    const nextTs = parseKeyTimestampMs(latestMeta.key);

    // No new frame -> do nothing
    if (prevKey === latestMeta.key) return;
    if (Number.isFinite(prevTs) && Number.isFinite(nextTs) && nextTs < prevTs) return;
    // If already decoded, show it immediately
    if (frameCache.has(latestMeta.key)) {
      _setL3HistoryEntries(ck, [...(historyMap.get(ck) || []), latestMeta], latestMeta.key);
      if (_canLiveSweepNow(ck, latestMeta.key)) {
        const cachedData = frameCache.get(latestMeta.key);
        if (cachedData) beginSweepReveal(cachedData, latestMeta.key, ck);
        else showFrame(latestMeta.key);
      } else if (_isViewingLiveLatest(ck) && !sweepActive) {
        showFrame(latestMeta.key);
      }
      return;
    }

    // New frame -> download/decode only this one
    if (_canStartIncomingSweep(ck, latestMeta.key) && prevKey) {
      sweepPendingKey = latestMeta.key;
    }
    enqueueDecode(latestMeta.key, { ...latestMeta, activateL3Latest: true, comboKey: ck, latestEntry: latestMeta }, true);
  } catch (_) {
  } finally {
    _processedWiseDirListPollRunning = false;
  }
}

// Fetch older history frames in the background and prepend them to historyMap
// one at a time so each decoded frame appears in the slider immediately.
async function _backfillHistory(stationId, family, tilt, seq) {
  const targetFrames = historyFrameLimitForSelection(stationId, family, tilt);
  if (targetFrames <= 1) return;
  if (levelII) return;
  // Brief pause so the priority frame can start decoding first
  await new Promise(r => setTimeout(r, 120));
  if (seq !== _l3LoadSeq) return;
  if (stationId !== activeStation || family !== activeFamily || tilt !== activeTilt) return;

  const ck = `${stationId}:${family}:${tilt}`;
  const currentHistory = historyMap.get(ck) || [];
  if (currentHistory.length >= targetFrames) return;

  let allKeys;
  try {
    allKeys = await findRecentKeys(stationId, family, tilt, targetFrames);
  } catch (_) { return; }

  if (seq !== _l3LoadSeq) return;
  if (stationId !== activeStation || family !== activeFamily || tilt !== activeTilt) return;

  const refreshed = historyMap.get(ck) || [];
  const knownKeys = new Set(refreshed.map(e => e.key));
  const olderKeys = allKeys.filter(k => !knownKeys.has(k.key));
  if (!olderKeys.length) return;

  // Prepend older frames so history runs oldest?newest
  const newHistory = [...olderKeys, ...refreshed].slice(-targetFrames);
  historyMap.set(ck, newHistory);

  // Keep the user on the same frame they were viewing
  const viewedKey_ = refreshed[historyIdx >= 0 ? Math.min(historyIdx, refreshed.length - 1) : refreshed.length - 1]?.key;
  if (viewedKey_) {
    const newIdx = newHistory.findIndex(e => e.key === viewedKey_);
    historyIdx = newIdx >= 0 ? newIdx : newHistory.length - 1;
  }
  updateSlider();
  startFrameTracking(newHistory.map(e => e.key));
  _setManualHistoryMode(ck, newHistory);
  _scheduleTimelineSettle(Math.max(0, historyIdx), newHistory, true);
  _syncLoadMoreBtn();
}

function stopPolling() {
  if (pollTimer !== null) { clearInterval(pollTimer); pollTimer = null; }
  stopActiveWiseProbeLoop();
  _weatherWiseRelayClose(false);
}

async function loadAll(stationId, isInitial = false) {
  if (isDerivedRadarProduct(activeFamily)) {
    void _loadPtdsFrame(stationId, activeTilt, _l3LoadSeq);
    return;
  }
  if (_isL2PathForFamily(activeFamily)) {
    if (isInitial) {
      await loadL2History(stationId, activeFamily, parseInt(activeTilt) || 0, {
        preferCache: false,
        refreshScans: true,
      });
    } else {
      await pollActiveL2Latest(stationId);
    }
  } else {
    if (isInitial) {
      // First load: show only the newest frame for the active combo.
      await loadHistory(stationId, activeFamily, activeTilt, { preferCache: false, currentOnly: true });
    } else {
      // Poll only the active combo for a newer frame.
      await pollActiveL3Latest(stationId);
    }
  }
}

async function _warmWiseRawBytes(entries, concurrency = 6) {
  const queue = entries.filter(e => {
    const key = e?.key;
    if (!key || !String(key).startsWith('WISE:')) return false;
    if (_processedWisePrefetchBytes.has(key)) return false;
    if (_processedWiseRawBytesCache.has(key)) return false;
    if (frameCache.has(key)) return false;
    return true;
  });
  if (!queue.length) return;
  let cursor = 0;
  const run = async () => {
    while (cursor < queue.length) {
      const entry = queue[cursor++];
      const key = entry?.key;
      if (!key) continue;
      const parts = String(key).split(':');
      const sid = canonicalStationId(parts[1] || '');
      const fam = String(parts[2] || '').trim().toUpperCase();
      const t = normalizeTilt(parts[3] || '0.5');
      const fn = decodeURIComponent(parts.slice(4).join(':') || '');
      if (!sid || !fam || !fn) continue;
      const url = _processedWiseFileUrl(sid, fam, t, fn);
      if (_isWiseNotFoundCoolingDown(key) || _isWiseNotFoundCoolingDown(url)) continue;
      if (_processedWiseRawBytesCache.has(key) || _processedWisePrefetchBytes.has(key)) continue;
      try {
        let fetchP = _pendingWiseFetches.get(url);
        if (!fetchP) {
          fetchP = _fetchBytesViaTauri(url, {
            timeoutMs: 15000,
            preferDirect: false,
          }).finally(() => _pendingWiseFetches.delete(url));
          _pendingWiseFetches.set(url, fetchP);
        }
        const bytes = await fetchP;
        if (bytes instanceof Uint8Array && bytes.byteLength >= 4) {
          _storeProcessedWiseRawBytes(key, bytes);
        }
      } catch (_) {}
    }
  };
  const workers = [];
  for (let i = 0; i < Math.min(concurrency, queue.length); i++) {
    workers.push(run());
  }
  await Promise.allSettled(workers);
}

async function loadRecentWiseFrames(stationId = activeStation, family = activeFamily, tilt = activeTilt, count = RECENT_WISE_FRAME_COUNT, options = {}) {
  const onProgress = typeof options?.onProgress === 'function' ? options.onProgress : null;
  const updateFrameLabel = options?.updateFrameLabel !== false;
  const shouldActivate = options?.activate !== false;
  const queueOnly = options?.queueOnly === true;
  const requestSeq = Number.isFinite(Number(options?.requestSeq)) ? Number(options.requestSeq) : null;
  const emitProgress = payload => {
    if (typeof onProgress !== 'function') return;
    try { onProgress(payload); } catch (_) {}
  };
  if (!_canUseProcessedWise(stationId, family, tilt)) {
    throw new Error('Recent frame downloads are only available for processed WeatherWise products.');
  }
  const sid = canonicalStationId(stationId);
  const normalizedFamily = String(family || '').toUpperCase();
  const normalizedTilt = _normalizeProcessedWiseTilt(normalizedFamily, tilt);
  const ck = `${sid}:${normalizedFamily}:${normalizedTilt}`;
  const wanted = Math.max(2, Math.min(MAX_HISTORY_FRAMES, Math.round(Number(count) || RECENT_WISE_FRAME_COUNT)));
  if (shouldActivate) _refreshManualHistoryBurst(ck, MANUAL_HISTORY_BURST_MS);
  emitProgress({ phase: 'resolving', requested: wanted, completed: 0, total: wanted, failed: 0 });
  comboHistoryTargetFrames.set(ck, wanted);
  const entries = await _fetchRecentProcessedWiseMetas(sid, normalizedFamily, normalizedTilt, wanted);
  if (requestSeq !== null && requestSeq !== recentFramesLoadSeq) return [];
  if (!entries.length) {
    throw new Error('No recent processed frames were found.');
  }
  _setL3HistoryEntries(ck, entries, entries[entries.length - 1].key);
  const history = historyMap.get(ck) || entries;
  const isActiveCombo = activeStation === sid && activeFamily === normalizedFamily && activeTilt === normalizedTilt && activeCacheKey() === ck;
  if (isActiveCombo) _setManualHistoryMode(ck, history);
  void _warmWiseRawBytes(_historyEntriesNewestToOldest(entries), 8).catch(() => {});
  const latestIndex = Math.max(0, history.length - 1);
  const targetIndex = Math.max(0, Math.min(_targetHistoryIndexForEntries(history), latestIndex));
  const targetEntry = history[targetIndex];
  const latestEntry = history[latestIndex] || targetEntry;
  if (shouldActivate) {
    _refreshManualHistoryBurst(ck, MANUAL_HISTORY_BURST_MS);
    _pruneQueuedHistoryJobs(ck, _historyEntriesNewestToOldest(history).map(entry => entry.key));
    _queueHistoryNewestToOldest(history, { priorityCount: Math.max(RECENT_WISE_PRIORITY_WINDOW, PLAYBACK_PREFETCH_WINDOW + 1) });
  } else {
    _pruneQueuedHistoryJobs(ck, latestEntry?.key ? [latestEntry.key] : []);
  }
  emitProgress({
    phase: 'downloading',
    requested: wanted,
    completed: 0,
    total: history.length,
    failed: 0,
  });
  try {
    const decodeEntry = shouldActivate ? targetEntry : latestEntry;
    const decodePriority = shouldActivate;
    if (queueOnly) {
      if (decodeEntry?.key && !frameCache.has(decodeEntry.key) && !_isDecodeQueued(decodeEntry.key)) {
        enqueueDecode(decodeEntry.key, decodeEntry, decodePriority);
      }
    } else {
      await ensureFrameDecoded(decodeEntry.key, decodeEntry, decodePriority);
    }
  } catch (err) {
    if (!shouldActivate) _pruneDecodedFramesForCombo(ck, latestEntry?.key ? [latestEntry.key] : []);
    emitProgress({
      phase: 'complete-with-errors',
      requested: wanted,
      completed: 0,
      total: history.length,
      failed: 1,
    });
    throw err;
  }
  if (requestSeq !== null && requestSeq !== recentFramesLoadSeq) return entries;
  if (!shouldActivate) {
    _pruneDecodedFramesForCombo(ck, latestEntry?.key ? [latestEntry.key] : []);
  } else if (activeCacheKey() === ck && !sweepActive && frameCache.has(targetEntry.key)) {
    showFrame(targetEntry.key, { skipPrefetch: true, immediateUpload: true });
  }
  _syncLoadMoreBtn();
  emitProgress({
    phase: 'complete',
    requested: wanted,
    completed: history.length,
    total: history.length,
    failed: 0,
  });
  if (isActiveCombo) _scheduleTimelineSettle(targetIndex, history, true);
  if (shouldActivate && updateFrameLabel) setFrameLabel(`Recent frames: ${history.length}`, 'live');
  return entries;
}

async function loadRecentWiseFramesForVisiblePanes(stationId = activeStation, count = RECENT_WISE_FRAME_COUNT, options = {}) {
  const sid = canonicalStationId(stationId);
  const selections = _visibleProcessedWiseSelections(sid);
  if (!selections.length) {
    throw new Error('Recent processed frames are unavailable for the visible panes.');
  }

  const requested = Math.max(2, Math.min(MAX_HISTORY_FRAMES, Math.round(Number(count) || RECENT_WISE_FRAME_COUNT)));
  const primarySelection = selections.find(selection => selection.isPrimary) || selections[0];
  const onProgress = typeof options?.onProgress === 'function' ? options.onProgress : null;
  const updateFrameLabel = options?.updateFrameLabel !== false;
  const requestSeq = Number.isFinite(Number(options?.requestSeq)) ? Number(options.requestSeq) : null;
  const progressByCombo = new Map();

  for (const selection of selections) {
    progressByCombo.set(selection.comboKey, {
      completed: 0,
      total: requested,
      failed: 0,
      phase: 'resolving',
    });
  }

  const emitAggregateProgress = () => {
    if (typeof onProgress !== 'function') return;
    let completed = 0;
    let total = 0;
    let failed = 0;
    let hasError = false;
    let allDone = true;

    for (const state of progressByCombo.values()) {
      completed += Math.max(0, Number(state?.completed) || 0);
      total += Math.max(0, Number(state?.total) || 0);
      failed += Math.max(0, Number(state?.failed) || 0);
      if (state?.phase !== 'complete' && state?.phase !== 'complete-with-errors' && state?.phase !== 'error') {
        allDone = false;
      }
      if (state?.failed > 0 || state?.phase === 'error' || state?.phase === 'complete-with-errors') {
        hasError = true;
      }
    }

    try {
      onProgress({
        phase: allDone ? (hasError ? 'complete-with-errors' : 'complete') : 'downloading',
        completed,
        total,
        failed,
        panes: selections.length,
      });
    } catch (_) {}
  };

  emitAggregateProgress();

  const results = await Promise.allSettled(selections.map(async selection => {
    try {
      const entries = await loadRecentWiseFrames(sid, selection.family, selection.tilt, requested, {
        activate: selection.comboKey === primarySelection.comboKey,
        updateFrameLabel: false,
        requestSeq,
        onProgress: progress => {
          progressByCombo.set(selection.comboKey, {
            completed: Math.max(0, Number(progress?.completed) || 0),
            total: Math.max(0, Number(progress?.total) || requested),
            failed: Math.max(0, Number(progress?.failed) || 0),
            phase: String(progress?.phase || 'downloading'),
          });
          emitAggregateProgress();
        },
      });
      progressByCombo.set(selection.comboKey, {
        completed: entries.length,
        total: entries.length,
        failed: 0,
        phase: 'complete',
      });
      emitAggregateProgress();
      return { selection, entries };
    } catch (err) {
      const prev = progressByCombo.get(selection.comboKey) || {};
      progressByCombo.set(selection.comboKey, {
        completed: Math.max(0, Number(prev.completed) || 0),
        total: Math.max(requested, Number(prev.total) || requested),
        failed: Math.max(requested, Number(prev.failed) || 0),
        phase: 'error',
      });
      emitAggregateProgress();
      throw err;
    }
  }));

  if (requestSeq !== null && requestSeq !== recentFramesLoadSeq) {
    return { activeEntries: [], selections, results };
  }

  const primaryResult = results.find(result =>
    result.status === 'fulfilled' && result.value.selection.comboKey === primarySelection.comboKey
  );
  const fallbackResult = results.find(result => result.status === 'fulfilled');
  const activeEntries = primaryResult?.status === 'fulfilled'
    ? primaryResult.value.entries
    : (fallbackResult?.status === 'fulfilled' ? fallbackResult.value.entries : []);

  if (!activeEntries.length) {
    const firstFailure = results.find(result => result.status === 'rejected');
    throw firstFailure?.reason || new Error('Recent frames failed.');
  }

  const primaryHistory = historyMap.get(primarySelection.comboKey) || activeEntries;
  if (primaryHistory.length >= 2) {
    _setManualHistoryMode(primarySelection.comboKey, primaryHistory);
    const targetIndex = (historyIdx >= 0 && historyIdx < primaryHistory.length)
      ? historyIdx
      : (primaryHistory.length - 1);
    historyIdx = targetIndex;
    if (multiPaneCount > 1) {
      _queueHistoryRender(targetIndex, primaryHistory, { priority: true });
    } else if (frameCache.has(primaryHistory[targetIndex]?.key)) {
      showFrame(primaryHistory[targetIndex].key, { skipPrefetch: true, immediateUpload: true });
    }
    _scheduleTimelineSettle(targetIndex, primaryHistory, true);
  }

  _syncLoadMoreBtn();
  if (updateFrameLabel) setFrameLabel(`Recent frames: ${activeEntries.length}`, 'live');
  return {
    activeEntries,
    selections,
    results,
  };
}

async function loadRecentWiseFramesForAllProducts(stationId = activeStation, primaryFamily = activeFamily, tilt = activeTilt, count = RECENT_WISE_FRAME_COUNT, options = {}) {
  if (!_stationSupportsProcessedWise(stationId)) {
    throw new Error('Recent frame downloads are only available for processed WeatherWise products.');
  }
  const sid = canonicalStationId(stationId);
  const primary = String(primaryFamily || '').toUpperCase();
  const families = supportedL3FamiliesForStation(sid);
  const orderedFamilies = [
    primary,
    ...families.filter(family => family !== primary),
  ].filter((family, index, arr) => family && arr.indexOf(family) === index);
  const requested = Math.max(2, Math.min(MAX_HISTORY_FRAMES, Math.round(Number(count) || RECENT_WISE_FRAME_COUNT)));
  const primaryTilt = _normalizeProcessedWiseTilt(primary, tilt);
  const primaryComboKey = `${sid}:${primary}:${primaryTilt}`;
  _refreshManualHistoryBurst(primaryComboKey, MANUAL_HISTORY_BURST_MS);
  const onProgress = typeof options?.onProgress === 'function' ? options.onProgress : null;
  const updateFrameLabel = options?.updateFrameLabel !== false;
  const requestSeq = Number.isFinite(Number(options?.requestSeq)) ? Number(options.requestSeq) : null;
  const progressByFamily = new Map();
  for (const family of orderedFamilies) {
    progressByFamily.set(family, {
      completed: 0,
      total: requested,
      failed: 0,
      phase: 'resolving',
    });
  }
  const emitAggregateProgress = () => {
    if (typeof onProgress !== 'function') return;
    let completed = 0;
    let total = 0;
    let failed = 0;
    let hasError = false;
    let allDone = true;
    for (const state of progressByFamily.values()) {
      completed += Math.max(0, Number(state?.completed) || 0);
      total += Math.max(0, Number(state?.total) || 0);
      failed += Math.max(0, Number(state?.failed) || 0);
      if (state?.phase !== 'complete' && state?.phase !== 'complete-with-errors' && state?.phase !== 'error') {
        allDone = false;
      }
      if (state?.failed > 0 || state?.phase === 'error' || state?.phase === 'complete-with-errors') hasError = true;
    }
    const phase = allDone
      ? (hasError ? 'complete-with-errors' : 'complete')
      : 'downloading';
    try {
      onProgress({
        phase,
        completed,
        total,
        failed,
        families: orderedFamilies.length,
      });
    } catch (_) {}
  };
  emitAggregateProgress();
  const loadFamily = async (family, { queueOnly = false } = {}) => {
    try {
      const entries = await loadRecentWiseFrames(sid, family, tilt, requested, {
        activate: family === primary,
        queueOnly,
        updateFrameLabel: false,
        requestSeq,
        onProgress: progress => {
          progressByFamily.set(family, {
            completed: Math.max(0, Number(progress?.completed) || 0),
            total: Math.max(0, Number(progress?.total) || requested),
            failed: Math.max(0, Number(progress?.failed) || 0),
            phase: String(progress?.phase || 'downloading'),
          });
          emitAggregateProgress();
        },
      });
      progressByFamily.set(family, {
        completed: entries.length,
        total: entries.length,
        failed: 0,
        phase: 'complete',
      });
      emitAggregateProgress();
      return { family, entries };
    } catch (err) {
      const prev = progressByFamily.get(family) || {};
      progressByFamily.set(family, {
        completed: Math.max(0, Number(prev.completed) || 0),
        total: Math.max(requested, Number(prev.total) || requested),
        failed: Math.max(requested, Number(prev.failed) || 0),
        phase: 'error',
      });
      emitAggregateProgress();
      throw err;
    }
  };

  const results = [];
  const primaryIndex = orderedFamilies.indexOf(primary);
  if (primaryIndex >= 0) {
    results.push(await Promise.resolve(loadFamily(primary, { queueOnly: false }))
      .then(value => ({ status: 'fulfilled', value }))
      .catch(reason => ({ status: 'rejected', reason })));
  }
  const otherFamilies = orderedFamilies.filter(family => family !== primary);
  const otherResults = await Promise.allSettled(otherFamilies.map(async family => loadFamily(family, { queueOnly: true })));
  results.push(...otherResults);
  if (requestSeq !== null && requestSeq !== recentFramesLoadSeq) {
    return { activeEntries: [], families: orderedFamilies, results };
  }
  const primaryResult = results.find(result => result.status === 'fulfilled' && result.value.family === primary);
  const fallbackResult = results.find(result => result.status === 'fulfilled');
  const activeEntries = primaryResult?.status === 'fulfilled'
    ? primaryResult.value.entries
    : (fallbackResult?.status === 'fulfilled' ? fallbackResult.value.entries : []);
  const activeFamilyName = primaryResult?.status === 'fulfilled'
    ? primary
    : (fallbackResult?.status === 'fulfilled' ? fallbackResult.value.family : primary);
  if (!activeEntries.length) {
    const firstFailure = results.find(result => result.status === 'rejected');
    throw firstFailure?.reason || new Error('Recent frames failed.');
  }
  const activeComboKey = `${sid}:${activeFamilyName}:${_normalizeProcessedWiseTilt(activeFamilyName, tilt)}`;
  const primaryHistory = historyMap.get(activeComboKey) || activeEntries;
  if (primaryHistory.length >= 2) {
    _setManualHistoryMode(activeComboKey, primaryHistory);
    const targetIndex = (historyIdx >= 0 && historyIdx < primaryHistory.length)
      ? historyIdx
      : (primaryHistory.length - 1);
    historyIdx = targetIndex;
    if (multiPaneCount > 1) {
      _queueHistoryRender(targetIndex, primaryHistory, { priority: true });
    } else if (frameCache.has(primaryHistory[targetIndex]?.key)) {
      showFrame(primaryHistory[targetIndex].key, { skipPrefetch: true, immediateUpload: true });
    }
    _scheduleTimelineSettle(targetIndex, primaryHistory, true);
  }
  if (updateFrameLabel) setFrameLabel(`Recent frames: ${activeEntries.length}`, 'live');
  return {
    activeEntries,
    families: orderedFamilies,
    results,
  };
}

const _tlPlay   = document.getElementById('tl-btn-play');
const _tlClose  = document.getElementById('tl-btn-close');
