let settingsWindowDrag = null;
let settingsWindowResize = null;
let settingsWindowHasManualPlacement = false;

function _clampSettingsWindowPosition(left, top) {
  if (!settingsModal) return { left, top };
  const rect = settingsModal.getBoundingClientRect();
  const margin = 8;
  const maxLeft = Math.max(margin, window.innerWidth - rect.width - margin);
  const maxTop = Math.max(margin, window.innerHeight - rect.height - margin);
  return {
    left: Math.max(margin, Math.min(left, maxLeft)),
    top: Math.max(margin, Math.min(top, maxTop)),
  };
}

function _setSettingsWindowPosition(left, top) {
  if (!settingsModal) return;
  const pos = _clampSettingsWindowPosition(left, top);
  settingsModal.style.left = `${Math.round(pos.left)}px`;
  settingsModal.style.top = `${Math.round(pos.top)}px`;
}

function _centerSettingsWindow() {
  if (!settingsModal) return;
  const rect = settingsModal.getBoundingClientRect();
  const margin = 8;
  const width = Math.min(rect.width || 900, window.innerWidth - margin * 2);
  const height = Math.min(rect.height || 680, window.innerHeight - margin * 2);
  const left = Math.max(margin, (window.innerWidth - width) / 2);
  const top = Math.max(margin, (window.innerHeight - height) / 2);
  if (settingsModal.style.width || settingsModal.style.height) {
    _setSettingsWindowRect(left, top, width, height);
  } else {
    _setSettingsWindowPosition(left, top);
  }
}

function _settingsWindowBounds() {
  const margin = 8;
  return {
    margin,
    minWidth: Math.min(420, Math.max(300, window.innerWidth - margin * 2)),
    minHeight: Math.min(360, Math.max(260, window.innerHeight - margin * 2)),
    maxWidth: Math.max(300, window.innerWidth - margin * 2),
    maxHeight: Math.max(260, window.innerHeight - margin * 2),
  };
}

function _setSettingsWindowRect(left, top, width, height) {
  if (!settingsModal) return;
  const bounds = _settingsWindowBounds();
  let nextWidth = Math.max(bounds.minWidth, Math.min(bounds.maxWidth, Number(width) || bounds.minWidth));
  let nextHeight = Math.max(bounds.minHeight, Math.min(bounds.maxHeight, Number(height) || bounds.minHeight));
  let nextLeft = Number(left) || bounds.margin;
  let nextTop = Number(top) || bounds.margin;

  if (nextLeft < bounds.margin) {
    nextWidth -= bounds.margin - nextLeft;
    nextLeft = bounds.margin;
  }
  if (nextTop < bounds.margin) {
    nextHeight -= bounds.margin - nextTop;
    nextTop = bounds.margin;
  }
  if (nextLeft + nextWidth > window.innerWidth - bounds.margin) {
    nextWidth = window.innerWidth - bounds.margin - nextLeft;
  }
  if (nextTop + nextHeight > window.innerHeight - bounds.margin) {
    nextHeight = window.innerHeight - bounds.margin - nextTop;
  }

  nextWidth = Math.max(bounds.minWidth, Math.min(bounds.maxWidth, nextWidth));
  nextHeight = Math.max(bounds.minHeight, Math.min(bounds.maxHeight, nextHeight));
  nextLeft = Math.max(bounds.margin, Math.min(window.innerWidth - nextWidth - bounds.margin, nextLeft));
  nextTop = Math.max(bounds.margin, Math.min(window.innerHeight - nextHeight - bounds.margin, nextTop));

  settingsModal.style.left = `${Math.round(nextLeft)}px`;
  settingsModal.style.top = `${Math.round(nextTop)}px`;
  settingsModal.style.width = `${Math.round(nextWidth)}px`;
  settingsModal.style.height = `${Math.round(nextHeight)}px`;
}

function _ensureSettingsWindowInViewport() {
  if (!settingsModal) return;
  if (!settingsWindowHasManualPlacement) {
    _centerSettingsWindow();
    return;
  }
  const rect = settingsModal.getBoundingClientRect();
  const left = rect.left;
  const top = rect.top;
  if (settingsModal.style.width || settingsModal.style.height) {
    _setSettingsWindowRect(left, top, rect.width, rect.height);
  } else {
    _setSettingsWindowPosition(left, top);
  }
}

function _bindSettingsWindowDrag() {
  if (!settingsModal || !settingsModalHeader) return;

  settingsModalHeader.addEventListener('pointerdown', event => {
    if (event.button != null && event.button !== 0) return;
    if (event.target?.closest?.('button, input, select, textarea, a')) return;
    const rect = settingsModal.getBoundingClientRect();
    settingsWindowDrag = {
      pointerId: event.pointerId,
      startX: event.clientX,
      startY: event.clientY,
      left: rect.left,
      top: rect.top,
    };
    settingsModal.classList.add('dragging');
    settingsModalHeader.setPointerCapture?.(event.pointerId);
    event.preventDefault();
  });

  settingsModalHeader.addEventListener('pointermove', event => {
    if (!settingsWindowDrag || settingsWindowDrag.pointerId !== event.pointerId) return;
    _setSettingsWindowPosition(
      settingsWindowDrag.left + event.clientX - settingsWindowDrag.startX,
      settingsWindowDrag.top + event.clientY - settingsWindowDrag.startY,
    );
    settingsWindowHasManualPlacement = true;
  });

  const endDrag = event => {
    if (!settingsWindowDrag || settingsWindowDrag.pointerId !== event.pointerId) return;
    settingsModal.classList.remove('dragging');
    settingsModalHeader.releasePointerCapture?.(event.pointerId);
    settingsWindowDrag = null;
  };

  settingsModalHeader.addEventListener('pointerup', endDrag);
  settingsModalHeader.addEventListener('pointercancel', endDrag);
  window.addEventListener('resize', _ensureSettingsWindowInViewport);
}

function _ensureSettingsResizeHandles() {
  if (!settingsModal || settingsModal.dataset.resizeHandles === 'true') return;
  ['nw', 'ne', 'sw', 'se'].forEach(corner => {
    const handle = document.createElement('div');
    handle.className = `settings-resize-handle ${corner}`;
    handle.dataset.resizeCorner = corner;
    handle.setAttribute('aria-hidden', 'true');
    settingsModal.appendChild(handle);
  });
  settingsModal.dataset.resizeHandles = 'true';
}

function _bindSettingsWindowResize() {
  if (!settingsModal) return;
  _ensureSettingsResizeHandles();

  settingsModal.querySelectorAll('.settings-resize-handle').forEach(handle => {
    handle.addEventListener('pointerdown', event => {
      if (event.button != null && event.button !== 0) return;
      const corner = handle.dataset.resizeCorner || 'se';
      const rect = settingsModal.getBoundingClientRect();
      settingsWindowResize = {
        pointerId: event.pointerId,
        corner,
        startX: event.clientX,
        startY: event.clientY,
        left: rect.left,
        top: rect.top,
        width: rect.width,
        height: rect.height,
      };
      settingsModal.classList.add('resizing');
      handle.setPointerCapture?.(event.pointerId);
      event.preventDefault();
      event.stopPropagation();
    });

    handle.addEventListener('pointermove', event => {
      if (!settingsWindowResize || settingsWindowResize.pointerId !== event.pointerId) return;
      const dx = event.clientX - settingsWindowResize.startX;
      const dy = event.clientY - settingsWindowResize.startY;
      const fromLeft = settingsWindowResize.corner.includes('w');
      const fromTop = settingsWindowResize.corner.includes('n');
      const nextLeft = fromLeft ? settingsWindowResize.left + dx : settingsWindowResize.left;
      const nextTop = fromTop ? settingsWindowResize.top + dy : settingsWindowResize.top;
      const nextWidth = fromLeft ? settingsWindowResize.width - dx : settingsWindowResize.width + dx;
      const nextHeight = fromTop ? settingsWindowResize.height - dy : settingsWindowResize.height + dy;
      _setSettingsWindowRect(nextLeft, nextTop, nextWidth, nextHeight);
      settingsWindowHasManualPlacement = true;
    });

    const endResize = event => {
      if (!settingsWindowResize || settingsWindowResize.pointerId !== event.pointerId) return;
      settingsModal.classList.remove('resizing');
      handle.releasePointerCapture?.(event.pointerId);
      settingsWindowResize = null;
    };
    handle.addEventListener('pointerup', endResize);
    handle.addEventListener('pointercancel', endResize);
  });
}

_bindSettingsWindowDrag();
_bindSettingsWindowResize();

function setSettingsOpen(open) {
  const next = !!open;
  settingsOverlay?.classList.toggle('open', next);
  settingsOverlay?.setAttribute('aria-hidden', next ? 'false' : 'true');
  settingsBtn?.classList.toggle('open', next);
  settingsBtn?.setAttribute('aria-expanded', next ? 'true' : 'false');
  if (!next) {
    settingsWindowDrag = null;
    settingsWindowResize = null;
    settingsModal?.classList.remove('dragging');
    settingsModal?.classList.remove('resizing');
    settingsModalHeader?.blur?.();
    settingsBtn?.blur?.();
    return;
  }
  if (next) {
    requestAnimationFrame(_ensureSettingsWindowInViewport);
    _setCitySearchOpen(false);
    _settingsSetPage(settingsActivePage || 'radar');
    syncSettingsLayerUi();
    syncSpcFilterUi();
    syncMesoFilterUi();
    syncStormFilterUi();
    syncCameraFilterUi();
    syncMapStyleUi();
    syncAppCacheUi();
    syncAppUpdateUi();
    syncNwwsSettingsUi();
    syncYouTubeEmbedUi();
    syncWarningPrefsUi();
  }
}

if (settingsBtn) {
  settingsBtn.addEventListener('click', e => {
    e.stopPropagation();
    const opening = !settingsOverlay?.classList.contains('open');
    setSettingsOpen(opening);
    if (opening) {
      setInfoPopupOpen(false);
    }
  });
}

if (citySearchBtn) {
  citySearchBtn.addEventListener('click', e => {
    e.stopPropagation();
    const opening = !citySearchOpen;
    if (opening) {
      setSettingsOpen(false);
      setInfoPopupOpen(false);
    }
    _setCitySearchOpen(opening);
  });
}

if (citySearchInput) {
  citySearchInput.addEventListener('input', () => {
    const q = String(citySearchInput.value || '').trim();
    if (!citySearchOpen) _setCitySearchOpen(true);
    if (q.length < CITY_SEARCH_MIN_CHARS) {
      _clearCitySearchResults();
      return;
    }
    _queueCitySearch(q);
  });
  citySearchInput.addEventListener('keydown', e => {
    if (e.key === 'Enter') {
      const firstResult = citySearchResults?.querySelector('.city-search-item');
      if (firstResult) {
        e.preventDefault();
        firstResult.click();
      }
    }
  });
}

settingsOverlay?.addEventListener('click', e => {
  if (e.target === settingsOverlay) e.stopPropagation();
});

document.getElementById('settings-close')?.addEventListener('click', () => setSettingsOpen(false));

document.addEventListener('keydown', e => {
  if (e.key === 'Escape' && settingsOverlay?.classList.contains('open')) setSettingsOpen(false);
});

SETTINGS_GROUP_IDS.forEach(groupId => {
  document.getElementById(`settings-group-${groupId}-btn`)?.addEventListener('click', e => {
    e.stopPropagation();
    const group = document.getElementById(`settings-group-${groupId}`);
    const open = !group?.classList.contains('open');
    setSettingsGroupOpen(groupId, open);
  });
});

function _setDbzFilter(next, { apply = true, persist = true } = {}) {
  const numeric = Number(next);
  const clamped = Number.isFinite(numeric) ? Math.max(-30, Math.min(75, Math.round(numeric))) : -30;
  dbzFilter = clamped;
  if (dbzSlider && Number(dbzSlider.value) !== clamped) dbzSlider.value = String(clamped);
  if (dbzNumberInput && Number(dbzNumberInput.value) !== clamped) dbzNumberInput.value = String(clamped);
  if (apply) applyFilter();
  if (persist) saveSettings();
}

function _setRadarDataSmoothing(next, { persist = true } = {}) {
  const enabled = !!next;
  if (radarDataSmoothing === enabled) return;
  radarDataSmoothing = enabled;
  if (persist) saveSettings();
  _invalidateSmoothingCaches();
  _scheduleRadarDataSmoothingRebuild(0);
  syncSettingsLayerUi();
}

function _setRadarDataSmoothingStrength(next, { persist = true } = {}) {
  const numeric = Number(next);
  radarDataSmoothingStrength = Number.isFinite(numeric)
    ? Math.max(0, Math.min(1, numeric))
    : 0.65;
  if (persist) saveSettings();
  _invalidateSmoothingCaches();
  _scheduleRadarDataSmoothingRebuild();
  syncSettingsLayerUi();
}

if (dbzSlider) {
  dbzSlider.addEventListener('input', () => {
    _setDbzFilter(dbzSlider.value);
  });
}

dbzNumberInput?.addEventListener('input', () => {
  _setDbzFilter(dbzNumberInput.value, { apply: false, persist: false });
});

dbzNumberInput?.addEventListener('change', () => {
  _setDbzFilter(dbzNumberInput.value);
});

const toggleSweep = document.getElementById('toggle-sweep');
if (toggleSweep) {
  toggleSweep.addEventListener('change', () => {
    liveSweepEnabled = toggleSweep.checked;
    if (!liveSweepEnabled) {
      cancelSweep(true);
      _cancelAllPaneSweeps(true);
    }
    saveSettings();
  });
}

const toggleCameras = document.getElementById('toggle-cameras');
const cameraFilterBtn = document.getElementById('camera-filter-btn');
if (toggleCameras) {
  toggleCameras.addEventListener('change', () => {
    camerasOverlayVisible = !!toggleCameras.checked;
    if (camerasOverlayVisible) _scheduleCameraStartupSync();
    else {
      _clearCameraStartupRetry();
      void syncCameraLayersFromState();
      _clearLoadedCameraData();
    }
    saveSettings();
  });
}

function setCameraFilterOpen(open) {
  const panel = document.getElementById('settings-section-camera');
  const btn = document.getElementById('camera-filter-btn');
  if (!panel || !btn) return;
  panel.classList.toggle('open', open);
  btn.classList.toggle('open', open);
  btn.setAttribute('aria-expanded', open ? 'true' : 'false');
}

const US_STATE_NAMES = {
  AL: 'Alabama', AK: 'Alaska', AZ: 'Arizona', AR: 'Arkansas', CA: 'California',
  CO: 'Colorado', CT: 'Connecticut', DE: 'Delaware', FL: 'Florida', GA: 'Georgia',
  HI: 'Hawaii', ID: 'Idaho', IL: 'Illinois', IN: 'Indiana', IA: 'Iowa',
  KS: 'Kansas', KY: 'Kentucky', LA: 'Louisiana', ME: 'Maine', MD: 'Maryland',
  MA: 'Massachusetts', MI: 'Michigan', MN: 'Minnesota', MS: 'Mississippi', MO: 'Missouri',
  MT: 'Montana', NE: 'Nebraska', NV: 'Nevada', NH: 'New Hampshire', NJ: 'New Jersey',
  NM: 'New Mexico', NY: 'New York', NC: 'North Carolina', ND: 'North Dakota', OH: 'Ohio',
  OK: 'Oklahoma', OR: 'Oregon', PA: 'Pennsylvania', RI: 'Rhode Island', SC: 'South Carolina',
  SD: 'South Dakota', TN: 'Tennessee', TX: 'Texas', UT: 'Utah', VT: 'Vermont',
  VA: 'Virginia', WA: 'Washington', WV: 'West Virginia', WI: 'Wisconsin', WY: 'Wyoming',
  DC: 'District of Columbia', PR: 'Puerto Rico', GU: 'Guam', VI: 'U.S. Virgin Islands',
};

let _cameraStateDropdownBound = false;

function _syncCameraStateDropdown() {
  const btn = document.getElementById('camera-state-btn');
  const btnLabel = document.getElementById('camera-state-btn-label');
  const panel = document.getElementById('camera-state-panel');
  const searchInput = document.getElementById('camera-state-search-input');
  const listEl = document.getElementById('camera-state-list');
  if (!btn || !panel || !listEl) return;

  if (cameraStateFilter !== 'ALL' && !cameraKnownStates.includes(cameraStateFilter)) {
    cameraStateFilter = 'ALL';
  }

  // Update button label
  const labelText = cameraStateFilter === 'ALL'
    ? 'All States'
    : (US_STATE_NAMES[cameraStateFilter] || cameraStateFilter);
  if (btnLabel) btnLabel.textContent = labelText;

  // Rebuild list
  listEl.innerHTML = '';
  const allItem = document.createElement('div');
  allItem.className = 'camera-state-item' + (cameraStateFilter === 'ALL' ? ' active' : '');
  allItem.textContent = 'All States';
  allItem.dataset.value = 'ALL';
  listEl.appendChild(allItem);

  cameraKnownStates.forEach(code => {
    const item = document.createElement('div');
    item.className = 'camera-state-item' + (cameraStateFilter === code ? ' active' : '');
    item.textContent = US_STATE_NAMES[code] ? `${US_STATE_NAMES[code]} (${code})` : code;
    item.dataset.value = code;
    listEl.appendChild(item);
  });

  // Apply search filter if open
  if (searchInput && searchInput.value.trim()) {
    _filterCameraStateList(searchInput.value.trim());
  }

  // Bind events once
  if (!_cameraStateDropdownBound) {
    _cameraStateDropdownBound = true;

    btn.addEventListener('click', e => {
      e.stopPropagation();
      const isOpen = panel.classList.contains('open');
      if (isOpen) {
        panel.classList.remove('open');
        btn.setAttribute('aria-expanded', 'false');
      } else {
        panel.classList.add('open');
        btn.setAttribute('aria-expanded', 'true');
        if (searchInput) { searchInput.value = ''; _filterCameraStateList(''); searchInput.focus(); }
      }
    });

    listEl.addEventListener('click', e => {
      const item = e.target?.closest?.('.camera-state-item');
      if (!item) return;
      const next = String(item.dataset.value || 'ALL').toUpperCase();
      cameraStateFilter = (next === 'ALL' || cameraKnownStates.includes(next)) ? next : 'ALL';
      panel.classList.remove('open');
      btn.setAttribute('aria-expanded', 'false');
      _syncCameraStateDropdown();
      _applyCameraStateFilter();
      saveSettings();
    });

    if (searchInput) {
      searchInput.addEventListener('input', () => _filterCameraStateList(searchInput.value.trim()));
      searchInput.addEventListener('click', e => e.stopPropagation());
      searchInput.addEventListener('keydown', e => {
        if (e.key === 'Escape') { panel.classList.remove('open'); btn.setAttribute('aria-expanded', 'false'); }
      });
    }

    document.addEventListener('click', e => {
      const dropdown = document.getElementById('camera-state-dropdown');
      if (dropdown && !dropdown.contains(e.target)) {
        panel.classList.remove('open');
        btn.setAttribute('aria-expanded', 'false');
      }
    }, true);
  }
}

function _filterCameraStateList(query) {
  const listEl = document.getElementById('camera-state-list');
  if (!listEl) return;
  const q = query.toLowerCase();
  Array.from(listEl.children).forEach(item => {
    const text = item.textContent.toLowerCase();
    item.classList.toggle('hidden', !!q && !text.includes(q));
  });
}

function syncCameraFilterUi() {
  const trafficToggle = document.getElementById('camera-filter-traffic');
  const weatherToggle = document.getElementById('camera-filter-weather');
  const chasersToggle = document.getElementById('camera-filter-chasers');
  const videoOnlyToggle = document.getElementById('camera-video-only-toggle');
  const bindFeedToggle = (el, key) => {
    if (!el) return;
    el.checked = cameraFilterSelection[key] !== false;
    el.onchange = () => {
      cameraFilterSelection[key] = !!el.checked;
      void syncCameraLayersFromState();
      saveSettings();
    };
  };
  bindFeedToggle(trafficToggle, 'traffic');
  bindFeedToggle(weatherToggle, 'weather');
  bindFeedToggle(chasersToggle, 'chasers');
  if (videoOnlyToggle) {
    videoOnlyToggle.checked = cameraVideoOnly;
    videoOnlyToggle.onchange = () => {
      cameraVideoOnly = !!videoOnlyToggle.checked;
      _applyCameraStateFilter();
      saveSettings();
    };
  }

  _syncCameraStateDropdown();
}

function setWarningPrefsOpen(open) {
  const overlay = warningPrefsOverlay || document.getElementById('warning-prefs-overlay');
  const btn = warningPrefsBtn || document.getElementById('warning-prefs-btn');
  if (!overlay || !btn) return;
  overlay.classList.toggle('open', open);
  overlay.setAttribute('aria-hidden', open ? 'false' : 'true');
  btn.classList.toggle('open', open);
  btn.setAttribute('aria-expanded', open ? 'true' : 'false');
  if (open) syncWarningPrefsUi();
}

function _syncActiveWarningPlayerVolumes() {
  const scale = _normalizeWarningGlobalVolume(warningGlobalVolume) / 100;
  for (const audio of warningSoundActivePlayers) {
    if (!audio) continue;
    const baseVolume = Math.max(0, Math.min(1, Number(audio._warningBaseVolume ?? 0.6)));
    try {
      audio.volume = Math.max(0, Math.min(1, baseVolume * scale));
    } catch (_) {}
  }
}

function _setWarningGlobalVolume(next, opts = {}) {
  warningGlobalVolume = _normalizeWarningGlobalVolume(next);
  _syncActiveWarningPlayerVolumes();
  if (opts?.persist !== false) saveSettings();
}

function renderWarningPrefsInto(container) {
  if (!container) return;
  container.innerHTML = '';
  const categorySections = [];
  let activeCategorySection = null;

  const makeToggleControl = (checked, onChange, className = 'warning-pref-toggle-wrap') => {
    const wrap = document.createElement('div');
    wrap.className = className;
    const text = document.createElement('span');
    text.className = 'warning-pref-toggle-text';
    const label = document.createElement('label');
    label.className = 'toggle';
    const input = document.createElement('input');
    input.type = 'checkbox';
    input.checked = !!checked;
    const track = document.createElement('span');
    track.className = 'toggle-track';
    label.appendChild(input);
    label.appendChild(track);
    const applyState = (next) => {
      const enabled = !!next;
      input.checked = enabled;
      text.textContent = enabled ? 'On' : 'Off';
      wrap.dataset.state = enabled ? 'on' : 'off';
    };
    applyState(checked);
    input.addEventListener('change', () => {
      const next = !!input.checked;
      applyState(next);
      onChange(next, input);
    });
    wrap.appendChild(text);
    wrap.appendChild(label);
    return { wrap, input, text, applyState };
  };

  const makeControlRow = (labelText, controlEl) => {
    const row = document.createElement('div');
    row.className = 'warning-pref-control-row';
    const label = document.createElement('div');
    label.className = 'warning-pref-control-label';
    label.textContent = labelText;
    row.appendChild(label);
    row.appendChild(controlEl);
    return row;
  };

  const makeRangeControl = ({ min, max, step, value, formatter, ariaLabel }) => {
    const wrap = document.createElement('div');
    wrap.className = 'warning-pref-range-control';
    const input = document.createElement('input');
    input.type = 'range';
    input.min = String(min);
    input.max = String(max);
    input.step = String(step);
    input.value = String(value);
    input.className = 'warning-pref-range';
    if (ariaLabel) input.setAttribute('aria-label', ariaLabel);
    const badge = document.createElement('div');
    badge.className = 'warning-pref-range-value';
    const updateBadge = () => {
      const raw = Number(input.value);
      badge.textContent = formatter(raw);
    };
    updateBadge();
    wrap.appendChild(input);
    wrap.appendChild(badge);
    return { wrap, input, badge, updateBadge };
  };

  const _PREF_CATEGORY_ORDER = ['tornado', 'severe', 'winter', 'special', 'flood', 'other'];
  const _PREF_CATEGORY_LABELS = { tornado: 'Tornado', severe: 'Severe', winter: 'Winter', special: 'Special Event', flood: 'Flood', other: 'Other' };

  const volumeCard = document.createElement('div');
  volumeCard.className = 'warning-pref-item warning-pref-volume-item';

  const volumeRow = document.createElement('div');
  volumeRow.className = 'warning-pref-summary warning-pref-volume-summary';

  const volumeTitleWrap = document.createElement('div');
  volumeTitleWrap.className = 'warning-pref-summary-main';

  const volumeTitle = document.createElement('div');
  volumeTitle.className = 'warning-pref-summary-title';
  volumeTitle.textContent = 'Global Alert Volume';

  const volumeSubtitle = document.createElement('div');
  volumeSubtitle.className = 'warning-pref-summary-code warning-pref-summary-note';
  volumeSubtitle.textContent = 'Controls all warning sounds';

  volumeTitleWrap.appendChild(volumeTitle);
  volumeTitleWrap.appendChild(volumeSubtitle);

  const volumeControl = makeRangeControl({
    min: 0,
    max: 100,
    step: 1,
    value: _normalizeWarningGlobalVolume(warningGlobalVolume),
    formatter: next => `${Math.round(next)}%`,
    ariaLabel: 'Global alert volume',
  });

  const updateVolumeUi = (persist) => {
    const next = _normalizeWarningGlobalVolume(volumeControl.input.value);
    volumeControl.updateBadge();
    _setWarningGlobalVolume(next, { persist });
  };
  volumeControl.input.addEventListener('input', () => updateVolumeUi(false));
  volumeControl.input.addEventListener('change', () => updateVolumeUi(true));

  volumeRow.appendChild(volumeTitleWrap);
  volumeRow.appendChild(volumeControl.wrap);
  volumeCard.appendChild(volumeRow);
  container.appendChild(volumeCard);

  const searchWrap = document.createElement('div');
  searchWrap.className = 'warning-pref-search';
  const searchInput = document.createElement('input');
  searchInput.type = 'search';
  searchInput.className = 'sp-text warning-pref-search-input';
  searchInput.placeholder = 'Search warnings';
  searchInput.setAttribute('aria-label', 'Search warning preferences');
  searchInput.setAttribute('autocomplete', 'off');
  searchInput.setAttribute('spellcheck', 'false');
  searchWrap.appendChild(searchInput);
  container.appendChild(searchWrap);

  const applySearchFilter = (query = '') => {
    const q = String(query || '').trim().toLowerCase();
    categorySections.forEach(section => {
      let visibleCount = 0;
      section.entries.forEach(entry => {
        const haystack = String(entry.dataset.search || '').toLowerCase();
        const match = !q || haystack.includes(q);
        entry.hidden = !match;
        if (match) visibleCount += 1;
      });
      section.header.hidden = visibleCount === 0;
    });
  };
  searchInput.addEventListener('input', () => applySearchFilter(searchInput.value));

  // Group config items by category, preserving within-group order (warnings only)
  const _prefGroups = {};
  for (const cat of _PREF_CATEGORY_ORDER) _prefGroups[cat] = [];
  for (const meta of WARNING_PREF_CONFIG) {
    if (!_WARNING_ONLY_IDS.has(meta.id)) continue;
    const cat = _warningCategory(meta.id);
    (_prefGroups[cat] || _prefGroups['other']).push(meta);
  }

  const _orderedPrefItems = [];
  for (const cat of _PREF_CATEGORY_ORDER) {
    const items = _prefGroups[cat];
    if (!items || !items.length) continue;
    _orderedPrefItems.push({ _isCatHeader: true, cat });
    for (const meta of items) _orderedPrefItems.push(meta);
  }

  for (const item of _orderedPrefItems) {
    if (item._isCatHeader) {
      const header = document.createElement('div');
      header.className = 'warning-pref-category-header';
      header.textContent = _PREF_CATEGORY_LABELS[item.cat] || item.cat;
      container.appendChild(header);
      activeCategorySection = { header, entries: [] };
      categorySections.push(activeCategorySection);
      continue;
    }
    const meta = item;
    const pref = _warningPrefForClass(meta.id);
    const entry = document.createElement('div');
    entry.className = 'warning-pref-item warning-pref-entry';
    entry.classList.toggle('is-disabled', pref.showOnMap === false);
    entry.style.setProperty('--warning-pref-accent', pref.color || ALERT_FALLBACK_COLOR);
    entry.dataset.search = `${meta.label} ${meta.id} ${_warningCategory(meta.id)}`.toLowerCase();
    activeCategorySection?.entries.push(entry);

    const summary = document.createElement('div');
    summary.className = 'warning-pref-summary';

    const titleWrap = document.createElement('div');
    titleWrap.className = 'warning-pref-summary-main';

    const title = document.createElement('div');
    title.className = 'warning-pref-summary-title';
    title.textContent = meta.label;

    const code = document.createElement('div');
    code.className = 'warning-pref-summary-code';
    code.textContent = meta.id;

    titleWrap.appendChild(title);
    titleWrap.appendChild(code);

    const summaryActions = document.createElement('div');
    summaryActions.className = 'warning-pref-summary-actions';
    let applyEntryEnabledState = null;

    const showToggle = makeToggleControl(pref.showOnMap !== false, (next) => {
      applyEntryEnabledState?.(next, { persist: true });
      _alertsRefreshPresentationNow();
    });
    showToggle.wrap.title = pref.showOnMap !== false ? 'Warning enabled on map' : 'Warning hidden from map';

    const expandBtn = document.createElement('button');
    expandBtn.type = 'button';
    expandBtn.className = 'warning-pref-expand';
    expandBtn.setAttribute('aria-label', `Expand ${meta.label} options`);
    expandBtn.setAttribute('aria-expanded', 'false');
    expandBtn.innerHTML = '<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M7 10l5 5 5-5" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"></path></svg>';

    summaryActions.appendChild(showToggle.wrap);
    summaryActions.appendChild(expandBtn);
    summary.appendChild(titleWrap);
    summary.appendChild(summaryActions);

    const details = document.createElement('div');
    details.className = 'warning-pref-details';

    const outlineControl = document.createElement('label');
    outlineControl.className = 'warning-pref-color-control';
    const outlineInput = document.createElement('input');
    outlineInput.type = 'color';
    outlineInput.value = _normalizeSpcHex(pref.color) || ALERT_FALLBACK_COLOR;
    outlineInput.setAttribute('aria-label', `${meta.label} outline color`);
    outlineControl.appendChild(outlineInput);

    let fillInput = null;
    const applyOutlineColor = (persist) => {
      const prevOutline = _normalizeSpcHex(warningPrefs[meta.id].color) || ALERT_FALLBACK_COLOR;
      const prevFill = _normalizeSpcHex(warningPrefs[meta.id].fillColor) || prevOutline;
      const nextColor = _normalizeSpcHex(outlineInput.value) || ALERT_FALLBACK_COLOR;
      warningPrefs[meta.id].color = nextColor;
      entry.style.setProperty('--warning-pref-accent', nextColor);
      if (prevFill === prevOutline) {
        warningPrefs[meta.id].fillColor = nextColor;
        if (fillInput) fillInput.value = nextColor;
      }
      _alertsRefreshPresentationNow();
      if (persist) saveSettings();
    };
    outlineInput.addEventListener('input', () => applyOutlineColor(false));
    outlineInput.addEventListener('change', () => applyOutlineColor(true));

    const fillControl = document.createElement('label');
    fillControl.className = 'warning-pref-color-control';
    fillInput = document.createElement('input');
    fillInput.type = 'color';
    fillInput.value = _normalizeSpcHex(pref.fillColor) || _normalizeSpcHex(pref.color) || ALERT_FALLBACK_COLOR;
    fillInput.setAttribute('aria-label', `${meta.label} fill color`);
    fillControl.appendChild(fillInput);
    const applyFillColor = (persist) => {
      warningPrefs[meta.id].fillColor = _normalizeSpcHex(fillInput.value) || _normalizeSpcHex(warningPrefs[meta.id].color) || ALERT_FALLBACK_COLOR;
      _alertsRefreshPresentationNow();
      if (persist) saveSettings();
    };
    fillInput.addEventListener('input', () => applyFillColor(false));
    fillInput.addEventListener('change', () => applyFillColor(true));

    const fillOpacityControl = makeRangeControl({
      min: 0,
      max: 100,
      step: 1,
      value: Math.round(_normalizeWarningFillOpacity(pref.fillOpacity, _warningDefaultFillOpacity()) * 100),
      formatter: next => `${Math.round(next)}%`,
      ariaLabel: `${meta.label} fill opacity`,
    });
    const applyFillOpacity = (persist) => {
      warningPrefs[meta.id].fillOpacity = _normalizeWarningFillOpacity(Number(fillOpacityControl.input.value) / 100, _warningDefaultFillOpacity());
      fillOpacityControl.updateBadge();
      _alertsRefreshPresentationNow();
      if (persist) saveSettings();
    };
    fillOpacityControl.input.addEventListener('input', () => applyFillOpacity(false));
    fillOpacityControl.input.addEventListener('change', () => applyFillOpacity(true));

    const lineWidthControl = makeRangeControl({
      min: 1,
      max: 8,
      step: 0.1,
      value: _normalizeWarningLineWidth(pref.lineWidth, _warningDefaultLineWidth(meta.id)),
      formatter: next => `${Number(next).toFixed(1)} px`,
      ariaLabel: `${meta.label} outline width`,
    });
    const applyLineWidth = (persist) => {
      warningPrefs[meta.id].lineWidth = _normalizeWarningLineWidth(lineWidthControl.input.value, _warningDefaultLineWidth(meta.id));
      lineWidthControl.updateBadge();
      _alertsRefreshPresentationNow();
      if (persist) saveSettings();
    };
    lineWidthControl.input.addEventListener('input', () => applyLineWidth(false));
    lineWidthControl.input.addEventListener('change', () => applyLineWidth(true));

    const notifyToggle = makeToggleControl(pref.notifications === true, (next) => {
      warningPrefs[meta.id].notifications = next;
      saveSettings();
    }, 'warning-pref-toggle-wrap warning-pref-inline-toggle');

    const soundWrap = document.createElement('label');
    soundWrap.className = 'warning-pref-select-wrap';
    const soundSelect = document.createElement('select');
    soundSelect.className = 'warning-pref-select';
    WARNING_SOUND_OPTIONS.forEach(option => {
      const opt = document.createElement('option');
      opt.value = option.id;
      opt.textContent = option.label;
      soundSelect.appendChild(opt);
    });
    soundSelect.value = _normalizeWarningSoundId(pref.sound);
    soundWrap.appendChild(soundSelect);
    const soundControl = document.createElement('div');
    soundControl.className = 'warning-pref-sound-control';
    soundControl.appendChild(soundWrap);
    const soundTestBtn = document.createElement('button');
    soundTestBtn.type = 'button';
    soundTestBtn.className = 'warning-pref-sound-test';
    soundTestBtn.setAttribute('aria-label', `Test ${meta.label} sound`);
    soundTestBtn.title = 'Test sound';
    soundTestBtn.innerHTML = `
      <svg viewBox="0 0 24 24" aria-hidden="true">
        <path d="M4.75 14.55v-5.1c0-.86.69-1.55 1.55-1.55h2.85a1.3 1.3 0 0 0 .81-.28l3.3-2.67c.98-.79 2.44-.1 2.44 1.16v11.78c0 1.26-1.46 1.95-2.44 1.16l-3.3-2.67a1.3 1.3 0 0 0-.81-.28H6.3c-.86 0-1.55-.69-1.55-1.55Z" fill="currentColor"/>
        <path d="M18.1 9.3c.95.83 1.52 2.05 1.52 3.3 0 1.26-.57 2.48-1.52 3.3" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"/>
        <path d="M20.25 6.95c1.47 1.41 2.35 3.46 2.35 5.65s-.88 4.24-2.35 5.65" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"/>
      </svg>`;
    soundControl.appendChild(soundTestBtn);
    const syncSoundTestButton = (forceDisabled = false) => {
      const soundId = _normalizeWarningSoundId(soundSelect.value);
      const disabled = forceDisabled || soundId === 'silent';
      soundTestBtn.disabled = disabled;
      soundTestBtn.title = disabled ? (forceDisabled ? 'Enable warning first' : 'No sound selected') : 'Test sound';
      soundTestBtn.setAttribute('aria-label', disabled ? (forceDisabled ? `Enable ${meta.label} before testing sound` : `No sound selected for ${meta.label}`) : `Test ${meta.label} sound`);
    };
    syncSoundTestButton();
    soundSelect.addEventListener('change', () => {
      warningPrefs[meta.id].sound = _normalizeWarningSoundId(soundSelect.value);
      syncSoundTestButton();
      saveSettings();
    });
    soundTestBtn.addEventListener('click', (event) => {
      event.preventDefault();
      event.stopPropagation();
      const soundId = _normalizeWarningSoundId(soundSelect.value);
      if (soundId === 'silent') return;
      void _playWarningSound(soundId, { bypassCooldown: true });
    });

    const dependentControls = [
      notifyToggle.input,
      outlineInput,
      fillInput,
      fillOpacityControl.input,
      lineWidthControl.input,
      soundSelect,
    ];
    const dependentWrappers = [
      details,
      notifyToggle.wrap,
      outlineControl,
      fillControl,
      fillOpacityControl.wrap,
      lineWidthControl.wrap,
      soundControl,
    ];
    applyEntryEnabledState = (enabled, { persist = false } = {}) => {
      const active = !!enabled;
      warningPrefs[meta.id].showOnMap = active;
      entry.classList.toggle('is-disabled', !active);
      showToggle.wrap.title = active ? 'Warning enabled on map' : 'Warning hidden from map';
      dependentControls.forEach(control => {
        if (control) control.disabled = !active;
      });
      dependentWrappers.forEach(wrap => {
        wrap?.classList?.toggle('is-disabled', !active);
        if (wrap) wrap.setAttribute('aria-disabled', !active ? 'true' : 'false');
      });
      if (!active) {
        warningPrefs[meta.id].notifications = false;
        notifyToggle.applyState(false);
      }
      syncSoundTestButton(!active);
      if (persist) saveSettings();
    };

    details.appendChild(makeControlRow('Notifications', notifyToggle.wrap));
    details.appendChild(makeControlRow('Outline Color', outlineControl));
    details.appendChild(makeControlRow('Fill Color', fillControl));
    details.appendChild(makeControlRow('Fill Opacity', fillOpacityControl.wrap));
    details.appendChild(makeControlRow('Width', lineWidthControl.wrap));
    details.appendChild(makeControlRow('Sound', soundControl));

    expandBtn.addEventListener('click', (event) => {
      event.preventDefault();
      event.stopPropagation();
      const open = !entry.classList.contains('is-expanded');
      expandBtn.classList.toggle('open', open);
      entry.classList.toggle('is-expanded', open);
      details.classList.toggle('open', open);
      expandBtn.setAttribute('aria-expanded', open ? 'true' : 'false');
    });

    applyEntryEnabledState(pref.showOnMap !== false, { persist: false });

    entry.appendChild(summary);
    entry.appendChild(details);
    container.appendChild(entry);
  }
  applySearchFilter(searchInput.value);
}

