function setAppUpdateProgress(downloadedBytes = null, totalBytes = null, message = '') {
  if (appUpdateProgressEl) {
    appUpdateProgressEl.hidden = !(downloadedBytes != null || totalBytes != null);
  }
  if (appUpdateProgressBarEl) {
    let widthPct = 4;
    if (downloadedBytes != null && totalBytes > 0) {
      widthPct = Math.max(4, Math.min(100, (downloadedBytes / totalBytes) * 100));
    }
    appUpdateProgressBarEl.style.width = `${widthPct}%`;
  }
  if (appUpdateProgressTextEl) {
    appUpdateProgressTextEl.textContent = message || '';
  }
}

function syncAppUpdateUi() {
  if (appUpdateCurrentVersionEl) {
    appUpdateCurrentVersionEl.textContent = appUpdateCurrentVersion || '--';
  }
  if (appUpdateNextVersionEl) {
    appUpdateNextVersionEl.textContent = appUpdateInfo?.version || '--';
  }
  if (appUpdateCopyEl) {
    appUpdateCopyEl.textContent = appUpdateInfo
      ? 'A newer version is available and can be installed now.'
      : 'Check GitHub Releases for a newer version of the app.';
  }
  if (appUpdateNotesEl) {
    const notes = String(appUpdateInfo?.body || '').trim();
    appUpdateNotesEl.textContent = notes || 'No release notes provided.';
  }
  if (appUpdateCheckBtn) {
    appUpdateCheckBtn.disabled = appUpdateBusy;
    appUpdateCheckBtn.textContent = appUpdateBusy ? 'Checking...' : 'Check';
  }
  if (appUpdateInstallBtn) {
    appUpdateInstallBtn.disabled = !(Number(appUpdateInfo?.assetId || 0) > 0 && String(appUpdateInfo?.assetName || '').trim()) || appUpdateBusy;
    appUpdateInstallBtn.textContent = 'Install';
  }
  if (appUpdateLaterBtn) {
    appUpdateLaterBtn.disabled = appUpdateBusy;
    appUpdateLaterBtn.textContent = 'Later';
  }
  if (!appUpdateInfo && appUpdateProgressEl) {
    appUpdateProgressEl.hidden = true;
    if (appUpdateProgressBarEl) appUpdateProgressBarEl.style.width = '0%';
  }
}

function applyAppUpdateCheckResponse(res, { openModalOnAvailable = true } = {}) {
  appUpdateCurrentVersion = String(res?.currentVersion || appUpdateCurrentVersion || '');

  if (res?.status === 'available' && res.update) {
    appUpdateInfo = res.update;
    setAppUpdateStatus(`Update ${res.update.version} available`, 'success');
    const hasInstaller = Number(res.update.assetId || 0) > 0 && String(res.update.assetName || '').trim();
    setAppUpdatePhase(hasInstaller ? 'Ready to install' : 'Installer unavailable');
    setAppUpdateProgress(null, null, hasInstaller
      ? 'Install downloads the latest Windows installer and closes the app.'
      : 'This release does not include a direct Windows installer asset.');
    if (openModalOnAvailable) {
      setSettingsOpen(false);
      setInfoPopupOpen(false);
      setAppUpdateModalOpen(true);
    }
  } else if (res?.status === 'upToDate') {
    appUpdateInfo = null;
    setAppUpdateStatus(`Up to date (${appUpdateCurrentVersion || 'current'})`, 'success');
    setAppUpdatePhase('Up to date');
    setAppUpdateProgress(null, null, res?.message || '');
  } else if (res?.status === 'disabled') {
    appUpdateInfo = null;
    setAppUpdateStatus('Update checks not configured', '');
    setAppUpdatePhase('Disabled');
    setAppUpdateProgress(null, null, res?.message || '');
  } else {
    appUpdateInfo = null;
    setAppUpdateStatus('Update check failed', 'error');
    setAppUpdatePhase('Check failed');
  }

  syncAppUpdateUi();
}

function buildAppUpdateResponse(currentVersion, release) {
  const latestVersion = normalizeVersionLabel(release?.tag_name);
  if (!latestVersion) {
    throw new Error('GitHub release is missing a valid tag name.');
  }
  if (!parseVersionParts(currentVersion)) {
    throw new Error(`Current app version is invalid: ${currentVersion}`);
  }
  if (!parseVersionParts(latestVersion)) {
    throw new Error(`Latest release version is invalid: ${latestVersion}`);
  }
  if (compareVersionLabels(latestVersion, currentVersion) <= 0) {
    return {
      status: 'upToDate',
      currentVersion,
      update: null,
      message: 'You already have the latest version.',
    };
  }
  return {
    status: 'available',
    currentVersion,
    update: {
      version: latestVersion,
      currentVersion,
      body: release?.body || '',
      date: release?.published_at || '',
      downloadUrl: pickReleaseDownloadUrl(release),
      releaseUrl: String(release?.html_url || '').trim(),
    },
    message: null,
  };
}

async function checkForAppUpdate({ openModalOnAvailable = true } = {}) {
  if (appUpdateBusy) return;
  appUpdateBusy = true;
  setAppUpdateStatus('Checking for updates...', '');
  setAppUpdatePhase('Checking');
  setAppUpdateProgress(null, null, '');
  syncAppUpdateUi();

  try {
    const res = await invoke('check_app_update');
    applyAppUpdateCheckResponse(res, { openModalOnAvailable });
  } catch (err) {
    appUpdateInfo = null;
    setAppUpdateStatus('Update check failed', 'error');
    setAppUpdatePhase('Check failed');
    console.warn('app update check failed:', err);
    setAppUpdateProgress(null, null, err?.message || String(err));
    syncAppUpdateUi();
  } finally {
    appUpdateBusy = false;
    syncAppUpdateUi();
  }
}

async function openAppUpdateDownload() {
  if (appUpdateBusy || !appUpdateInfo) return;
  const assetId = Number(appUpdateInfo.assetId || 0);
  const assetName = String(appUpdateInfo.assetName || '').trim();
  if (!assetId || !assetName) {
    setAppUpdateStatus('No installer download available', 'error');
    setAppUpdatePhase('Unavailable');
    setAppUpdateProgress(null, null, 'This private release does not include a direct Windows installer asset.');
    syncAppUpdateUi();
    return;
  }

  appUpdateBusy = true;
  setAppUpdateStatus(`Installing ${appUpdateInfo.version}...`, 'success');
  setAppUpdatePhase('Downloading installer');
  setAppUpdateProgress(0, 1, 'Downloading the installer to your temp folder...');
  syncAppUpdateUi();

  try {
    await invoke('install_app_update', {
      url: JSON.stringify({ assetId, assetName }),
    });
    setAppUpdatePhase('Closing app');
    setAppUpdateProgress(1, 1, 'Installer launched. Closing the app...');
    setAppUpdateModalOpen(false);
  } catch (err) {
    setAppUpdateStatus('Could not install update', 'error');
    setAppUpdatePhase('Install failed');
    setAppUpdateProgress(null, null, err?.message || String(err));
  } finally {
    appUpdateBusy = false;
    syncAppUpdateUi();
  }
}

appUpdateCheckBtn?.addEventListener('click', () => {
  void checkForAppUpdate({ openModalOnAvailable: true });
});
appUpdateInstallBtn?.addEventListener('click', () => { void openAppUpdateDownload(); });
appUpdateLaterBtn?.addEventListener('click', () => {
  if (!appUpdateBusy) setAppUpdateModalOpen(false);
});

function setNwwsCredentialsStatus(text = '', isError = false) {
  const next = text || '';
  [nwwsCredentialsStatus, nwwsLoginStatus].forEach(el => {
    if (!el) return;
    el.textContent = next;
    el.classList.toggle('error', !!next && isError);
    el.classList.toggle('success', !!next && !isError);
  });
  const badge = document.getElementById('settings-nwws-badge');
  if (badge) {
    const isConnected = next.toLowerCase().includes('connected') && !isError;
    badge.textContent = isConnected ? 'Connected' : (next || 'Not configured');
    badge.classList.toggle('connected', isConnected);
    badge.classList.toggle('error', isError);
  }
}

function syncNwwsSettingsUi() {
  const creds = _getNwwsBridgeCredentials();
  const useNwws = _shouldUseNwwsBridge();
  const useNwsApi = _shouldUseNwsApiAlerts();
  if (nwwsUsernameInput && nwwsUsernameInput.value !== nwwsUsername) {
    nwwsUsernameInput.value = nwwsUsername || '';
  }
  if (nwwsPasswordInput && nwwsPasswordInput.value !== nwwsPassword) {
    nwwsPasswordInput.value = nwwsPassword || '';
  }
  const settingsUserInput = document.getElementById('settings-nwws-username');
  const settingsPassInput = document.getElementById('settings-nwws-password');
  if (settingsUserInput && settingsUserInput.value !== nwwsUsername) settingsUserInput.value = nwwsUsername || '';
  if (settingsPassInput && settingsPassInput.value !== nwwsPassword) settingsPassInput.value = nwwsPassword || '';
  if (toggleNwwsAlerts) toggleNwwsAlerts.checked = nwwsEnabled;
  if (toggleNwsApiAlerts) {
    toggleNwsApiAlerts.checked = useNwws ? true : nwsApiEnabled;
    toggleNwsApiAlerts.disabled = useNwws;
  }
  nwsApiSourceRow?.classList.toggle('disabled', useNwws);
  if (nwsApiSourceStatus) {
    if (useNwws) {
      nwsApiSourceStatus.textContent = 'Startup only';
      nwsApiSourceStatus.classList.remove('error');
      nwsApiSourceStatus.classList.add('success');
    } else if (useNwsApi) {
      nwsApiSourceStatus.textContent = 'Active';
      nwsApiSourceStatus.classList.remove('error');
      nwsApiSourceStatus.classList.add('success');
    } else {
      nwsApiSourceStatus.textContent = 'Off';
      nwsApiSourceStatus.classList.toggle('error', alertsVisible);
      nwsApiSourceStatus.classList.remove('success');
    }
  }
  if (!nwwsCredentialsStatus?.textContent) {
    if (!nwwsEnabled) setNwwsCredentialsStatus('Disabled');
    else setNwwsCredentialsStatus(creds.configured ? 'Saved locally' : 'Missing credentials');
  }
}

async function saveNwwsCredentialsAndReconnect() {
  nwwsUsername = _normalizeNwwsCredential(nwwsUsernameInput?.value || '');
  nwwsPassword = _normalizeNwwsCredential(nwwsPasswordInput?.value || '');
  saveSettings();
  syncNwwsSettingsUi();
  nwwsFatalStopInFlight = false;
  setNwwsCredentialsStatus(_getNwwsBridgeCredentials().configured ? 'Saving and reconnecting...' : 'Missing credentials');
  try {
    await invoke('stop_nwws_bridge');
  } catch (_) {}
  nwwsBridgeStartPromise = null;
  nwwsLastStatusSig = '';
  nwwsLastAlertsGeneratedAt = '';
  _resetWarningNotificationPriming();
  applyAlertSourceMode();
}

function formatCacheBytes(bytes) {
  const size = Number(bytes) || 0;
  if (size <= 0) return '0 B';
  const units = ['B', 'KB', 'MB', 'GB'];
  let value = size;
  let unitIdx = 0;
  while (value >= 1024 && unitIdx < units.length - 1) {
    value /= 1024;
    unitIdx += 1;
  }
  const digits = unitIdx === 0 ? 0 : (value >= 100 ? 0 : 1);
  return `${value.toFixed(digits)} ${units[unitIdx]}`;
}

