function _cameraProtectedCacheGet(key) {
  const cacheKey = String(key || '').trim();
  if (!cacheKey) return null;
  const entry = _cameraProtectedStreamCache.get(cacheKey);
  if (!entry) return null;
  if (!Number.isFinite(entry.expiresAt) || entry.expiresAt <= Date.now()) {
    _cameraProtectedStreamCache.delete(cacheKey);
    return null;
  }
  return { ...entry.value };
}

function _cameraProtectedCacheSet(key, value, ttlMs = CAMERA_PROTECTED_STREAM_CACHE_MS) {
  const cacheKey = String(key || '').trim();
  if (!cacheKey || !value || typeof value !== 'object') return;
  _cameraProtectedStreamCache.set(cacheKey, {
    expiresAt: Date.now() + Math.max(5_000, Number(ttlMs) || CAMERA_PROTECTED_STREAM_CACHE_MS),
    value: { ...value },
  });
}

function _cameraStripTokenParam(url) {
  const raw = String(url || '').trim();
  if (!raw) return '';
  try {
    const parsed = new URL(raw);
    parsed.searchParams.delete('token');
    return parsed.toString();
  } catch (_) {
    return raw
      .replace(/([?&])token=[^&]*/i, '$1')
      .replace(/[?&]$/, '');
  }
}

function _cameraTrimSerializableList(list) {
  if (!Array.isArray(list) || !list.length) return '';
  const trimmed = list
    .map(item => {
      if (item == null) return null;
      if (typeof item === 'string' || typeof item === 'number' || typeof item === 'boolean') return item;
      if (typeof item === 'object') {
        const next = _cameraTrimPayload(item);
        return Object.keys(next).length ? next : null;
      }
      return null;
    })
    .filter(Boolean);
  if (!trimmed.length) return '';
  try {
    return JSON.stringify(trimmed);
  } catch (_) {
    return '';
  }
}

function _cameraTrimPayload(props = {}) {
  const payload = {};
  CAMERA_PAYLOAD_KEYS.forEach(key => {
    if (!Object.prototype.hasOwnProperty.call(props, key)) return;
    const value = props[key];
    if (value == null) return;
    if (key === 'cameras' || key === 'views' || key === 'cameraViews') {
      if (typeof value === 'string') {
        const s = value.trim();
        if (s) payload[key] = s;
        return;
      }
      const serialized = _cameraTrimSerializableList(value);
      if (serialized) payload[key] = serialized;
      return;
    }
    if (key === 'm3u8_urls' || key === 'jpg_urls') {
      if (typeof value === 'string') {
        const s = value.trim();
        if (s) payload[key] = s;
        return;
      }
      if (Array.isArray(value)) {
        const compact = value
          .map(item => String(item || '').trim())
          .filter(Boolean);
        if (!compact.length) return;
        try {
          payload[key] = JSON.stringify(compact);
        } catch (_) {}
      }
      return;
    }
    if (typeof value === 'string') {
      if (value.trim()) payload[key] = value;
      return;
    }
    if (typeof value === 'number' || typeof value === 'boolean') {
      payload[key] = value;
    }
  });
  if (Object.prototype.hasOwnProperty.call(props, '_has_video')) {
    payload._has_video = Number(props._has_video) ? 1 : 0;
  } else if (_cameraFeatureHasVideo(props)) {
    payload._has_video = 1;
  }
  return payload;
}

function _cameraPayloadKindSet(kind) {
  return cameraPayloadIdsByKind[kind] || null;
}

function _cameraPayloadKey(kind, feature, index = 0) {
  const props = feature?.properties || {};
  const coords = feature?.geometry?.coordinates;
  const coordKey = Array.isArray(coords) && coords.length >= 2
    ? `${Number(coords[0]).toFixed(5)},${Number(coords[1]).toFixed(5)}`
    : `idx-${index}`;
  const rawId = feature?.id
    ?? props.id
    ?? props.cameraId
    ?? props.uuid
    ?? props.siteId
    ?? props.site_id
    ?? props.camera_uri
    ?? props.imageId
    ?? props.image_id
    ?? props.view_id
    ?? props.name
    ?? coordKey;
  return `${kind}:${String(rawId || coordKey)}`;
}

function _clearCameraPayloadKind(kind) {
  const ids = _cameraPayloadKindSet(kind);
  if (!ids) return;
  ids.forEach(id => cameraPayloadById.delete(id));
  ids.clear();
}

function _ingestCameraFeatureSet(kind, rawFeatures) {
  _clearCameraPayloadKind(kind);
  const ids = _cameraPayloadKindSet(kind);
  const renderFeatures = [];
  const src = Array.isArray(rawFeatures) ? rawFeatures : [];
  src.forEach((feature, index) => {
    const coords = feature?.geometry?.coordinates;
    if (!Array.isArray(coords) || coords.length < 2) return;
    const props = feature?.properties || {};
    const payloadId = _cameraPayloadKey(kind, feature, index);
    const payload = _cameraTrimPayload(props);
    if (!payload.id && feature?.id != null) payload.id = feature.id;
    payload._camera_id = payloadId;
    cameraPayloadById.set(payloadId, payload);
    ids?.add(payloadId);
    renderFeatures.push({
      type: 'Feature',
      id: payloadId,
      geometry: {
        type: 'Point',
        coordinates: [Number(coords[0]), Number(coords[1])],
      },
      properties: {
        _camera_id: payloadId,
        _state: String(props._state || '').trim().toUpperCase(),
        _has_video: Number(payload._has_video) ? 1 : 0,
      },
    });
  });
  return renderFeatures;
}

function _cameraPayloadFromFeature(featureOrProps) {
  const props = featureOrProps?.properties || featureOrProps || {};
  const payloadId = String(props?._camera_id || '').trim();
  if (payloadId && cameraPayloadById.has(payloadId)) return cameraPayloadById.get(payloadId);
  return props;
}

const US_STATE_NAME_TO_ABBR = {
  ALABAMA: 'AL', ALASKA: 'AK', ARIZONA: 'AZ', ARKANSAS: 'AR', CALIFORNIA: 'CA',
  COLORADO: 'CO', CONNECTICUT: 'CT', DELAWARE: 'DE', FLORIDA: 'FL', GEORGIA: 'GA',
  HAWAII: 'HI', IDAHO: 'ID', ILLINOIS: 'IL', INDIANA: 'IN', IOWA: 'IA',
  KANSAS: 'KS', KENTUCKY: 'KY', LOUISIANA: 'LA', MAINE: 'ME', MARYLAND: 'MD',
  MASSACHUSETTS: 'MA', MICHIGAN: 'MI', MINNESOTA: 'MN', MISSISSIPPI: 'MS', MISSOURI: 'MO',
  MONTANA: 'MT', NEBRASKA: 'NE', NEVADA: 'NV', 'NEW HAMPSHIRE': 'NH', 'NEW JERSEY': 'NJ',
  'NEW MEXICO': 'NM', 'NEW YORK': 'NY', 'NORTH CAROLINA': 'NC', 'NORTH DAKOTA': 'ND', OHIO: 'OH',
  OKLAHOMA: 'OK', OREGON: 'OR', PENNSYLVANIA: 'PA', 'RHODE ISLAND': 'RI', 'SOUTH CAROLINA': 'SC',
  'SOUTH DAKOTA': 'SD', TENNESSEE: 'TN', TEXAS: 'TX', UTAH: 'UT', VERMONT: 'VT',
  VIRGINIA: 'VA', WASHINGTON: 'WA', 'WEST VIRGINIA': 'WV', WISCONSIN: 'WI', WYOMING: 'WY',
  'DISTRICT OF COLUMBIA': 'DC',
};

const CAMERA_ALLOWED_STATE_CODES = new Set([
  'AL', 'AK', 'AZ', 'AR', 'CA', 'CO', 'CT', 'DE', 'FL', 'GA',
  'HI', 'ID', 'IL', 'IN', 'IA', 'KS', 'KY', 'LA', 'ME', 'MD',
  'MA', 'MI', 'MN', 'MS', 'MO', 'MT', 'NE', 'NV', 'NH', 'NJ',
  'NM', 'NY', 'NC', 'ND', 'OH', 'OK', 'OR', 'PA', 'RI', 'SC',
  'SD', 'TN', 'TX', 'UT', 'VT', 'VA', 'WA', 'WV', 'WI', 'WY',
  'DC', 'PR', 'VI', 'GU', 'AS', 'MP', 'AA', 'AE', 'AP',
]);

function _normalizeUsState(raw) {
  const s = String(raw || '').trim().replace(/\./g, '');
  if (!s) return '';
  if (/^[A-Za-z]{2}$/.test(s)) {
    const code = s.toUpperCase();
    return CAMERA_ALLOWED_STATE_CODES.has(code) ? code : '';
  }
  const up = s.toUpperCase().replace(/\s+/g, ' ');
  const code = US_STATE_NAME_TO_ABBR[up] || '';
  return CAMERA_ALLOWED_STATE_CODES.has(code) ? code : '';
}

function _extractStateCode(text) {
  const s = String(text || '').trim();
  if (!s) return '';
  const direct = _normalizeUsState(s);
  if (direct) return direct;

  const parts = s.split(',').map(p => p.trim()).filter(Boolean);
  for (let i = parts.length - 1; i >= 0; i -= 1) {
    const part = parts[i];
    const n = _normalizeUsState(part);
    if (n) return n;
    const words = part.split(/[^A-Za-z]+/).filter(Boolean);
    for (let j = 0; j < words.length; j += 1) {
      const one = _normalizeUsState(words[j]);
      if (one) return one;
      if (j + 1 < words.length) {
        const two = _normalizeUsState(`${words[j]} ${words[j + 1]}`);
        if (two) return two;
      }
      if (j + 2 < words.length) {
        const three = _normalizeUsState(`${words[j]} ${words[j + 1]} ${words[j + 2]}`);
        if (three) return three;
      }
    }
  }

  return '';
}

function _cameraStateFromSources(...sources) {
  for (const src of sources) {
    const state = _extractStateCode(src);
    if (state) return state;
  }
  return '';
}

function _cameraParseViews(rawViews) {
  if (Array.isArray(rawViews)) return rawViews;
  if (typeof rawViews !== 'string') return [];
  try {
    const parsed = JSON.parse(rawViews);
    return Array.isArray(parsed) ? parsed : [];
  } catch (_) {
    return [];
  }
}

function _cameraViewHasVideo(view, props = {}) {
  if (!view) return false;
  if (typeof view === 'string') return _isLikelyVideoStreamUrl(view);
  if (typeof view !== 'object') return false;

  const state = String(props?._state || props?.state || '').trim().toUpperCase();
  const directUrls = [
    view.url,
    view.video_url,
    view.m3u8Url,
    view.m3u8_url,
    view.dash_url,
    view.streamingURL,
    view.streamingVideoURL,
    view.html,
  ];
  if (directUrls.some(url => _isLikelyVideoStreamUrl(url))) return true;

  const viewUrl = String(view.url || view.image_url || '').trim();
  if (state === 'WI' && /511wi\.gov\/map\/Cctv\/\d+/i.test(viewUrl)) return true;

  const preview = String(
    view.videoPreviewUrl
    || view.preview_url
    || view.snapshot_url
    || view.thumbnail
    || view.jpg_url
    || ''
  ).trim();
  const type = String(view.type || view.mediaType || '').trim().toUpperCase();
  if (preview && (!type || !/(?:STILL|IMAGE|SNAPSHOT|JPEG|JPG|PNG)/.test(type))) return true;

  return false;
}

function _cameraHasKnownBrokenStreamUrl(props = {}) {
  return [props.url2, props.URL2, props.url, props.html].some(value =>
    /traveler\.modot\.org\/tisvc\/api\/tms\/camerastream\/?$/i.test(String(value || '').trim())
  );
}

function _cameraFeatureHasVideo(props = {}) {
  if (!props || typeof props !== 'object') return false;

  const definiteStreamFields = [
    props.dash_url,
    props.mpd_url,
    props.dash,
    props.hls_url,
    props.streamingURL,
    props.streamingVideoURL,
    props.m3u8Url,
    props.m3u8_url,
    props.m3u8,
    props.hls_stream_protected,
    props.streamSrc,
    props.httpsVideoUrl,
    props.httpVideoUrl,
    props.https_url,
    props.ios_url,
    props.stream_url,
    props.video_url,
    props.videoUrl,
  ];
  if (definiteStreamFields.some(v => String(v || '').trim())) return true;
  if ([props.url2, props.URL2, props.url, props.html].some(v => _isLikelyVideoStreamUrl(v))) return true;

  const grouped = props.cameras;
  if (grouped) {
    try {
      const cams = typeof grouped === 'string' ? JSON.parse(grouped) : grouped;
      if (Array.isArray(cams) && cams.some(cam => _cameraFeatureHasVideo(cam))) return true;
    } catch (_) {}
  }

  const views = _cameraParseViews(props.views);
  if (views.some(view => _cameraViewHasVideo(view, props))) return true;

  const videoAuth = props.videoauth;
  if (videoAuth === true || String(videoAuth || '').toLowerCase() === 'true') return true;

  const imageUrl = String(props.image_url || props.imageUrl || '').trim();
  const imageId = String(props.imageId || props.image_id || '').trim();
  const viewId = String(props.view_id || '').trim();
  if (imageId && String(props._state || '').toUpperCase() === 'GA') return true;
  if (viewId && /511pa\.com\/map\/Cctv\/\d+/i.test(imageUrl)) return true;
  if (/511ga\.org\/map\/Cctv\/\d+/i.test(imageUrl)) return true;
  if (/511ny\.org\/map\/Cctv\/\d+/i.test(imageUrl)) return true;
  if (/511pa\.com\/map\/Cctv\/\d+/i.test(imageUrl)) return true;
  if (/fl511\.com\/map\/Cctv\/\d+/i.test(imageUrl)) return true;

  return false;
}

function _cameraResolvedHasVideo(props = {}) {
  if (Object.prototype.hasOwnProperty.call(props, '_has_video')) {
    return Number(props?._has_video) ? 1 : 0;
  }
  if (_cameraHasKnownBrokenStreamUrl(props)) return 0;
  if (_cameraFeatureHasVideo(props)) return 1;
  return 0;
}

function _ensureTrafficCameraWorker() {
  if (_trafficCameraWorker) return _trafficCameraWorker;
  _trafficCameraWorker = new Worker('./camera-worker.js');
  _trafficCameraWorker.onmessage = ev => {
    const { id, features, error } = ev?.data || {};
    const pending = _trafficCameraWorkerPending.get(id);
    if (!pending) return;
    _trafficCameraWorkerPending.delete(id);
    if (error) pending.reject(new Error(error));
    else pending.resolve(Array.isArray(features) ? features : []);
  };
  _trafficCameraWorker.onerror = ev => {
    const msg = ev?.message || 'camera worker error';
    for (const pending of _trafficCameraWorkerPending.values()) {
      pending.reject(new Error(msg));
    }
    _trafficCameraWorkerPending.clear();
    _trafficCameraWorker = null;
  };
  return _trafficCameraWorker;
}

function _disposeTrafficCameraWorker() {
  for (const pending of _trafficCameraWorkerPending.values()) {
    try { pending.reject(new Error('camera worker disposed')); } catch (_) {}
  }
  if (_trafficCameraWorker) {
    try { _trafficCameraWorker.terminate(); } catch (_) {}
    _trafficCameraWorker = null;
  }
  _trafficCameraWorkerPending.clear();
}

function _composeTrafficCameraFeaturesOffMain(datasets = {}) {
  const id = ++_trafficCameraWorkerSeq;
  return new Promise((resolve, reject) => {
    _trafficCameraWorkerPending.set(id, { resolve, reject });
    _ensureTrafficCameraWorker().postMessage({ id, datasets });
  });
}

function _rebuildKnownCameraStates() {
  const set = new Set();
  const gather = list => {
    if (!Array.isArray(list)) return;
    list.forEach(f => {
      const state = String(f?.properties?._state || '').trim().toUpperCase();
      if (CAMERA_ALLOWED_STATE_CODES.has(state)) set.add(state);
    });
  };
  gather(trafficCameraFeatures);
  gather(weatherCameraFeatures);
  gather(wxwiseChaserFeatures);
  gather(roChaserFeatures);
  const next = [...set].sort();
  cameraKnownStates = next;
  if (cameraStateFilter !== 'ALL' && !set.has(cameraStateFilter)) {
    cameraStateFilter = 'ALL';
  }
}

function _isMapReadyForCameraLayers() {
  try {
    if (!map || typeof map.getStyle !== 'function') return false;
    const style = map.getStyle();
    return !!style && Array.isArray(style.layers);
  } catch (_) {
    return false;
  }
}

function _setCameraLayerVisible(layerId, visible) {
  _overlayMaps().forEach(m => {
    if (m.getLayer(layerId)) m.setLayoutProperty(layerId, 'visibility', visible ? 'visible' : 'none');
  });
}

function _cameraStateFilterExpr() {
  const clauses = [];
  if (cameraStateFilter !== 'ALL') {
    clauses.push(['==', ['coalesce', ['get', '_state'], ''], cameraStateFilter]);
  }
  if (cameraVideoOnly) {
    clauses.push(['==', ['coalesce', ['get', '_has_video'], 0], 1]);
  }
  if (!clauses.length) return null;
  if (clauses.length === 1) return clauses[0];
  return ['all', ...clauses];
}

function _applyCameraStateFilter() {
  const expr = _cameraStateFilterExpr();
  _overlayMaps().forEach(m => {
    [TRAFFIC_CAMERA_LAYER_ID, WEATHER_CAMERA_LAYER_ID, WXWISE_CHASER_LAYER_ID, RO_CHASER_LAYER_ID].forEach(layerId => {
      if (m.getLayer(layerId)) {
        try { m.setFilter(layerId, expr); } catch (_) {}
      }
    });
  });
}

function _cameraPointFeature(lon, lat, props = {}, id = '') {
  const featureProps = { ...(props || {}) };
  featureProps._has_video = _cameraResolvedHasVideo(featureProps);
  return {
    type: 'Feature',
    id: id || undefined,
    geometry: { type: 'Point', coordinates: [lon, lat] },
    properties: featureProps,
  };
}

function _cameraCoords(feature) {
  const coords = feature?.geometry?.coordinates;
  if (!Array.isArray(coords) || coords.length < 2) return null;
  const lon = Number(coords[0]);
  const lat = Number(coords[1]);
  if (!Number.isFinite(lon) || !Number.isFinite(lat)) return null;
  return [lon, lat];
}

function _bindCameraLayerEvents(layerId) {
  if (cameraLayerEventsBound.has(layerId)) return;
  cameraLayerEventsBound.add(layerId);
  _bindCameraLayerEventsOnMap(layerId, map);
}

function _ensureCameraIconOnMap(m) {
  if (m.hasImage(TRAFFIC_CAMERA_ICON_NAME)) return;
  const size = 30;
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');
  // Blue filled circle with white stroke (WeatherWise camera marker style)
  ctx.beginPath();
  ctx.arc(size / 2, size / 2, size / 2 - 1, 0, Math.PI * 2);
  ctx.fillStyle = '#3b82f6';
  ctx.fill();
  ctx.strokeStyle = 'white';
  ctx.lineWidth = 1.5;
  ctx.stroke();
  // mdi:video path (video camera icon), scaled to fit inside circle
  const camPath = new Path2D('M17,10.5V7A1,1 0 0,0 16,6H4A1,1 0 0,0 3,7V17A1,1 0 0,0 4,18H16A1,1 0 0,0 17,17V13.5L21,17.5V6.5L17,10.5Z');
  const scale = (size - 10) / 21;
  ctx.save();
  ctx.translate((size - 21 * scale) / 2, (size - 18 * scale) / 2);
  ctx.scale(scale, scale);
  ctx.fillStyle = 'white';
  ctx.fill(camPath);
  ctx.restore();
  try { m.addImage(TRAFFIC_CAMERA_ICON_NAME, ctx.getImageData(0, 0, size, size)); } catch (e) { console.warn('[Camera] addImage failed:', e); }
}

function _addTrafficCameraIconLayer(sourceId, layerId, data) {
  _overlayMaps().forEach(m => {
    if (m.getSource(sourceId)) {
      m.getSource(sourceId)?.setData(data);
    } else {
      m.addSource(sourceId, { type: 'geojson', data });
      m.addLayer({
        id: layerId, type: 'circle', source: sourceId,
        layout: { 'visibility': 'none' },
        paint: { 'circle-radius': ['interpolate', ['linear'], ['zoom'], 4, 3, 10, 5], 'circle-color': '#3b82f6', 'circle-stroke-color': '#fff', 'circle-stroke-width': 1.2, 'circle-opacity': 0.95 },
      }, m.getLayer('stations-dot') ? 'stations-dot' : undefined);
      _bindCameraLayerEventsOnMap(layerId, m);
    }
  });
}

function _addCameraPointLayer(sourceId, layerId, data, color) {
  _overlayMaps().forEach(m => {
    if (m.getSource(sourceId)) {
      m.getSource(sourceId)?.setData(data);
    } else {
      m.addSource(sourceId, { type: 'geojson', data });
      m.addLayer({
        id: layerId,
        type: 'circle',
        source: sourceId,
        layout: { visibility: 'none' },
        paint: {
          'circle-radius': ['interpolate', ['linear'], ['zoom'], 4, 3, 10, 5],
          'circle-color': color,
          'circle-stroke-color': '#fff',
          'circle-stroke-width': 1.2,
          'circle-opacity': 0.95,
        },
      }, m.getLayer('stations-dot') ? 'stations-dot' : undefined);
      _bindCameraLayerEventsOnMap(layerId, m);
    }
  });
}

function _replaceCameraPointLayer(sourceId, layerId, data, color) {
  _overlayMaps().forEach(m => {
    if (m.getLayer(layerId)) { try { m.removeLayer(layerId); } catch (_) {} }
    if (m.getSource(sourceId)) { try { m.removeSource(sourceId); } catch (_) {} }
    m.addSource(sourceId, { type: 'geojson', data });
    m.addLayer({
      id: layerId,
      type: 'circle',
      source: sourceId,
      layout: { visibility: 'none' },
      paint: {
        'circle-radius': ['interpolate', ['linear'], ['zoom'], 4, 3, 10, 5],
        'circle-color': color,
        'circle-stroke-color': '#fff',
        'circle-stroke-width': 1.2,
        'circle-opacity': 0.95,
      },
    }, m.getLayer('stations-dot') ? 'stations-dot' : undefined);
    _bindCameraLayerEventsOnMap(layerId, m);
  });
}

function _applyCameraSourcesBatch(kinds = null) {
  if (!_isMapReadyForCameraLayers()) return;
  const applyTraffic = !kinds || kinds.traffic;
  const applyWeather = !kinds || kinds.weather;
  const applyChasers = !kinds || kinds.chasers;

  if (applyTraffic && trafficCameraFeatures.length) {
    _addTrafficCameraIconLayer(
      TRAFFIC_CAMERA_SOURCE_ID,
      TRAFFIC_CAMERA_LAYER_ID,
      { type: 'FeatureCollection', features: trafficCameraFeatures },
    );
  }
  if (applyWeather && weatherCameraFeatures.length) {
    _addCameraPointLayer(
      WEATHER_CAMERA_SOURCE_ID,
      WEATHER_CAMERA_LAYER_ID,
      { type: 'FeatureCollection', features: weatherCameraFeatures },
      '#22c55e',
    );
  }
  if (applyChasers && wxwiseChasersLoaded) {
    _addCameraPointLayer(
      WXWISE_CHASER_SOURCE_ID,
      WXWISE_CHASER_LAYER_ID,
      { type: 'FeatureCollection', features: wxwiseChaserFeatures },
      '#ef4444',
    );
  }
  if (applyChasers && roChasersLoaded) {
    _addCameraPointLayer(
      RO_CHASER_SOURCE_ID,
      RO_CHASER_LAYER_ID,
      { type: 'FeatureCollection', features: roChaserFeatures },
      '#ef4444',
    );
  }

  _rebuildKnownCameraStates();
  _applyCameraStateFilter();
  setCamerasVisible(camerasOverlayVisible && _cameraFilterEnabled('traffic'));
  setWeatherCamerasVisible(camerasOverlayVisible && _cameraFilterEnabled('weather'));
  syncCameraFilterUi();
}

function _clearLoadedCameraData() {
  trafficCameraFeatures = [];
  weatherCameraFeatures = [];
  wxwiseChaserFeatures = [];
  roChaserFeatures = [];
  trafficCamerasLoaded = false;
  weatherCamerasLoaded = false;
  wxwiseChasersLoaded = false;
  roChasersLoaded = false;
  cameraKnownStates = [];
  _clearCameraPayloadKind('traffic');
  _clearCameraPayloadKind('weather');
  _clearCameraPayloadKind('wxwise');
  _clearCameraPayloadKind('ro');
  _disposeTrafficCameraWorker();
  _overlayMaps().forEach(m => {
    m.getSource(TRAFFIC_CAMERA_SOURCE_ID)?.setData(CAMERA_EMPTY_GEOJSON);
    m.getSource(WEATHER_CAMERA_SOURCE_ID)?.setData(CAMERA_EMPTY_GEOJSON);
    m.getSource(WXWISE_CHASER_SOURCE_ID)?.setData(CAMERA_EMPTY_GEOJSON);
    m.getSource(RO_CHASER_SOURCE_ID)?.setData(CAMERA_EMPTY_GEOJSON);
  });
}

function _scheduleCameraSourceApply(kinds = { traffic: true, weather: true, chasers: true }) {
  _cameraApplyPendingKinds.traffic ||= kinds.traffic === true;
  _cameraApplyPendingKinds.weather ||= kinds.weather === true;
  _cameraApplyPendingKinds.chasers ||= kinds.chasers === true;
  if (_cameraApplyQueued) return;
  _cameraApplyQueued = true;
  requestAnimationFrame(() => {
    _cameraApplyQueued = false;
    const nextKinds = {
      traffic: _cameraApplyPendingKinds.traffic,
      weather: _cameraApplyPendingKinds.weather,
      chasers: _cameraApplyPendingKinds.chasers,
    };
    _cameraApplyPendingKinds.traffic = false;
    _cameraApplyPendingKinds.weather = false;
    _cameraApplyPendingKinds.chasers = false;
    _applyCameraSourcesBatch(nextKinds);
  });
}

function _applyChaserSources(reason = 'poll') {
  if (!_isMapReadyForCameraLayers()) return;
  if (wxwiseChasersLoaded) {
    _addCameraPointLayer(
      WXWISE_CHASER_SOURCE_ID,
      WXWISE_CHASER_LAYER_ID,
      { type: 'FeatureCollection', features: wxwiseChaserFeatures },
      '#ef4444',
    );
  }
  if (roChasersLoaded) {
    _addCameraPointLayer(
      RO_CHASER_SOURCE_ID,
      RO_CHASER_LAYER_ID,
      { type: 'FeatureCollection', features: roChaserFeatures },
      '#ef4444',
    );
  }
  _rebuildKnownCameraStates();
  _applyCameraStateFilter();
  const showChasers = camerasOverlayVisible && _cameraFilterEnabled('chasers');
  setWxWiseChasersVisible(showChasers);
  setRadarOmegaChasersVisible(showChasers);
  syncCameraFilterUi();
}

function isOklahomaCameraFeature(feature) {
  const p = feature.properties || {};
  const state = (p.state || p.State || '').toLowerCase();
  if (state === 'oklahoma' || state === 'ok') return true;
  return Object.values(p).some(v =>
    typeof v === 'string' && (v.includes('oktraffic.org') || v.includes('oktrafficradar.org'))
  );
}

function isKentuckyCameraFeature(feature) {
  const p = feature?.properties || {};
  const source = String(p.source || p.Source || '').toUpperCase();
  if (source.includes('KYTC') || source.includes('TRIMARC')) return true;
  return _cameraStateFromSources(
    p.state,
    p.State,
    p.state_name,
    p.county,
    p.location,
    p.description,
    p.name,
  ) === 'KY';
}

function isAlabamaCameraFeature(feature) {
  const p = feature?.properties || {};
  const blob = JSON.stringify({
    state: p.state || p.State || '',
    source_file: p._source_file || '',
    permalink: p.permalink || p.permLink || '',
    snapshot_url: p.snapshot_url || p.snapshotImageUrl || '',
    map_image_url: p.map_image_url || p.mapImageUrl || '',
  }).toLowerCase();
  return blob.includes('alabama')
    || blob.includes('algotraffic.com')
    || blob.includes('/v4/cameras/');
}

function isGeorgiaCameraFeature(feature) {
  const p = feature?.properties || {};
  const state = _cameraStateFromSources(
    p.state,
    p.State,
    p.state_name,
    p.county,
    p.city,
    p.location,
    p.title,
    p.name,
  );
  if (state === 'GA') return true;
  return Object.values(p).some(v => {
    if (typeof v !== 'string') return false;
    const s = v.toLowerCase();
    return s.includes('navigator.dot.ga.gov')
      || s.includes('511ga.org/map/cctv/')
      || s.includes('511ga.org');
  });
}

function isIndianaCameraFeature(feature) {
  const p = feature?.properties || {};
  const state = _cameraStateFromSources(
    p.state,
    p.State,
    p.state_name,
    p.county,
    p.city,
    p.location,
    p.title,
    p.name,
  );
  if (state === 'IN') return true;
  return Object.values(p).some(v => {
    if (typeof v !== 'string') return false;
    const s = v.toLowerCase();
    return s.includes('public.carsprogram.org/cameras/in/')
      || s.includes('indot_')
      || s.includes('511in.org')
      || s.includes('indiana');
  });
}

function isIowaCameraFeature(feature) {
  const p = feature?.properties || {};
  const state = _cameraStateFromSources(
    p.state,
    p.State,
    p.state_name,
    p.county,
    p.city,
    p.location,
    p.title,
    p.name,
    p.source,
  );
  if (state === 'IA') return true;
  return Object.values(p).some(v => {
    if (typeof v !== 'string') return false;
    const s = v.toLowerCase();
    return s.includes('iowadot')
      || s.includes('iowadotsnapshot')
      || s.includes('511ia')
      || s.includes('iowa');
  });
}

function isColoradoCameraFeature(feature) {
  const p = feature?.properties || {};
  const state = _cameraStateFromSources(
    p.state,
    p.State,
    p.state_name,
    p.county,
    p.city,
    p.location,
    p.title,
    p.name,
  );
  if (state === 'CO') return true;
  return Object.values(p).some(v => {
    if (typeof v !== 'string') return false;
    const s = v.toLowerCase();
    return s.includes('cotrip')
      || s.includes('cocam.carsprogram.org')
      || s.includes('publicstreamer');
  });
}

function isMississippiCameraFeature(feature) {
  const p = feature?.properties || {};
  const state = _cameraStateFromSources(
    p.state,
    p.State,
    p.state_abbr,
    p.iso_3166_2,
    p.county,
    p.city,
    p.location,
    p.description,
    p.name,
  );
  if (state !== 'MS') return false;
  return Object.values(p).some(v => {
    if (typeof v !== 'string') return false;
    const s = v.toLowerCase();
    return s.includes('mdottraffic.com')
      || s.includes('trafficvision.live')
      || s.includes('mississippi dot')
      || s.includes('mdot');
  });
}

function isHawaiiCameraFeature(feature) {
  const p = feature?.properties || {};
  const state = _cameraStateFromSources(
    p.state,
    p.State,
    p.state_name,
    p.description,
    p.location,
    p.name,
    p.source,
    p._source_file,
  );
  if (state === 'HI') return true;
  return Object.values(p).some(v => {
    if (typeof v !== 'string') return false;
    const s = v.toLowerCase();
    return s.includes('goakamai')
      || s.includes('cctv.cdn.goakamai.org');
  });
}

function _normalizeTrimarcSnapshotUrl(url) {
  const s = String(url || '').trim();
  if (!s) return '';
  return s.replace(/^http:\/\//i, 'https://');
}

function _buildKentuckyTrimarcFeatures(raw) {
  const items = Array.isArray(raw) ? raw : [];
  const features = [];
  for (const item of items) {
    const status = String(item?.status || '').trim().toLowerCase();
    const snapshot = _normalizeTrimarcSnapshotUrl(item?.snapshot);
    const lat = Number(item?.latitude);
    const lon = Number(item?.longitude);
    if (status !== 'online' || !snapshot || !Number.isFinite(lat) || !Number.isFinite(lon)) continue;
    features.push(_cameraPointFeature(lon, lat, {
      state: 'Kentucky',
      source: 'KYTC',
      id: item?.id ?? '',
      name: item?.name || 'Traffic Camera',
      description: item?.description || '',
      direction: item?.direction || '',
      highway: item?.highway || '',
      milemarker: item?.mileMarker || item?.milemarker || '',
      snapshot,
      snapshot_name: item?.snapshot_name || '',
      latitude: lat,
      longitude: lon,
      status: 'Online',
      _state: 'KY',
    }, String(item?.id || item?.name || snapshot)));
  }
  return features;
}

function _buildAlabamaAlgoTrafficFeatures(raw) {
  const items = Array.isArray(raw) ? raw : [];
  const features = [];
  for (const item of items) {
    const loc = item?.location || {};
    const lat = Number(loc?.latitude);
    const lon = Number(loc?.longitude);
    const hls = String(item?.playbackUrls?.hls || '').trim();
    if (!Number.isFinite(lat) || !Number.isFinite(lon) || !hls) continue;

    const route = String(loc?.displayRouteDesignator || loc?.routeDesignator || '').trim();
    const cross = String(loc?.displayCrossStreet || loc?.crossStreet || '').trim();
    const mile = Number(loc?.linearReference);
    const crossLabel = cross || (Number.isFinite(mile) ? `MM ${mile}` : '');
    const name = [route, crossLabel].filter(Boolean).join(' @ ') || `Camera ${item?.id ?? ''}`.trim();

    features.push(_cameraPointFeature(lon, lat, {
      id: item?.id ?? '',
      name,
      location: name,
      hls_url: hls,
      dash_url: String(item?.playbackUrls?.dash || '').trim(),
      snapshot_url: String(item?.snapshotImageUrl || '').trim(),
      map_image_url: String(item?.mapImageUrl || '').trim(),
      city: String(loc?.city || '').trim(),
      county: String(loc?.county || '').trim(),
      route: route,
      cross_street: crossLabel,
      direction: String(loc?.direction || '').trim(),
      milepost: Number.isFinite(mile) ? mile : '',
      responsibleRegion: String(item?.responsibleRegion || '').trim(),
      accessLevel: String(item?.accessLevel || '').trim(),
      permalink: String(item?.permLink || '').trim(),
      source: 'AlgoTraffic',
      agency: 'ALDOT',
      state: 'Alabama',
      _state: 'AL',
    }, String(item?.id || name)));
  }
  return features;
}

function _buildIndianaCarsFeatures(raw) {
  const features = [];
  if (Array.isArray(raw)) {
    for (const item of raw) {
      const loc = item?.location || {};
      const lat = Number(loc?.latitude);
      const lon = Number(loc?.longitude);
      if (!Number.isFinite(lat) || !Number.isFinite(lon)) continue;

      const views = Array.isArray(item?.views) ? item.views : [];
      const videoView = views.find(v => String(v?.url || '').trim() && String(v?.type || '').toUpperCase() !== 'STILL_IMAGE') || views[0] || {};
      const m3u8Url = String(videoView?.url || '').trim();
      const imageUrl = String(videoView?.videoPreviewUrl || '').trim();
      if (!m3u8Url && !imageUrl) continue;

      const title = String(item?.name || '').trim() || 'Indiana Traffic Camera';
      const route = String(loc?.routeId || '').trim();
      const cityRef = String(loc?.cityReference || '').trim();
      const locationText = [route, cityRef].filter(Boolean).join(' @ ') || cityRef || route || title;

      features.push(_cameraPointFeature(lon, lat, {
        id: item?.id ?? '',
        name: title,
        title,
        location: locationText,
        route: route,
        city: cityRef,
        image_url: imageUrl,
        m3u8_url: m3u8Url,
        source: 'INDOT',
        agency: String(item?.cameraOwner?.name || 'INDOT').trim() || 'INDOT',
        state: 'Indiana',
        _state: 'IN',
      }, String(item?.id || title)));
    }
    return features;
  }

  const srcFeatures = Array.isArray(raw?.features) ? raw.features : [];
  for (const f of srcFeatures) {
    const c = _cameraCoords(f);
    if (!c) continue;
    const p = f?.properties || {};
    const title = String(p.title || p.name || '').trim();
    const imageUrl = String(p.image_url || p.imageUrl || '').trim();
    const m3u8Url = String(p.m3u8_url || p.m3u8 || '').trim();
    if (!imageUrl && !m3u8Url) continue;
    features.push(_cameraPointFeature(c[0], c[1], {
      ...p,
      name: title || 'Indiana Traffic Camera',
      title: title || 'Indiana Traffic Camera',
      image_url: imageUrl,
      m3u8_url: m3u8Url,
      source: 'INDOT',
      agency: 'INDOT',
      state: 'Indiana',
      _state: 'IN',
    }, String(f?.id || p?.id || p?.m3u8_url || p?.image_url || title)));
  }
  return features;
}

function _buildIowa511Features(raw) {
  const srcFeatures = Array.isArray(raw?.features) ? raw.features : [];
  const features = [];
  for (const f of srcFeatures) {
    const c = _cameraCoords(f);
    if (!c) continue;
    const p = f?.properties || {};
    const views = Array.isArray(p.views) ? p.views : [];
    const preferredView = views.find(v => String(v?.m3u8_url || '').trim())
      || views.find(v => String(v?.jpg_url || '').trim())
      || views[0]
      || {};
    const jpgList = Array.isArray(p.jpg_urls) ? p.jpg_urls : [];
    const hlsList = Array.isArray(p.m3u8_urls) ? p.m3u8_urls : [];
    const imageUrl = String(
      preferredView?.jpg_url
      || jpgList.find(url => String(url || '').trim())
      || ''
    ).trim();
    const m3u8Url = String(
      preferredView?.m3u8_url
      || hlsList.find(url => String(url || '').trim())
      || ''
    ).trim();
    if (!imageUrl && !m3u8Url) continue;

    const title = String(p.title || p.name || '').trim() || 'Iowa Traffic Camera';
    const serializedViews = views.length ? JSON.stringify(views) : '';
    features.push(_cameraPointFeature(c[0], c[1], {
      ...p,
      id: String(p.camera_uri || p.id || '').trim(),
      camera_uri: String(p.camera_uri || '').trim(),
      name: title,
      title,
      location: title,
      image_url: imageUrl,
      snapshot_url: imageUrl,
      m3u8_url: m3u8Url,
      stream_url: m3u8Url,
      jpg_urls: JSON.stringify(jpgList),
      m3u8_urls: JSON.stringify(hlsList),
      views: serializedViews,
      source: 'Iowa 511',
      agency: 'Iowa DOT',
      state: 'Iowa',
      _state: 'IA',
    }, String(f?.id || p?.camera_uri || imageUrl || m3u8Url || title)));
  }
  return features;
}

